within AES.Functions;

function hod "hour of day (0-23)"
  extends Modelica.Icons.Function;
  input Real t;
  input Real hour_start=0;
  input Real min_start=0;
  input Real sec_start=0;
  output Real y;
algorithm
  y := 1.0*(floor(Functions.sod(t,hour_start,min_start,sec_start)/3600));
end hod;

within AES.Functions;
function layer_fcf_conductivities "face-centres-face"
  extends Modelica.Icons.Function;
  input Real s[:];
  input Real lambda[:];
  output Real L[size(s,1) + 1];
protected
  Integer n;
algorithm
  n := size(s,1);
  L[1] := lambda[1];
  L[n + 1] := lambda[n];
  for i in 2:n loop
    L[i] := lambda[i - 1] * lambda[i]
            / (s[i - 1] * lambda[i] + s[i] * lambda[i - 1])
            * (s[i - 1] + s[i]);
  end for

  ;
end layer_fcf_conductivities;

within AES.Functions;

function sod "second of day (0-86399)"
  extends Modelica.Icons.Function;
  input Real t;
  input Real hour_start=0;
  input Real min_start=0;
  input Real sec_start=0;
  output Real y;
algorithm
  y := mod(t+3600*hour_start+60*min_start+sec_start,86400);
end sod;

within AES.Functions;

function sqrtReg "Symmetric square root approximation with finite derivative in zero"
  extends Modelica.Icons.Function;
  input Real x;
  input Real delta = 0.01 "Range of significant deviation from sqrt(x)";
  output Real y;
algorithm
  y := x / sqrt(sqrt(x * x + delta * delta))
  ;
end sqrtReg;

within AES.Functions;
function sqrtReg_der "Derivative of sqrtReg"
  extends Modelica.Icons.Function;
  input Real x;
  input Real delta = 0.01 "Range of significant deviation from sqrt(x)";
  input Real dx "Derivative of x";
  output Real dy;
algorithm
  dy := dx * 0.5 * (x * x + 2 * delta * delta) / (x * x + delta * delta) ^ 1.25;
end sqrtReg_der;

