within IDEAS.Fluid.Movers.BaseClasses.Characteristics;
function pressure
  "Pump or fan head away from the origin without correction for mover flow resistance"
  extends Modelica.Icons.Function;

  input Modelica.Units.SI.VolumeFlowRate V_flow "Volumetric flow rate";
  input Real r_N(unit="1") "Relative revolution, r_N=N/N_nominal";
  input Real d[:] "Derivatives of flow rate vs. pressure at the support points";
  input Modelica.Units.SI.PressureDifference dpMax(displayUnit="Pa")
    "Maximum pressure drop at nominal speed, for regularisation";
  input Modelica.Units.SI.VolumeFlowRate V_flow_max
    "Maximum flow rate at nominal speed, for regularisation";
  input IDEAS.Fluid.Movers.BaseClasses.Characteristics.flowParametersInternal per
    "Pressure performance data";

  output Modelica.Units.SI.PressureDifference dp(displayUnit="Pa")
    "Pressure raise";

protected
  constant Real delta = 0.05
    "Small number for r_N below which we don't care about the affinity laws";
  constant Real delta2 = delta/2 "= delta/2";
  Real r_R(unit="1") "Relative revolution, bounded below by delta";
  Integer i "Integer to select data interval";
  Modelica.Units.SI.VolumeFlowRate rat "Ratio of V_flow/r_R";

algorithm
  // For r_N < delta, we restrict r_N in the term V_flow/r_N.
  // This is done using a cubic spline in a region 0.75*delta < r_N < 1.25*r_N
  // We call this restricted value r_R
  if r_N > delta then
    r_R :=r_N;
  elseif r_N < 0 then
    r_R := delta2;
  else
    // Restrict r_N using a spline
    r_R :=Modelica.Fluid.Utilities.cubicHermite(
      x=r_N,
      x1=0,
      x2=delta,
      y1=delta2,
      y2=delta,
      y1d=0,
      y2d=1);
  end if;

  i :=1;

  rat := V_flow/r_R;
  for j in 1:size(d, 1)-1 loop
    if rat > per.V_flow[j] then
      i := j;
    end if;
  end for;
  // In the assignment below,
  // dp -> 0 as r_N -> 0 quadratically, because rat is bounded
  // by the above regularization
  if r_N>=0 then
    dp:=r_N^2*IDEAS.Utilities.Math.Functions.cubicHermiteLinearExtrapolation(
              x=rat,
              x1=per.V_flow[i],
              x2=per.V_flow[i + 1],
              y1=per.dp[i],
              y2=per.dp[i + 1],
              y1d=d[i],
              y2d=d[i+1]);
  else
    dp:=-r_N^2*(dpMax-dpMax/V_flow_max*V_flow);
  end if
;
end pressure;

within IDEAS.Fluid.Examples.Performance.PressureDrop;
model SeriesParallelDp
  "Combined series and parallel connection with prescribed pressure difference and non-optimised parameters"
  extends Modelica.Icons.Example;
  package Medium = IDEAS.Media.Air;
  parameter Integer nRes(min=2) = 10 "Number of resistances";
  parameter Modelica.Units.SI.PressureDifference dp_nominal=1
    "Pressure drop at nominal mass flow rate";
  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal=1
    "Nominal mass flow rate";

  Sources.Boundary_pT sou(
    redeclare package Medium = Medium,
    nPorts=1,
    use_p_in=true) "Pressure boundary condition"
    ;
  Modelica.Blocks.Sources.Pulse pulse_m_flow(
    period=1,
    offset=Medium.p_default,
    amplitude=dp_nominal)
              "Pulse input for flow rate"
    ;
  FixedResistances.PressureDrop[nRes] resParallel(
    redeclare each package Medium = Medium,
    each m_flow_nominal=m_flow_nominal,
    each allowFlowReversal=false,
    dp_nominal={dp_nominal*(1 + mod(i, 3)) for i in 1:nRes},
    each from_dp=false) "Parallel pressure drop components"
    ;
  Sources.Boundary_pT sin(
    redeclare package Medium = Medium, nPorts=1)
      "Pressure boundary condition"
      ;
  FixedResistances.PressureDrop res2(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    dp_nominal=dp_nominal,
    from_dp=false)
                  "Series pressure drop component"
    ;
equation
  for i in 1:nRes-1 loop
    connect(resParallel[i].port_a, resParallel[i + 1].port_a)
      ;
    connect(resParallel[i].port_b, resParallel[i + 1].port_b)
      ;
  end for;
  connect(resParallel[1].port_a, sou.ports[1])
    ;

  connect(resParallel[nRes].port_b, res2.port_a)
    ;
  connect(res2.port_b, sin.ports[1])
    ;
  connect(pulse_m_flow.y, sou.p_in)

   ;
end SeriesParallelDp;

within IDEAS.BoundaryConditions.SolarGeometry.BaseClasses;
block ZenithAngle "Zenith angle"
  extends Modelica.Blocks.Icons.Block;
  Modelica.Blocks.Interfaces.RealInput solHouAng(quantity="Angle", unit="rad")
    "Solar hour angle"
    ;
  Modelica.Blocks.Interfaces.RealInput decAng(quantity="Angle", unit="rad")
    "Solar declination angle"
    ;
  Modelica.Blocks.Interfaces.RealOutput zen(
    final quantity="Angle",
    final unit="rad",
    displayUnit="deg") "Zenith angle"
    ;
  Modelica.Blocks.Interfaces.RealInput lat(
    quantity="Angle",
    unit="rad",
    displayUnit="deg") "Latitude"
    ;
equation
  zen =  Modelica.Math.acos(Modelica.Math.cos(lat)*Modelica.Math.cos(decAng)*
    Modelica.Math.cos(solHouAng) + Modelica.Math.sin(lat)*Modelica.Math.sin(
    decAng)) "(A4.8)"
  ;
end ZenithAngle;

