model ThermalZones
  "Declaration of an FMU that exports multiple thermal zones"
  extends IDEAS.Fluid.FMI.ExportContainers.ThermalZones(
    redeclare final package Medium = MediumA,
    nPorts =  3,
    nZon = 2);

  replaceable package MediumA = IDEAS.Media.Air "Medium for air";

  parameter Modelica.Units.SI.Volume V=6*10*3 "Room volume";

  /////////////////////////////////////////////////////////
  // Air temperatures at design conditions
  parameter Modelica.Units.SI.Temperature TASup_nominal=273.15 + 18
    "Nominal air temperature supplied to room";
  parameter Modelica.Units.SI.Temperature TRooSet=273.15 + 24
    "Nominal room air temperature";
  parameter Modelica.Units.SI.Temperature TOut_nominal=273.15 + 30
    "Design outlet air temperature";

  /////////////////////////////////////////////////////////
  // Cooling loads and air mass flow rates
  parameter Modelica.Units.SI.HeatFlowRate QRooInt_flow=1000
    "Internal heat gains of the room";
  parameter Modelica.Units.SI.HeatFlowRate QRooC_flow_nominal=-QRooInt_flow -
      10E3/30*(TOut_nominal - TRooSet) "Nominal cooling load of the room";
  parameter Modelica.Units.SI.MassFlowRate mA_flow_nominal=1.3*
      QRooC_flow_nominal/1006/(TASup_nominal - TRooSet)
    "Nominal air mass flow rate, increased by factor 1.3 to allow for recovery after temperature setback";

  BoundaryConditions.WeatherData.ReaderTMY3 weaDat(
    pAtmSou=IDEAS.BoundaryConditions.Types.DataSource.Parameter,
    TDryBul=TOut_nominal,
    filNam=Modelica.Utilities.Files.loadResource("modelica://IDEAS/Resources/weatherdata/USA_IL_Chicago-OHare.Intl.AP.725300_TMY3.mos"),
    TDryBulSou=IDEAS.BoundaryConditions.Types.DataSource.File,
    computeWetBulbTemperature=false) "Weather data reader"
    ;
  BoundaryConditions.WeatherData.Bus weaBus "Weather data bus"
    ;
  Modelica.Blocks.Interfaces.RealOutput TOut(final unit="K")
    "Outdoor temperature" ;
  Modelica.Blocks.Interfaces.RealOutput TRad1(final unit="K")
    "Radiative temperature"
    ;
  Modelica.Blocks.Interfaces.RealOutput TRad2(final unit="K")
    "Radiative temperature"
    ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedTemperature TAirOut
    "Outside air temperature"
    ;
  Modelica.Thermal.HeatTransfer.Components.ThermalConductor theCon1(G=10000/30)
    "Thermal conductance with the ambient"
    ;
  Modelica.Thermal.HeatTransfer.Sources.FixedHeatFlow preHea1(Q_flow=
        QRooInt_flow) "Prescribed heat flow for internal gains"
    ;
  MixingVolumes.MixingVolume vol1(
    redeclare package Medium = MediumA,
    m_flow_nominal=mA_flow_nominal,
    V=V,
    mSenFac=3,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    nPorts=3) "Room volume"
    ;
  Modelica.Thermal.HeatTransfer.Components.ThermalConductor theCon2(G=10000/30)
    "Thermal conductance with the ambient"
    ;
  Modelica.Thermal.HeatTransfer.Sources.FixedHeatFlow preHea2(Q_flow=
        QRooInt_flow) "Prescribed heat flow for internal gains"
    ;
  MixingVolumes.MixingVolume vol2(
    redeclare package Medium = MediumA,
    m_flow_nominal=mA_flow_nominal,
    V=V,
    mSenFac=3,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    nPorts=3) "Room volume"
    ;
  Sensors.MassFlowRate senMasFlo[nPorts](redeclare final package Medium = MediumA)
    "Mass flow rate sensor to connect thermal adapter with thermal zone."
    ;
  Sensors.MassFlowRate senMasFlo1[nPorts](
                                         redeclare final package Medium = MediumA)
    "Mass flow rate sensor to connect thermal adapter with thermal zone."
    ;
  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor temSen1
    "Temperature sensor (that approximates the radiative temperature by the air temperature)"
    ;
  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor temSen2
    "Temperature sensor (that approximates the radiative temperature by the air temperature)"
    ;

equation
  connect(weaDat.weaBus,weaBus)  ;
  connect(theCon1.port_b, vol1.heatPort) ;
  connect(preHea1.port, vol1.heatPort) ;
  connect(TAirOut.T, weaBus.TDryBul) ;
  connect(TAirOut.port, theCon1.port_a)
    ;

  connect(TOut, weaBus.TDryBul) ;
  connect(theCon2.port_b, vol2.heatPort) ;
  connect(preHea2.port, vol2.heatPort) ;
  connect(TAirOut.port, theCon2.port_a) ;
  connect(vol1.heatPort, theZonAda[1].heaPorAir) ;
  connect(vol2.heatPort, theZonAda[2].heaPorAir) ;
  connect(theZonAda[2].ports, senMasFlo1.port_a) ;
  connect(senMasFlo.port_a, theZonAda[1].ports) ;
  connect(senMasFlo1.port_b, vol2.ports[1:3]) ;
  connect(senMasFlo.port_b, vol1.ports[1:3]) ;
  connect(temSen1.port, vol1.heatPort) ;
  connect(temSen2.port, vol2.heatPort) ;
  connect(temSen1.T, TRad1)
    ;
  connect(temSen2.T, TRad2) 
    ;
end ThermalZones;

