protected
  Modelica.Blocks.Interfaces.RealInput Te_internal(unit="K");
  Modelica.Units.SI.Temperature TSha = Te_internal + (H - HSha) * epsSw_shading /hSha
    "Simplified static heat balance to compute the shading object temperature";
equation
