  Modelica.Blocks.Interfaces.RealVectorInput[nin] u "Variables that are saved"
     ;
protected
  parameter String insNam = getInstanceName() "Instance name";
  IDEAS.Utilities.IO.Files.BaseClasses.JSONWriterObject jsonWri=
      IDEAS.Utilities.IO.Files.BaseClasses.JSONWriterObject(
        insNam,
        fileName,
        outputTime==IDEAS.Utilities.IO.Files.BaseClasses.OutputTime.Terminal,
        varKeys)
    "File writer object";
equation
  if outputTime==IDEAS.Utilities.IO.Files.BaseClasses.OutputTime.Terminal then
    IDEAS.Utilities.IO.Files.BaseClasses.cacheVals(jsonWri, u);
  end if;

  if outputTime==IDEAS.Utilities.IO.Files.BaseClasses.OutputTime.Initial then
    when initial() then
      IDEAS.Utilities.IO.Files.BaseClasses.writeJSON(jsonWri, u);
    end when;
  end if;

  if outputTime==IDEAS.Utilities.IO.Files.BaseClasses.OutputTime.Custom then
    when time>=customTime then
      IDEAS.Utilities.IO.Files.BaseClasses.writeJSON(jsonWri, u);
    end when;
  end if

  ;
end JSONWriter;

