    "Vertical distance between side fin and window"
    ;

  Real fraSunDir(
    final min=0,
    final max=1,
    final unit="1")
    "Fraction of window area exposed to the sun";
  Real fraSunDifSky(
    final min=0,
    final max=1,
    final unit="1")
    "Fraction of window area exposed to diffuse sun light";

  IDEAS.Buildings.Components.Shading.Overhang overhang(
    A_glazing=A_glazing,
    A_frame=A_frame,
    inc=inc,
    Tenv_nom=Tenv_nom,
    epsSw_frame=epsSw_frame,
    epsLw_frame=epsLw_frame,
    epsLw_glazing=epsLw_glazing,
    epsSw_shading=epsSw_shading,
    g_glazing=g_glazing,
    linCon=linCon,
    haveFrame=haveFrame,
    linRad=linRad,
    final azi=azi,
    haveBoundaryPorts=false,
    hSha=hSha,
    final hWin=hWin,
    final wWin=wWin,
    final wLeft=wLeft,
    final wRight=wRight,
    final dep=ovDep,
    final gap=ovGap)
    ;
  IDEAS.Buildings.Components.Shading.SideFins sideFins(
    A_glazing=A_glazing,
    A_frame=A_frame,
    inc=inc,
    Tenv_nom=Tenv_nom,
    epsSw_frame=epsSw_frame,
    epsLw_frame=epsLw_frame,
    epsLw_glazing=epsLw_glazing,
    epsSw_shading=epsSw_shading,
    g_glazing=g_glazing,
    linCon=linCon,
    haveFrame=haveFrame,
    linRad=linRad,
    final azi=azi,
    haveBoundaryPorts=haveBoundaryPorts,
    hSha=hSha,
    final hWin=hWin,
    final wWin=wWin,
    final hFin=hFin,
    final dep=finDep,
    final gap=finGap)
    ;
protected
  final parameter Modelica.Units.SI.Area aWin=hWin*wWin "Window area";
initial equation

    assert(ovDep > 0, "The depth of the overhang must be larger than zero. If this is not the case, just use Shading.SideFins");
    assert(finDep > 0, "The depth of the side fins must be larger than zero. If this is not the case, just use Shading.Overhang");

equation
  fraSunDir = overhang.fraSunDir*sideFins.fraSunDir;
  fraSunDifSky = overhang.fraSunDifSky*sideFins.fraSunDif;
  HShaDirTil = HDirTil * fraSunDir;
  HShaSkyDifTil = HSkyDifTil * fraSunDifSky;
  HShaGroDifTil = HGroDifTil * sideFins.fraSunDif;

  connect(angInc, iAngInc) ;
  connect(overhang.angZen, angZen) ;
  connect(sideFins.angInc, angInc) ;
  connect(sideFins.angZen, angZen) ;
  connect(sideFins.angAzi, angAzi) ;
  connect(overhang.angAzi, angAzi) ;
  connect(overhang.angInc, angInc) ;
  connect(HDirTil, overhang.HDirTil) ;
  connect(HDirTil, sideFins.HDirTil) ;
  connect(HSkyDifTil, overhang.HSkyDifTil) ;
  connect(HSkyDifTil, sideFins.HSkyDifTil) ;
  connect(HGroDifTil, overhang.HGroDifTil) ;
  connect(HGroDifTil, sideFins.HGroDifTil) ;
  connect(sideFins.port_frame, port_frame) ;
  connect(sideFins.port_glazing, port_glazing) ;
  connect(Te, sideFins.Te) ;
  connect(hForcedConExt, sideFins.hForcedConExt) ;
  connect(TEnv, sideFins.TEnv) ;
  connect(TDryBul, sideFins.TDryBul) 
  ;
end Box;

