model ChimneyShaftWithVolume
  "Model with chimney effect and a dynamic model of a shaft"
  extends Modelica.Icons.Example;
  package Medium = IDEAS.Media.Air;

  IDEAS.Fluid.MixingVolumes.MixingVolume roo(
    V=2.5*5*5,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    T_start=273.15 + 20,
    redeclare package Medium = Medium,
    m_flow_nominal=0.05,
    p_start=101325,
    nPorts=3) "Air volume of a room"
    ;
  IDEAS.Airflow.Multizone.Orifice oriChiTop(
    m=0.5,
    redeclare package Medium = Medium,
    A=0.01) "Orifice at top"
            ;
  IDEAS.Fluid.Sources.MassFlowSource_T boundary(
    redeclare package Medium = Medium,
    use_m_flow_in=true,
    T=293.15,
    nPorts=1) "Mass flow rate boundary condition"
    ;
  IDEAS.Fluid.Sources.Boundary_pT bou0(
    redeclare package Medium = Medium,
    T=273.15,
    nPorts=2) "Pressure boundary condition"
              ;
  IDEAS.Airflow.Multizone.Orifice oriBot(
    m=0.5,
    redeclare package Medium = Medium,
    A=0.01) "Orifice"
            ;
  Modelica.Blocks.Sources.CombiTimeTable mRoo_flow(tableOnFile=false, table=[0,
        0.05; 600,0.05; 601,0; 1800,0; 1801,-0.05; 2400,-0.05; 2401,0; 3600,0])
    "Mass flow into and out of room to fill the medium column with air of different temperature"
    ;
  MediumColumn staOut(
    redeclare package Medium = Medium,
    densitySelection=IDEAS.Airflow.Multizone.Types.densitySelection.fromTop,
    h=1.5) "Model for stack effect outside the room"
    ;
  IDEAS.Airflow.Multizone.Orifice oriChiBot(
    m=0.5,
    redeclare package Medium = Medium,
    A=0.01) "Orifice at bottom"
            ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow preHea
    "Prescribed heat flow" ;
  Modelica.Blocks.Continuous.LimPID con(
    Td=10,
    yMax=1,
    yMin=-1,
    Ti=60,
    controllerType=Modelica.Blocks.Types.SimpleController.P,
    k=5) "Controller to maintain volume temperature"
    ;
  Modelica.Blocks.Sources.Constant TSet(k=293.15) "Temperature set point"
    ;
  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor temSen
    "Temperature sensor" ;
  Modelica.Blocks.Math.Gain gain(k=3000) "Gain for heat flow rate"
    ;
  IDEAS.Airflow.Multizone.MediumColumnDynamic sha(
    redeclare package Medium = Medium,
    V=3,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial)
    "Shaft of chimney"
    ;
  MediumColumn staIn(
    redeclare package Medium = Medium,
    densitySelection=IDEAS.Airflow.Multizone.Types.densitySelection.fromBottom,
    h=1.5) "Model for stack effect inside the room"
    ;

equation
  connect(TSet.y, con.u_s) ;
  connect(temSen.T, con.u_m) ;
  connect(gain.u, con.y) ;
  connect(gain.y, preHea.Q_flow) ;
  connect(sha.port_a, oriChiTop.port_a) ;
  connect(sha.port_b, oriChiBot.port_b) ;
  connect(staOut.port_b, oriBot.port_a) ;
  connect(preHea.port, roo.heatPort) ;
  connect(roo.heatPort, temSen.port) ;
  connect(bou0.ports[1], oriChiTop.port_b)  ;
  connect(bou0.ports[2], staOut.port_a) ;
  connect(oriBot.port_b, staIn.port_a)   ;
  connect(mRoo_flow.y[1], boundary.m_flow_in) ;
  connect(boundary.ports[1], roo.ports[1]) ;
  connect(roo.ports[2], staIn.port_b)   ;
  connect(roo.ports[3], oriChiBot.port_a) 
  ;
end ChimneyShaftWithVolume;

