within IDEAS.Fluid.HeatExchangers.BaseClasses;
function epsilon_C
  "Computes heat exchanger effectiveness for given capacity flow rates and heat exchanger flow regime"
  input Modelica.Units.SI.ThermalConductance UA "UA value";
  input Modelica.Units.SI.ThermalConductance C1_flow
    "Enthalpy flow rate medium 1";
  input Modelica.Units.SI.ThermalConductance C2_flow
    "Enthalpy flow rate medium 2";
  input Integer flowRegime
    "Heat exchanger flow regime, see  IDEAS.Fluid.Types.HeatExchangerFlowRegime";
  input Modelica.Units.SI.ThermalConductance CMin_flow_nominal
    "Minimum enthalpy flow rate at nominal condition";
  input Modelica.Units.SI.ThermalConductance CMax_flow_nominal
    "Maximum enthalpy flow rate at nominal condition";
  input Real delta = 1E-3 "Small value used for smoothing";
  output Real eps(min=0, max=1) "Heat exchanger effectiveness";

protected
  Modelica.Units.SI.ThermalConductance deltaCMin
    "Small number for capacity flow rate";
  Modelica.Units.SI.ThermalConductance deltaCMax
    "Small number for capacity flow rate";
  Modelica.Units.SI.ThermalConductance CMin_flow "Minimum capacity flow rate";
  Modelica.Units.SI.ThermalConductance CMax_flow "Maximum capacity flow rate";
  Modelica.Units.SI.ThermalConductance CMinNZ_flow
    "Minimum capacity flow rate, bounded away from zero";
  Modelica.Units.SI.ThermalConductance CMaxNZ_flow
    "Maximum capacity flow rate, bounded away from zero";
  Real gaiEps(min=0, max=1)
    "Gain used to force UA to zero for very small flow rates";
  Real gaiNTU(min=1E-10, max=1)
    "Gain used to force NTU to a number slightly above zero for very small flow rates. Because NTU is used in NTU^-(0.22), it must not be zero.";
  Real NTU "Number of transfer units";
  Real Z(min=0, max=1) "Ratio of capacity flow rate (CMin/CMax)";

algorithm
  deltaCMin := delta*CMin_flow_nominal;
  deltaCMax := delta*CMax_flow_nominal;
  // effectiveness
  CMin_flow :=IDEAS.Utilities.Math.Functions.smoothMin(
    C1_flow,
    C2_flow,
    deltaCMin/4);
  CMax_flow :=IDEAS.Utilities.Math.Functions.smoothMax(
    C1_flow,
    C2_flow,
    deltaCMax/4);
  // CMin and CMax, constrained to be non-zero to compute eps-NTU-Z relationship
  CMinNZ_flow :=IDEAS.Utilities.Math.Functions.smoothMax(
    CMin_flow,
    deltaCMin,
    deltaCMin/4);
  CMaxNZ_flow :=IDEAS.Utilities.Math.Functions.smoothMax(
    CMax_flow,
    deltaCMax,
    deltaCMax/4);
  Z := CMin_flow/CMaxNZ_flow+1E-10*deltaCMin;
  // Gain that goes to zero as CMin_flow gets below deltaCMin
  // This is needed to allow zero flow
  gaiEps := IDEAS.Utilities.Math.Functions.spliceFunction(
           pos=1,
           neg=0,
           x=CMin_flow-deltaCMin,
           deltax=deltaCMin/2);
  gaiNTU := IDEAS.Utilities.Math.Functions.spliceFunction(
           pos=1,
           neg=delta,
           x=CMin_flow-deltaCMin,
           deltax=deltaCMin/2);

  NTU := gaiNTU*UA/CMinNZ_flow;
  eps := gaiEps*IDEAS.Fluid.HeatExchangers.BaseClasses.epsilon_ntuZ(
                  NTU=NTU,
                  Z=Z,
                  flowRegime=flowRegime)

  ;
end epsilon_C;

within IDEAS.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors;
function infiniteLineSource
  "Infinite line source model for borehole heat exchangers"
  extends Modelica.Icons.Function;

  input Real t "Time";
  input Real aSoi "Ground thermal diffusivity";
  input Real dis "Radial distance between borehole axes";

  output Real h_ils "Thermal response factor of borehole 1 on borehole 2";

algorithm
  h_ils := if t > 0.0 then
              IDEAS.Utilities.Math.Functions.exponentialIntegralE1(dis^2/(4*aSoi*t))
           else
              0.0
;
end infiniteLineSource;

within IDEAS.Fluid.Geothermal.Borefields.BaseClasses.Boreholes.BaseClasses.Examples;
model InternalHEXTwoUTube
  "Comparison of the effective borehole thermal resistance from the thermal network of Bauer et al. with the resistance calculated by doubleUTubeResistances (ref)"
  extends Modelica.Icons.Example;

  parameter Integer nSeg(min=1) = 10
    "Number of segments to use in vertical discretization of the boreholes";
  parameter Modelica.Units.SI.Length hSeg=borFieDat.conDat.hBor/nSeg
    "Length of the internal heat exchanger";

  package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater;
  IDEAS.Fluid.Geothermal.Borefields.BaseClasses.Boreholes.BaseClasses.InternalHEXTwoUTube
    intHex(
    TFlu_start(displayUnit="K") = 285.15,
    redeclare package Medium = Medium,
    hSeg=hSeg,
    dp1_nominal=10,
    dp2_nominal=10,
    dp3_nominal=10,
    dp4_nominal=10,
    dynFil=true,
    borFieDat=borFieDat,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    TGro_start(displayUnit="K") = 285.15,
    m1_flow_nominal=borFieDat.conDat.mBor_flow_nominal/2,
    m2_flow_nominal=borFieDat.conDat.mBor_flow_nominal/2,
    m3_flow_nominal=borFieDat.conDat.mBor_flow_nominal/2,
    m4_flow_nominal=borFieDat.conDat.mBor_flow_nominal/2)
    ;

  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature fixedTemperature(T=273.15
         + 12)
    ;
  IDEAS.Fluid.Sources.MassFlowSource_T boundary(nPorts=2,
    redeclare package Medium = Medium,
    m_flow=borFieDat.conDat.mBor_flow_nominal,
    T=293.15)
    ;
  IDEAS.Fluid.Sources.MassFlowSource_T boundary1(nPorts=2,
    redeclare package Medium = Medium,
    m_flow=borFieDat.conDat.mBor_flow_nominal,
    T=288.15)
    ;
  IDEAS.Fluid.Sources.Boundary_pT bou(nPorts=4, redeclare package Medium = Medium)
    ;
  Real Rb_sim(unit="(m.K)/W") = ((senTem.T + senTem1.T + senTem2.T + senTem3.T)/4 - intHex.port_wall.T)/max(-intHex.port_wall.Q_flow / hSeg,1);
  IDEAS.Fluid.Sensors.TemperatureTwoPort senTem(redeclare package Medium =
        Medium, m_flow_nominal=borFieDat.conDat.mBor_flow_nominal)
    ;
  IDEAS.Fluid.Sensors.TemperatureTwoPort senTem1(redeclare package Medium =
        Medium, m_flow_nominal=borFieDat.conDat.mBor_flow_nominal)
    ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=Rb_sim)
    ;
  Modelica.Blocks.Sources.Constant Rb_ref(k=0.0443802)
    ;
  Modelica.Blocks.Math.Add error(k2=-1)
    ;
  IDEAS.Fluid.Sensors.TemperatureTwoPort senTem2(redeclare package Medium =
        Medium, m_flow_nominal=borFieDat.conDat.mBor_flow_nominal)
    ;
  IDEAS.Fluid.Sensors.TemperatureTwoPort senTem3(redeclare package Medium =
        Medium, m_flow_nominal=borFieDat.conDat.mBor_flow_nominal)
    ;
  parameter IDEAS.Fluid.Geothermal.Borefields.Data.Borefield.Example
    borFieDat(conDat=
        IDEAS.Fluid.Geothermal.Borefields.Data.Configuration.Example(
        borCon=IDEAS.Fluid.Geothermal.Borefields.Types.BoreholeConfiguration.DoubleUTubeParallel,
        use_Rb=false))
    "Borefield data"
    ;
equation

  connect(fixedTemperature.port, intHex.port_wall)
    ;
  connect(boundary.ports[1], intHex.port_a1)
    ;
  connect(bou.ports[1], senTem.port_b) ;
  connect(senTem.port_a, intHex.port_b1)
    ;
  connect(realExpression.y, error.u1) ;
  connect(Rb_ref.y, error.u2) ;

  connect(boundary.ports[2], intHex.port_a3) ;
  connect(boundary1.ports[1], intHex.port_a4)
    ;
  connect(boundary1.ports[2], intHex.port_a2) ;
  connect(intHex.port_b2, senTem1.port_a) ;
  connect(senTem1.port_b, bou.ports[2])
    ;
  connect(intHex.port_b4, senTem2.port_a) ;
  connect(senTem2.port_b, bou.ports[3]) ;
  connect(intHex.port_b3, senTem3.port_a) ;
  connect(senTem3.port_b, bou.ports[4]) 
  ;
end InternalHEXTwoUTube;

