within IDEAS.Fluid.Actuators.Valves;
model TwoWayEqualPercentage
  "Two way valve with equal percentage flow characteristics"
  extends BaseClasses.PartialTwoWayValveKv(
    phi=max(0.1*l, if homotopyInitialization then
        homotopy(actual=IDEAS.Fluid.Actuators.BaseClasses.equalPercentage(
        y_actual,
        R,
        l,
        delta0), simplified=l + y_actual*(1 - l)) else
        IDEAS.Fluid.Actuators.BaseClasses.equalPercentage(
        y_actual,
        R,
        l,
        delta0)));
  parameter Real R=50 "Rangeability, R=50...100 typically";
  parameter Real delta0=0.01
    "Range of significant deviation from equal percentage law";

initial equation
  // Since the flow model IDEAS.Fluid.BaseClasses.FlowModels.basicFlowFunction_m_flow computes
  // 1/k^2, the parameter l must not be zero.
  assert(l > 0, "Valve leakage parameter l must be bigger than zero.");
  assert(l < 1/R, "Wrong parameters in valve model.\n"
                + "  Rangeability R = " + String(R) + "\n"
                + "  Leakage flow l = " + String(l) + "\n"
                + "  Must have l < 1/R = " + String(1/R))
  ;
end TwoWayEqualPercentage;

within IDEAS.Media.Refrigerants.R410A;
function dPressureVap_dTemperature_Tv
  "Derivative of the Martin-Hou equation of state with regards to temperature"

  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  input Modelica.Units.SI.SpecificVolume v "Specific volume of refrigerant";
  output Real dpdT(
    final unit="Pa/K")
     "Derivative of pressure with regards to temperature";

protected
  Modelica.Units.SI.SpecificVolume v_abs "Smoothed specific volume";

algorithm
  v_abs := IDEAS.Utilities.Math.Functions.smoothMax(v, 1.01*b, 0.01*b);

  dpdT := R/(v_abs-b);
  for i in 1:size(A, 1) loop
    dpdT := dpdT + (B[i] - C[i]*k/TCri*Modelica.Math.exp(-k*T/TCri))/(v_abs - b)^(i+1);
  end for

;
end dPressureVap_dTemperature_Tv;

within IDEAS.Controls.ControlHeating.HeatingCurves;
block HeatingCurveFilter
  "Block to compute the supply and return set point of heating systems"

  /* 
  Model extended from Buildings library with a first order filter to 
  filter the ambient temperature
  */
  extends Modelica.Blocks.Icons.Block;

  parameter Real m=1.3 "Exponent for heat transfer";
  parameter Modelica.Units.SI.Temperature TSup_nominal "Supply temperature"
    ;
  parameter Modelica.Units.SI.Temperature TSupMin=273.15 + 30 if minSup
    "Minimum supply temperature if enabled" ;
  parameter Boolean minSup=true
    "= true, to set a lower bound on the supply temperature";
  parameter Modelica.Units.SI.Temperature TRet_nominal "Return temperature"
    ;
  parameter Modelica.Units.SI.Temperature TRoo_nominal=293.15
    "Room temperature" ;
  parameter Modelica.Units.SI.Temperature TOut_nominal "Outside temperature"
    ;

  parameter Boolean use_TRoo_in=false
    "Get the room temperature set point from the input connector" ;
  parameter Modelica.Units.SI.Temperature TRoo=293.15
    "Fixed value of room air temperature set point if use_TRoo_in=false"
    ;
  parameter Modelica.Units.SI.TemperatureDifference dTOutHeaBal=8
    "Offset for heating curve";
  parameter Modelica.Units.SI.Time timeFilter=86400
    "Time constant for filter on ambient temperature";
  Modelica.Blocks.Interfaces.RealInput TRoo_in(
    final quantity="ThermodynamicTemperature",
    final unit="K",
    displayUnit="degC",
    min=0) if use_TRoo_in "Room air temperature set point" ;

  Modelica.Blocks.Interfaces.RealInput TOut(
    final quantity="ThermodynamicTemperature",
    final unit="K",
    displayUnit="degC",
    min=0) "Outside temperature"
    ;
  Modelica.Blocks.Interfaces.RealOutput TSup(
    final quantity="ThermodynamicTemperature",
    final unit="K",
    displayUnit="degC",
    min=0) "Setpoint for supply temperature"
    ;
  Modelica.Blocks.Interfaces.RealOutput TRet(
    final quantity="ThermodynamicTemperature",
    final unit="K",
    displayUnit="degC",
    min=0) "Setpoint for return temperature"
    ;
  replaceable Modelica.Blocks.Interfaces.SISO filter ;
protected
  parameter Modelica.Units.SI.Temperature TOutOffSet_nominal=TOut_nominal +
      dTOutHeaBal
    "Effective outside temperature for heat transfer at nominal conditions (takes into account room heat gains)";

  Modelica.Blocks.Interfaces.RealInput TRoo_in_internal(
    final quantity="ThermodynamicTemperature",
    final unit="K",
    displayUnit="degC",
    min=0) "Needed to connect to conditional connector";
  Real qRel "Relative heat load = Q_flow/Q_flow_nominal";
  Modelica.Units.SI.Temperature TOutOffSet
    "Effective outside temperature for heat transfer (takes into account room heat gains)";
  Real TSup_internal "Internal variable for more readable code";
equation
  connect(TRoo_in, TRoo_in_internal);
  if not use_TRoo_in then
    TRoo_in_internal = TRoo;
  end if;
  TOutOffSet = filter.y + dTOutHeaBal;
  // Relative heating load, compared to nominal conditions
  qRel = max(0, (TRoo_in_internal - TOutOffSet)*IDEAS.Utilities.Math.Functions.inverseXRegularized(TRoo_nominal -TOutOffSet_nominal, 0.01));

  TSup_internal = TRoo_in_internal +
                  ((TSup_nominal + TRet_nominal)/2 - TRoo_nominal)*qRel^(1/m) + (TSup_nominal - TRet_nominal)/2*qRel;
  TSup = if minSup then max(TSupMin, TSup_internal) else TSup_internal;
  TRet = TSup - qRel*(TSup_nominal - TRet_nominal);
  connect(TOut, filter.u) 
  ;
end HeatingCurveFilter;

within IDEAS.Experimental.Electric.Photovoltaics.Components;
model PvVoltageCtrlGeneral_InputVGrid_2
  "Basic controller, with fixed shut down time, with RealInput for grid voltage"

  extends Modelica.Blocks.Icons.Block;

  parameter Real VMax=248;
  parameter Real timeOff=300;
  parameter Integer numPha=1
    "1 or 3, just indicates if it's a single or 3 phase PV system";

  discrete Real switch(start=1, fixed=true) "if 1, system is producing";

  Modelica.Blocks.Interfaces.RealInput PInit
    ;
  Modelica.Blocks.Interfaces.RealInput QInit
    ;
  Modelica.Blocks.Interfaces.RealOutput PFinal
    ;
  Modelica.Blocks.Interfaces.RealOutput QFinal
    ;

protected
  discrete Real restartTime(start=-1, fixed=true)
    "system is off until time>restartTime";

public
  Modelica.Blocks.Interfaces.RealInput VGrid
    ;
algorithm

  when VGrid > VMax then
    switch := 0;
    restartTime := time + timeOff;
  elsewhen time < restartTime then
    switch := 0;
    restartTime := pre(restartTime);
  elsewhen time >= restartTime and VGrid < VMax then
    restartTime := pre(restartTime);
    switch := 1;
  end when;

  PFinal := switch*PInit;
  QFinal := QInit

  ;
end PvVoltageCtrlGeneral_InputVGrid_2;

