    redeclare package Medium = Medium,
    wOpe=1,
    hOpe=2.2,
    dp_turbulent(displayUnit="Pa") = 0.01,
    CD=0.78,
    m=0.5)  constrainedby Fluid.Interfaces.PartialFourPortInterface
