    ;
  connect(souRev.T_in, T.y) ;
  connect(pIn.y, souRev.p_in) ;
  connect(X_w_in.y, souRev.X_w_in) ;
  connect(C.y, souRev.C_in) ;
  connect(TRev.y, conAirRevFlo.TAirZon) ;
  connect(X_w.y, conAirRevFlo.X_wZon) 
;
