model ScrollWaterToWater_Dynamic
  "Test model for scroll water to water heat pump"
  extends Modelica.Icons.Example;
  package Medium1 = IDEAS.Media.Water "Medium model";
  package Medium2 = IDEAS.Media.Water "Medium model";

  parameter Modelica.Units.SI.MassFlowRate m1_flow_nominal=0.47
