  parameter Modelica.Units.SI.MassFlowRate flowLoad=0.47
    "Mass flow rate on the evaporator side";

  IDEAS.Fluid.Sources.Boundary_pT sin2(
    redeclare package Medium = Medium2, nPorts=2) "Source side sink"
    ;
  IDEAS.Fluid.Sources.Boundary_pT sin1(
