          len2 = len2[j],
          burDep2 = burDep2[j],
          includeRealSource=false);
        h[i,j] = IDEAS.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors.finiteLineSource(
