model TraceSubstanceConservation
  "This test checks if trace substance mass flow rates are conserved"
  extends Modelica.Icons.Example;
  constant String substanceName="CO2";
  package Medium = IDEAS.Media.Air(extraPropertiesNames={substanceName});
  IDEAS.Fluid.Sources.MassFlowSource_h sou(
    redeclare package Medium = Medium,
    nPorts=1,
    m_flow=1,
    X={0.01,0.99},
    C=fill(0.001, Medium.nC)) "Air source with moisture and trace substances"
    ;

  IDEAS.Fluid.MixingVolumes.MixingVolumeMoistAir vol(
    redeclare package Medium = Medium,
    m_flow_nominal=1,
    V=1,
    nPorts=2,
    allowFlowReversal=false,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState)
    "Mixing volume for adding moisture"
    ;
  Modelica.Blocks.Sources.Constant mWatFlo(k=0.001) "Water mass flow rate "
    ;
  IDEAS.Fluid.Sensors.TraceSubstancesTwoPort senTraSubIn(
    redeclare package Medium = Medium,
    m_flow_nominal=1,
    tau=0,
    allowFlowReversal=false,
    substanceName=substanceName) "Measured inlet trace substance concentration"
    ;
  IDEAS.Fluid.Sensors.TraceSubstancesTwoPort senTraSubOut(
    redeclare package Medium = Medium,
    m_flow_nominal=1,
    tau=0,
    allowFlowReversal=false,
    substanceName=substanceName)
    "Measured outlet trace substance concentration"
    ;
  IDEAS.Fluid.Sources.Boundary_pT sin(redeclare package Medium = Medium,
      nPorts=1) "Air sink"
    ;
  Sensors.MassFlowRate senMasFloIn(redeclare package Medium = Medium,
      allowFlowReversal=false) "Fluid mass flow rate at inlet"
    ;
  Sensors.MassFlowRate senMasFloOut(redeclare package Medium = Medium,
      allowFlowReversal=false) "Fluid mass flow rate at outlet"
    ;
  Modelica.Blocks.Math.Product CfloIn "Trace substance mass flow rate at inlet"
    ;
  Modelica.Blocks.Math.Product CfloOut
    "Trace substance mass flow rate at outlet" ;
equation
  connect(mWatFlo.y, vol.mWat_flow) ;
  connect(sou.ports[1], senTraSubIn.port_a) ;
  connect(senTraSubIn.port_b, senMasFloIn.port_a) ;
  connect(senMasFloIn.port_b, vol.ports[1]) ;
  connect(sin.ports[1], senMasFloOut.port_b) ;
  connect(senMasFloOut.port_a, senTraSubOut.port_b) ;
  connect(CfloIn.u2, senTraSubIn.C) ;
  connect(CfloIn.u1, senMasFloIn.m_flow) ;
  connect(CfloOut.u1, senMasFloOut.m_flow) ;
  connect(CfloOut.u2, senTraSubOut.C) ;
  connect(vol.ports[2], senTraSubOut.port_a) 
  ;
end TraceSubstanceConservation;

within IDEAS.Fluid.Chillers.Examples;
model Carnot_y "Test model for chiller based on Carnot_y efficiency"
  extends Modelica.Icons.Example;
 package Medium1 = IDEAS.Media.Water "Medium model";
 package Medium2 = IDEAS.Media.Water "Medium model";

  parameter Modelica.Units.SI.Power P_nominal=10E3
    "Nominal compressor power (at y=1)";
  parameter Modelica.Units.SI.TemperatureDifference dTEva_nominal=-10
    "Temperature difference evaporator outlet-inlet";
  parameter Modelica.Units.SI.TemperatureDifference dTCon_nominal=10
    "Temperature difference condenser outlet-inlet";
  parameter Real COPc_nominal = 3 "Chiller COP";

  parameter Modelica.Units.SI.MassFlowRate m2_flow_nominal=-P_nominal*
      COPc_nominal/dTEva_nominal/4200
    "Nominal mass flow rate at chilled water side";
  parameter Modelica.Units.SI.MassFlowRate m1_flow_nominal=m2_flow_nominal*(
      COPc_nominal + 1)/COPc_nominal
    "Nominal mass flow rate at condenser water wide";

  IDEAS.Fluid.Chillers.Carnot_y chi(
    redeclare package Medium1 = Medium1,
    redeclare package Medium2 = Medium2,
    P_nominal=P_nominal,
    dTEva_nominal=dTEva_nominal,
    dTCon_nominal=dTCon_nominal,
    use_eta_Carnot_nominal=true,
    etaCarnot_nominal=0.3,
    dp1_nominal=6000,
    dp2_nominal=6000,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    show_T=true,
    T1_start=303.15,
    T2_start=278.15) "Chiller model"
    ;
  IDEAS.Fluid.Sources.MassFlowSource_T sou1(nPorts=1,
    redeclare package Medium = Medium1,
    use_T_in=true,
    m_flow=m1_flow_nominal,
    T=298.15)
    ;
  IDEAS.Fluid.Sources.MassFlowSource_T sou2(nPorts=1,
    redeclare package Medium = Medium2,
    use_T_in=true,
    m_flow=m2_flow_nominal,
    T=291.15)
    ;
  IDEAS.Fluid.Sources.Boundary_pT sin1(
    nPorts=1,
    redeclare package Medium = Medium1)
    ;
  IDEAS.Fluid.Sources.Boundary_pT sin2(
    nPorts=1,
    redeclare package Medium = Medium2)
    ;
  Modelica.Blocks.Sources.Ramp uCom(
    height=-1,
    duration=60,
    offset=1,
    startTime=1800) "Compressor control signal"
    ;
  Modelica.Blocks.Sources.Ramp TCon_in(
    height=10,
    duration=60,
    offset=273.15 + 20,
    startTime=60) "Condenser inlet temperature"
    ;
  Modelica.Blocks.Sources.Ramp TEva_in(
    height=10,
    duration=60,
    startTime=900,
    offset=273.15 + 15) "Evaporator inlet temperature"
    ;
equation
  connect(sou1.ports[1], chi.port_a1)    ;
  connect(sou2.ports[1], chi.port_a2)    ;
  connect(chi.port_b1, sin1.ports[1])    ;
  connect(sin2.ports[1], chi.port_b2)    ;
  connect(TCon_in.y, sou1.T_in) ;
  connect(TEva_in.y, sou2.T_in) ;
  connect(uCom.y, chi.y) 
  ;
end Carnot_y;

