within IDEAS.LIDEAS.Components.BaseClasses;
model LinWindowResponse
  "Shortwave window response implementation for LIDEAS"
  parameter Integer nLay(min=1) "Number of layers of the wall";
  parameter Real[:, nLay + 1] SwAbs
    "Absorbed solar radiation for each layer for look-up table as function of angle of incidence";
  parameter Real[:, 2] SwTrans
    "Transmitted solar radiation for look-up table as function of angle of incidence";
  parameter Real[nLay] SwAbsDif
    "Absorbed solar radiation for each layer for look-up table as function of angle of incidence";
  parameter Real SwTransDif
    "Transmitted solar radiation for look-up table as function of angle of incidence";
  parameter Boolean linearise = false
    "Set to true for enabling linearization inputs/outputs";
  parameter Boolean createOutputs = false
    "Set to true for enabling linearization inputs/outputs";

  final parameter Integer[nLay] columns=if (nLay == 1) then {2} else integer(
      linspace(
      2,
      nLay + 1,
      nLay));
  Modelica.Blocks.Interfaces.RealInput solDir
    "Direct solar illuminance on surface"
    ;
  Modelica.Blocks.Interfaces.RealInput solDif
    "Diffuse solar illuminance on surface"
    ;
  Modelica.Blocks.Interfaces.RealInput angInc
    "Angle of incidence"
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a[nLay] iSolAbs
    "Solar absorptance in the panes"
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a iSolDir
    "Transmitted direct solar radiation"
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a iSolDif
    "Transmitted diffuse solar radiation"
    ;
  Modelica.Blocks.Math.Gain radToDeg(final k=180/Modelica.Constants.pi)
    "Conversion from radians to degrees"
    ;
  Modelica.Blocks.Interfaces.RealInput[nLay] AbsQFlowInput if linearise
    ;
  Modelica.Blocks.Interfaces.RealInput iSolDirInput if linearise
    ;
  Modelica.Blocks.Interfaces.RealInput iSolDifInput if linearise
    ;
  Modelica.Blocks.Interfaces.RealOutput[nLay] AbsQFlowOutput if createOutputs
    ;
  Modelica.Blocks.Interfaces.RealOutput iSolDifOutput if createOutputs
    ;
  Modelica.Blocks.Interfaces.RealOutput iSolDirOutput if createOutputs
    ;

  Modelica.Blocks.Tables.CombiTable1Ds SwAbsDir(
    final table=SwAbs,
    final smoothness=Modelica.Blocks.Types.Smoothness.LinearSegments,
    final columns=columns)
    "Table for AOI dependent absorptance"
    ;
  Modelica.Blocks.Tables.CombiTable1Ds SwTransDir(
    final table=SwTrans,
    final smoothness=Modelica.Blocks.Types.Smoothness.LinearSegments,
    final columns={2})
    "Table for AOI dependent transmittance"
    ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow[nLay] Abs_flow
    "Solar absorptance in the panes source" ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow Dir_flow
    "Transmitted direct solar radiation source" ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow Dif_flow
    "Transmitted difuse solar radiation source" ;
  Modelica.Blocks.Math.Product[nLay] SwAbsDirProd  ;
  Modelica.Blocks.Math.Product SwTransDirProd ;
  Modelica.Blocks.Math.Gain[   nLay] SwAbsDifProd(k=SwAbsDif)  ;
  Modelica.Blocks.Math.Gain    SwTransDifProd(k=SwTransDif)  ;
  Modelica.Blocks.Math.Add[nLay] add ;

equation
  connect(Abs_flow.port, iSolAbs) ;
  connect(Dir_flow.port, iSolDir) ;
  connect(Dif_flow.port, iSolDif) ;
  connect(solDir, SwTransDirProd.u1) ;
  connect(SwAbsDir.y, SwAbsDirProd.u2) ;
  connect(SwTransDir.y[1], SwTransDirProd.u2) ;
  for i in 1:nLay loop
    connect(solDir, SwAbsDirProd[i].u1) ;
    connect(solDif, SwAbsDifProd[i].u) ;
  end for;
  if not linearise then
    connect(add.y, Abs_flow.Q_flow) ;
    connect(SwTransDifProd.y, Dif_flow.Q_flow) ;
    connect(SwTransDirProd.y, Dir_flow.Q_flow) ;
  end if;
  connect(SwAbsDirProd.y, add.u2) ;
  connect(SwAbsDifProd.y, add.u1) ;
  connect(Abs_flow.Q_flow, AbsQFlowInput) ;
  connect(iSolDirInput, Dir_flow.Q_flow) ;
  connect(iSolDifInput, Dif_flow.Q_flow) ;
  connect(AbsQFlowOutput, add.y) ;
  connect(SwTransDirProd.y, iSolDirOutput) ;
  connect(SwTransDifProd.y, iSolDifOutput) ;
  connect(solDif, SwTransDifProd.u) ;
  connect(radToDeg.u, angInc) ;
  connect(radToDeg.y, SwAbsDir.u) ;
  connect(radToDeg.y, SwTransDir.u) 
  ;
end LinWindowResponse;

within IDEAS.Fluid.FMI.Adaptors;
model Outlet "Adaptor for connecting a fluid outlet to the FMI interface"

  replaceable package Medium =
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  parameter Boolean allowFlowReversal = true
    "= true to allow flow reversal, false restricts to design direction (inlet -> outlet)"
    ;

  parameter Boolean use_p_in = true
    "= true to use a pressure from connector, false to output Medium.p_default"
    ;

  IDEAS.Fluid.FMI.Interfaces.Outlet outlet(
    redeclare final package Medium = Medium,
    final allowFlowReversal=allowFlowReversal,
    final use_p_in=use_p_in) "Fluid outlet"
                   ;

  Modelica.Fluid.Interfaces.FluidPort_a port_a(
    redeclare final package Medium=Medium) "Fluid port"
                ;
  IDEAS.Fluid.FMI.Interfaces.PressureInput p
    if use_p_in "Pressure to be sent to outlet"
              ;
protected
  IDEAS.Fluid.FMI.Interfaces.FluidProperties bacPro_internal(
    redeclare final package Medium = Medium)
    "Internal connector for fluid properties for back flow";
  IDEAS.Fluid.FMI.Interfaces.PressureOutput p_in_internal
    "Internal connector for pressure";

  IDEAS.Fluid.FMI.Interfaces.MassFractionConnector X_w_in_internal
    "Internal connector for mass fraction of forward flow properties";
  IDEAS.Fluid.FMI.Interfaces.MassFractionConnector X_w_out_internal
    "Internal connector for mass fraction of backward flow properties";
initial equation
   assert(Medium.nXi < 2,
   "The medium must have zero or one independent mass fraction Medium.nXi.");
equation
  port_a.m_flow = outlet.m_flow;

  outlet.forward.T = Medium.temperature_phX(
    p = p_in_internal,
    h = inStream(port_a.h_outflow),
    X = cat(1, inStream(port_a.Xi_outflow), {1-sum(inStream(port_a.Xi_outflow))}));

  inStream(port_a.C_outflow)  = outlet.forward.C;

  // Mass fraction for forward flow
  X_w_in_internal = if Medium.nXi > 0 then inStream(port_a.Xi_outflow[1]) else 0;
  connect(outlet.forward.X_w, X_w_in_internal);

  // Conditional connector for mass fraction for backward flow
  if Medium.nXi > 0 and allowFlowReversal then
    connect(X_w_out_internal, outlet.backward.X_w);
  else
    X_w_out_internal = 0;
  end if;
  port_a.Xi_outflow = fill(X_w_out_internal, Medium.nXi);

  // Conditional connector for flow reversal
  connect(outlet.backward, bacPro_internal);
  if not allowFlowReversal then
    bacPro_internal.T  = Medium.T_default;
    bacPro_internal.C  = fill(0, Medium.nC);
    if Medium.nXi > 0 then
      // This test for nXi is needed for IDEAS.Fluid.FMI.Validation.HeaterFan_noReverseFlow
      // to work with IDEAS.Media.Water
      connect(bacPro_internal.X_w, X_w_out_internal);
    end if;
  end if;
  bacPro_internal.T  = Medium.temperature_phX(
    p = p_in_internal,
    h = port_a.h_outflow,
    X = port_a.Xi_outflow);
  bacPro_internal.C  = port_a.C_outflow;

  // Conditional connectors for pressure
  if use_p_in then
    connect(outlet.p, p_in_internal);
  else
    p_in_internal = Medium.p_default;
  end if;
  connect(p, p_in_internal);
  port_a.p = p_in_internal

    ;
end Outlet;

