within IDEAS.Experimental.Electric.BaseClasses.Converters.ConvertersPower;
model Converter "Generalized converter model"
extends Modelica.Blocks.Icons.Block;

parameter Boolean AC "AC or DC output";
parameter Real pf(min=0,max=1) = 1 "Converter power factor (output) [%/100]";
parameter Boolean lagging = true "Lagging pf or not"; // At converter: lagging = Q-consumption by inverter and vice versa.

  parameter Modelica.Units.SI.Efficiency eff
    "Converter efficiency as a function of the input power [%/100]";

  Modelica.Units.SI.ActivePower Plos;

protected
  Modelica.Units.SI.ApparentPower S;
  Modelica.Units.SI.ReactivePower Q;
 parameter Real Qsign = if lagging then 1 else -1 "Sign of reactive power";

public
 Modelica.Blocks.Interfaces.RealInput PIn
   ;
 Modelica.Blocks.Interfaces.RealOutput POut
   ;
 Modelica.Blocks.Interfaces.RealOutput QOut = Qsign * Q if AC
   ;

equation
POut = PIn * eff;
Plos = (1-eff)*PIn;

S^2=POut^2+Q^2;
pf = abs(POut) / sqrt(POut^2+Q^2)

  ;
end Converter;

within IDEAS.Fluid.Geothermal.Borefields.BaseClasses.Boreholes.BaseClasses.Functions;
function multipoleFmk "Complex matrix F_mk from Claesson and Hellstrom (2011)"
  extends Modelica.Icons.Function;

  input Integer nPip "Number of pipes";
  input Integer J "Number of multipoles";
  input Real QPip_flow[nPip](each unit="W/m") "Heat flow in pipes";
  input Real PRea[nPip,J] "Multipoles (Real part)";
  input Real PIma[nPip,J] "Multipoles (Imaginary part)";
  input Modelica.Units.SI.Radius rBor "Borehole radius";
  input Modelica.Units.SI.Radius rPip[nPip] "Outter radius of pipes";
  input Modelica.Units.SI.Position xPip[nPip] "x-Coordinates of pipes";
  input Modelica.Units.SI.Position yPip[nPip] "y-Coordinates of pipes";
  input Modelica.Units.SI.ThermalConductivity kFil
    "Thermal conductivity of grouting material";
  input Modelica.Units.SI.ThermalConductivity kSoi
    "Thermal conductivity of soil material";

  output Real FRea[nPip,J] "Multipole coefficients";
  output Real FIma[nPip,J] "Multipole coefficients";

protected
  Complex zPip_i "Position of pipe i";
  Complex zPip_j "Position of pipe j";
  Complex P_nj "Multipole of order j for pipe n";
  Real pikFil(unit="(m.K)/W")=1/(2*Modelica.Constants.pi*kFil) "Coefficient based on grout thermal conductivity";
  Real sigma=(kFil - kSoi)/(kFil + kSoi) "Thermal conductivity ratio";
  Complex f "Intermedia value of multipole coefficient";
  Integer j_pend "Maximum loop index in fourth term";

algorithm

  for m in 1:nPip loop
    zPip_i := Complex(xPip[m], yPip[m]);
    for k in 1:J loop
      f := Complex(0, 0);
      for n in 1:nPip loop
        zPip_j := Complex(xPip[n], yPip[n]);
        // First term
        if m <> n then
          f := f + QPip_flow[n]*pikFil/k*(rPip[m]/(zPip_j - zPip_i))^k;
        end if;
        // Second term
        f := f + sigma*QPip_flow[n]*pikFil/k*(rPip[m]*Modelica.ComplexMath.conj(
          zPip_j)/(rBor^2 - zPip_i*Modelica.ComplexMath.conj(zPip_j)))^k;
        for j in 1:J loop
          P_nj := Complex(PRea[n, j], PIma[n, j]);
          // Third term
          if m <> n then
            f := f + P_nj*IDEAS.Utilities.Math.Functions.binomial(j + k - 1, j -
              1)*rPip[n]^j*(-rPip[m])^k/(zPip_i - zPip_j)^(j + k);
          end if;
          //Fourth term
          j_pend := min(k, j);
          for jp in 0:j_pend loop
            f := f + sigma*Modelica.ComplexMath.conj(P_nj)*
              IDEAS.Utilities.Math.Functions.binomial(j, jp)*
              IDEAS.Utilities.Math.Functions.binomial(j + k - jp - 1, j - 1)*
              rPip[n]^j*rPip[m]^k*zPip_i^(j - jp)*Modelica.ComplexMath.conj(
              zPip_j)^(k - jp)/(rBor^2 - zPip_i*Modelica.ComplexMath.conj(
              zPip_j))^(k + j - jp);
          end for;
        end for;
      end for;
      FRea[m, k] := Modelica.ComplexMath.real(f);
      FIma[m, k] := Modelica.ComplexMath.imag(f);
    end for;
  end for

  ;
end multipoleFmk;

within IDEAS.Fluid.Actuators.Motors;
model IdealMotor "Ideal motor model with hysteresis"
  extends Modelica.Blocks.Interfaces.SISO;

  parameter Real delta(min=0, max=0.5) = 0.05 "Hysteresis";
  parameter Modelica.Units.SI.Time tOpe(min=0) = 120 "Opening time";
  parameter Modelica.Units.SI.Time tClo(min=0) = tOpe "Closing time";
  parameter Real y_start(min=0, max=1) = 0.5 "Start position";

  Modelica.Blocks.Logical.Hysteresis uppHys(final uLow=0, uHigh=delta,
    final pre_y_start=false)
                       ;
  Modelica.Blocks.Logical.Hysteresis lowHys(uLow=-delta, final uHigh=0,
    final pre_y_start=true) "Lower hysteresis"
                                         ;
  Modelica.Blocks.Logical.Switch uppSwi ;
  Modelica.Blocks.Continuous.LimIntegrator int(
    final y_start=y_start,
    final k=1,
    outMax=1,
    outMin=0,
    initType=Modelica.Blocks.Types.Init.InitialState,
    limitsAtInit=true,
    y(stateSelect=StateSelect.always)) "Integrator for valve opening position"
    ;

protected
  final Modelica.Blocks.Sources.Constant zer(final k=0) "Zero signal"
    ;
  Modelica.Blocks.Sources.Constant vOpe(final k=1/tOpe) "Opening speed"
    ;
  Modelica.Blocks.Sources.Constant vClo(final k=-1/tClo) "Closing speed"
    ;
  Modelica.Blocks.Logical.Switch lowSwi ;
  Modelica.Blocks.Math.Add add ;
  Modelica.Blocks.Math.Feedback feeBac "Feedback to compute position error"
                                         ;
equation
  connect(zer.y, uppSwi.u3) ;
  connect(uppHys.y, uppSwi.u2)
    ;
  connect(vOpe.y, uppSwi.u1) ;
  connect(lowHys.y, lowSwi.u2) ;
  connect(vClo.y, lowSwi.u3) ;
  connect(zer.y, lowSwi.u1) ;
  connect(add.y, int.u) ;
  connect(uppSwi.y, add.u1) ;
  connect(u, feeBac.u1)   ;
  connect(feeBac.y, uppHys.u)   ;
  connect(feeBac.y, lowHys.u)   ;
  connect(lowSwi.y, add.u2) ;
  connect(int.y, y) ;
  connect(int.y, feeBac.u2) 
   ;
end IdealMotor;

