within IDEAS.Fluid.Geothermal.Borefields.BaseClasses.Boreholes.BaseClasses.Examples;
model InternalHEXOneUTube
  "Comparison of the effective borehole thermal resistance  from the thermal network of Bauer et al. with the resistance calculated by singleUTubeResistances (ref)"
  extends Modelica.Icons.Example;

  parameter Integer nSeg(min=1) = 10
    "Number of segments to use in vertical discretization of the boreholes";
  parameter Modelica.Units.SI.Length hSeg=borFieDat.conDat.hBor/nSeg
    "Length of the internal heat exchanger";

  package Medium = Modelica.Media.Water.ConstantPropertyLiquidWater;
  IDEAS.Fluid.Geothermal.Borefields.BaseClasses.Boreholes.BaseClasses.InternalHEXOneUTube
    intHex(
    redeclare package Medium = Medium,
    hSeg=hSeg,
    dp1_nominal=10,
    dp2_nominal=10,
    borFieDat=borFieDat,
    m1_flow_nominal=borFieDat.conDat.mBor_flow_nominal,
    m2_flow_nominal=borFieDat.conDat.mBor_flow_nominal,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    TFlu_start=285.15,
    TGro_start=285.15)
    ;

  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature fixedTemperature(T=273.15
         + 12)
    ;
  IDEAS.Fluid.Sources.MassFlowSource_T boundary(nPorts=1,
    redeclare package Medium = Medium,
    m_flow=borFieDat.conDat.mBor_flow_nominal,
    T=293.15)
    ;
  IDEAS.Fluid.Sources.MassFlowSource_T boundary1(nPorts=1,
    redeclare package Medium = Medium,
    m_flow=borFieDat.conDat.mBor_flow_nominal,
    T=293.15)
    ;
  IDEAS.Fluid.Sources.Boundary_pT bou(nPorts=2, redeclare package Medium = Medium)
    ;
  Real Rb_sim(unit="(m.K)/W") = ((senTem.T + senTem1.T)/2 - intHex.port_wall.T)/max(-intHex.port_wall.Q_flow / hSeg,1);
  IDEAS.Fluid.Sensors.TemperatureTwoPort senTem(redeclare package Medium =
        Medium, m_flow_nominal=borFieDat.conDat.mBor_flow_nominal)
    ;
  IDEAS.Fluid.Sensors.TemperatureTwoPort senTem1(redeclare package Medium =
        Medium, m_flow_nominal=borFieDat.conDat.mBor_flow_nominal)
    ;
  Modelica.Blocks.Sources.RealExpression realExpression(y=Rb_sim)
    ;
  Modelica.Blocks.Sources.Constant Rb_ref(k=0.082399)
    ;
  Modelica.Blocks.Math.Add error(k2=-1)
    ;
  parameter IDEAS.Fluid.Geothermal.Borefields.Data.Borefield.Example
    borFieDat(conDat=
        IDEAS.Fluid.Geothermal.Borefields.Data.Configuration.Example(
        use_Rb=false))
    "Borefield data"
    ;
equation

  connect(boundary1.ports[1], intHex.port_a2)
    ;
  connect(boundary.ports[1], intHex.port_a1)
    ;
  connect(bou.ports[1], senTem.port_b) ;
  connect(senTem.port_a, intHex.port_b1)
    ;
  connect(senTem1.port_a, bou.ports[2]) ;
  connect(senTem1.port_b, intHex.port_b2)
    ;
  connect(realExpression.y, error.u1) ;
  connect(Rb_ref.y, error.u2) ;
  connect(fixedTemperature.port, intHex.port_wall)

  ;
end InternalHEXOneUTube;

within IDEAS.Examples.TwinHouses.Interfaces;
partial model PartialTTHStructure "Partial Model Based on Excel autogenerated"
  extends IDEAS.Templates.Interfaces.BaseClasses.Structure(
    redeclare each package Medium = IDEAS.Media.Air,
    nZones=7,
    nEmb=0);
  parameter Boolean includeTB=false
    "optional extension of model to include thermal bridges";
  parameter Boolean includeAirCoup=false
    "optional extension of model to include increased air coupling";
  parameter Integer exp=1 "Experiment number: 1 or 2";
  parameter Integer bui=1 "Building number 1 (N2), 2 (O5)";
  final parameter String filename = if exp==1 and bui== 1 then "BCTwinHouseN2Exp1.txt" elseif exp==2 and bui==1 then "BCTwinHouseN2Exp2.txt" else "BCTwinHouseO5.txt";
  final parameter String dirPath = Modelica.Utilities.Files.loadResource("modelica://IDEAS/Resources/measurements/")
    ;
protected
  final parameter Modelica.Units.SI.Angle incWall=IDEAS.Types.Tilt.Wall;
  final parameter Modelica.Units.SI.Angle incCeil=IDEAS.Types.Tilt.Ceiling;
  final parameter Modelica.Units.SI.Angle incFloor=IDEAS.Types.Tilt.Floor;
  final parameter Modelica.Units.SI.Angle aziNorth=IDEAS.Types.Azimuth.N;
  final parameter Modelica.Units.SI.Angle aziEast=IDEAS.Types.Azimuth.E;
  final parameter Modelica.Units.SI.Angle aziSouth=IDEAS.Types.Azimuth.S;
  final parameter Modelica.Units.SI.Angle aziWest=IDEAS.Types.Azimuth.W;

public
  Modelica.Blocks.Sources.CombiTimeTable inputAtticAndBasement(
    table=[0.0,0.0,0.0; 1000,1,1],
    smoothness=Modelica.Blocks.Types.Smoothness.ContinuousDerivative,
    tableOnFile=true,
    fileName=dirPath + filename,
    columns={2,3},
    extrapolation=Modelica.Blocks.Types.Extrapolation.HoldLastPoint,
    tableName="data")
    ;
  Modelica.Blocks.Math.UnitConversions.From_degC[2] from_degC
    ;
  BaseClasses.Structures.ThermalBridges thermalBridges if includeTB
    ;
  BaseClasses.controlBlind controlBlind1(exp=exp,bui=bui)
    ;
  Buildings.Components.Interfaces.WeaBus weaBus(outputAngles=sim.outputAngles,
      numSolBus=sim.numIncAndAziInBus);
equation

  connect(thermalBridges.heatPortRad, heatPortRad);
  connect(thermalBridges.Tzone,TSensor);
