within IDEAS.Fluid.Actuators.Valves;
model TwoWayTable "Two way valve with table-specified flow characteristics"
  extends BaseClasses.PartialTwoWayValveKv(
    phi=max(0.1*l, phiLooUp.y[1]),
    final l = phiLooUp.table[1, 2]);
  parameter Data.Generic flowCharacteristics "Table with flow characteristics"
    ;

  // Since the flow model IDEAS.Fluid.BaseClasses.FlowModels.basicFlowFunction_m_flow computes
  // 1/k^2, the flowCharacteristics.phi[1] must not be zero.
  // We therefore set a lower bound.
protected
  Modelica.Blocks.Tables.CombiTable1Dv phiLooUp(
    final tableOnFile=false,
    final table=[flowCharacteristics.y,cat(
        1,
        {max(flowCharacteristics.phi[1], 1E-8)},
        {flowCharacteristics.phi[i] for i in 2:size(flowCharacteristics.phi, 1)})],
    final columns=2:2,
    final smoothness=Modelica.Blocks.Types.Smoothness.ContinuousDerivative)
    "Normalized mass flow rate for the given valve position under the assumption of a constant pressure"
    ;

initial equation
  assert(abs(flowCharacteristics.y[1]) < Modelica.Constants.eps,
    "flowCharateristics.y[1] must be 0.");
  assert(abs(flowCharacteristics.y[size(flowCharacteristics.y, 1)] - 1) <
    Modelica.Constants.eps,
    "flowCharateristics.y[end] must be 1.");
  assert(abs(flowCharacteristics.phi[size(flowCharacteristics.phi, 1)] - 1) <
    Modelica.Constants.eps,
    "flowCharateristics.phi[end] must be 1.");

  // Assert that the sequences are strictly monotonic increasing
  assert(IDEAS.Utilities.Math.Functions.isMonotonic(
           x=flowCharacteristics.y,
           strict=true),
         "The values for y in flowCharacteristics must be strictly monotone increasing.");
  assert(IDEAS.Utilities.Math.Functions.isMonotonic(
           x=flowCharacteristics.phi,
           strict=true),
         "The values for phi in flowCharacteristics must be strictly monotone increasing.");

equation
  connect(phiLooUp.u[1], y_actual) 
  ;
end TwoWayTable;

within IDEAS.Fluid.HeatExchangers.ActiveBeams.BaseClasses;
model DerivativesCubicSpline "Cubic spline for interpolation"
  extends Modelica.Blocks.Icons.Block;
  parameter Real[:] xd={0,0.5,1};
  parameter Real[size(xd, 1)] yd={0,0.75,1};

  Modelica.Blocks.Interfaces.RealInput u
    "Independent variable for interpolation"
    ;
  Modelica.Blocks.Interfaces.RealOutput y "Interpolated value"
    ;
protected
  parameter Real[size(xd, 1)] dMonotone(each fixed=false) "Derivatives";
  Integer i "Counter to pick the interpolation interval";

initial algorithm
  // Get the derivative values at the support points

  dMonotone := IDEAS.Utilities.Math.Functions.splineDerivatives(
    x=xd,
    y=yd,
    ensureMonotonicity=true);

algorithm
  i := 1;
  for j in 1:size(xd, 1) - 1 loop
    if u > xd[j] then
      i := j;
    end if;
  end for;
  // Extrapolate or interpolate the data
  y :=
    IDEAS.Utilities.Math.Functions.cubicHermiteLinearExtrapolation(
    x=u,
    x1=xd[i],
    x2=xd[i + 1],
    y1=yd[i],
    y2=yd[i + 1],
    y1d=dMonotone[i],
    y2d=dMonotone[i + 1])
;
end DerivativesCubicSpline;

within IDEAS.Fluid.BaseClasses.FlowModels.Validation;
model BasicFlowFunction_dp_DerivativeCheck
  "Model that checks the correct implementation of the 1st order derivative of the flow function"
  extends Modelica.Icons.Example;

  constant Real gain = 2 "Gain for computing the mass flow rate";

  parameter Real k = 0.35 "Flow coefficient";
  parameter Modelica.Units.SI.MassFlowRate m_flow_turbulent=0.36
    "Mass flow rate where transition to turbulent flow occurs";
  Modelica.Units.SI.MassFlowRate m_flow "Mass flow rate";
  Modelica.Units.SI.MassFlowRate m_flow_comp "Comparison value for m_flow";
  Modelica.Units.SI.PressureDifference dp "Pressure drop";
  Modelica.Units.SI.MassFlowRate err "Integration error";
initial equation
 m_flow = m_flow_comp;
equation
  dp = time*gain;
  m_flow = IDEAS.Fluid.BaseClasses.FlowModels.basicFlowFunction_dp(
    dp=dp,
    k = k,
    m_flow_turbulent=m_flow_turbulent);
  der(m_flow) = der(m_flow_comp);
  err = m_flow-m_flow_comp;
  assert(abs(err) < 1E-3, "Error in implementation.")
;
end BasicFlowFunction_dp_DerivativeCheck;

