  Modelica.Blocks.Math.Gain gainCon(final k=1 - radFra)
    ;
protected
  Modelica.Thermal.HeatTransfer.Sources.PrescribedHeatFlow preHeaFloRad(final
      alpha=0) "Prescribed heat flow rate for radiative sensible heat"
    ;
