within IDEAS.Fluid.Geothermal.Borefields.BaseClasses.HeatTransfer.ThermalResponseFactors;
function shaGFunction
  "Returns a SHA1 encryption of the formatted arguments for the g-function generation"
  extends Modelica.Icons.Function;
  input Integer nBor "Number of boreholes";
  input Modelica.Units.SI.Position cooBor[nBor,2] "Coordinates of boreholes";
  input Modelica.Units.SI.Height hBor "Borehole length";
  input Modelica.Units.SI.Height dBor "Borehole buried depth";
  input Modelica.Units.SI.Radius rBor "Borehole radius";
  input Modelica.Units.SI.ThermalDiffusivity aSoi
    "Ground thermal diffusivity used in g-function evaluation";
  input Integer nSeg "Number of line source segments per borehole";
  input Integer nTimSho "Number of time steps in short time region";
  input Integer nTimLon "Number of time steps in long time region";
  input Real ttsMax "Maximum adimensional time for gfunc calculation";

  output String sha
  "SHA1 encryption of the g-function arguments";

protected
  constant String formatStrGen =  "1.3e" "String format for general parameters";
  constant String formatStrCoo =  ".2f" "String format for coordinate";
algorithm
  sha := IDEAS.Utilities.Cryptographics.sha(String(nBor, format=formatStrGen));
  sha := IDEAS.Utilities.Cryptographics.sha(sha + String(hBor, format=formatStrGen));
  sha := IDEAS.Utilities.Cryptographics.sha(sha + String(dBor, format=formatStrGen));
  sha := IDEAS.Utilities.Cryptographics.sha(sha + String(rBor, format=formatStrGen));
  sha := IDEAS.Utilities.Cryptographics.sha(sha + String(aSoi, format=formatStrGen));
  sha := IDEAS.Utilities.Cryptographics.sha(sha + String(nSeg, format=formatStrGen));
  sha := IDEAS.Utilities.Cryptographics.sha(sha + String(nTimSho, format=formatStrGen));
  sha := IDEAS.Utilities.Cryptographics.sha(sha + String(nTimLon, format=formatStrGen));
  sha := IDEAS.Utilities.Cryptographics.sha(sha + String(ttsMax, format=formatStrGen));
  for i in 1:nBor loop
    sha := IDEAS.Utilities.Cryptographics.sha(sha + String(cooBor[i, 1], format=formatStrCoo));
    sha := IDEAS.Utilities.Cryptographics.sha(sha + String(cooBor[i, 2], format=formatStrCoo));
  end for

;
end shaGFunction;

within IDEAS.BoundaryConditions.Occupants.Components;
model Schedule "Single schedule with look-ahead"

  outer IDEAS.BoundaryConditions.SimInfoManager sim;
  extends Modelica.Icons.ObsoleteModel;

  parameter Real occupancy[:]=3600*{7,19}
    "Occupancy table, each entry switching occupancy on or off";
  parameter Boolean firstEntryOccupied=true
    "Set to true if first entry in occupancy denotes a changed from unoccupied to occupied";
  parameter Modelica.Units.SI.Time startTime=0 "Start time of periodicity";
  parameter Modelica.Units.SI.Time endTime=86400 "End time of periodicity";

  Modelica.Blocks.Interfaces.RealOutput tNexNonOcc
    "Time until next non-occupancy"
    ;
  Modelica.Blocks.Interfaces.RealOutput tNexOcc "Time until next occupancy"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput occupied
    "Outputs true if occupied at current time"
    ;

protected
  final parameter Modelica.Units.SI.Time period=endTime - startTime;
  final parameter Integer nRow=size(occupancy, 1);

  output Integer nexStaInd "Next index when occupancy starts";
  output Integer nexStoInd "Next index when occupancy stops";

  output Integer iPerSta
    "Counter for the period in which the next occupancy starts";
  output Integer iPerSto
    "Counter for the period in which the next occupancy stops";
  output Modelica.Units.SI.Time schTim
    "Time in schedule (not exceeding max. schedule time)";
  output Modelica.Units.SI.Time tMax "Maximum time in schedule";
  output Modelica.Units.SI.Time tOcc "Time when next occupancy starts";
  output Modelica.Units.SI.Time tNonOcc "Time when next non-occupancy starts";

initial algorithm
  tOcc := if firstEntryOccupied then occupancy[1] else  time;
  tNonOcc := if firstEntryOccupied then  time else occupancy[1];

  iPerSta := 0;
  iPerSto := 0;
  nexStaInd := if firstEntryOccupied then 1 else 2;
  nexStoInd := if firstEntryOccupied then 2 else 1;
  occupied := not firstEntryOccupied;
  tOcc := occupancy[nexStaInd];
  tNonOcc := occupancy[nexStoInd];

algorithm
  tMax := endTime;
  schTim := startTime + mod( time - startTime, period);

  // Changed the index that computes the time until the next occupancy
  when time >= occupancy[nexStaInd] + iPerSta*period then
    nexStaInd := nexStaInd + 2;
    occupied := not occupied;
    // Wrap index around
    if nexStaInd > nRow then
      nexStaInd := if firstEntryOccupied then 1 else 2;
      iPerSta := iPerSta + 1;
    end if;
    tOcc := occupancy[nexStaInd] + iPerSta*(period);
  end when;

  // Changed the index that computes the time until the next non-occupancy
  when time >= occupancy[nexStoInd] + iPerSto*period then
    nexStoInd := nexStoInd + 2;
    occupied := not occupied;
    // Wrap index around
    if nexStoInd > nRow then
      nexStoInd := if firstEntryOccupied then 2 else 1;
      iPerSto := iPerSto + 1;
    end if;
    tNonOcc := occupancy[nexStoInd] + iPerSto*(period);
  end when;

  tNexOcc := tOcc -  time;
  tNexNonOcc := tNonOcc -  time

  ;
end Schedule;

