within IDEAS.BoundaryConditions.WeatherData.BaseClasses;
block ConvertTime
  "Converts the simulation time to calendar time in scale of 1 year (365 days), or a multiple of a year"
  extends Modelica.Blocks.Icons.Block;

  parameter Modelica.Units.SI.Time weaDatStaTim(displayUnit="d")
    "Start time of weather data";
  parameter Modelica.Units.SI.Time weaDatEndTim(displayUnit="d")
    "End time of weather data";

  Modelica.Blocks.Interfaces.RealInput modTim(
    final quantity="Time",
    final unit="s") "Simulation time"
    ;
  Modelica.Blocks.Interfaces.RealOutput calTim(
    final quantity="Time",
    final unit="s") "Calendar time"
    ;

protected
  constant Modelica.Units.SI.Time shiftSolarRad=1800
    "Number of seconds for the shift for solar radiation calculation";
  parameter Modelica.Units.SI.Time lenWea=weaDatEndTim - weaDatStaTim
    "Length of weather data";

  parameter Boolean canRepeatWeatherFile = abs(mod(lenWea, 365*24*3600)) < 1E-2
    "=true, if the weather file can be repeated, since it has the length of a year or a multiple of it";

  discrete Modelica.Units.SI.Time tNext(start=0, fixed=true)
    "Start time of next period";

equation
  when {initial(), canRepeatWeatherFile and modTim > pre(tNext)} then
    // simulation time stamp went over the end time of the weather file
    //(last time stamp of the weather file + average increment)
    tNext = if canRepeatWeatherFile then integer(modTim/lenWea)*lenWea + lenWea else time;
  end when;
  calTim = if canRepeatWeatherFile then modTim - tNext + lenWea else modTim;

  assert(canRepeatWeatherFile or noEvent((time - weaDatEndTim) < shiftSolarRad),
    "In " + getInstanceName() + ": Insufficient weather data provided for the desired simulation period.
    The simulation time " + String(time) +
    " exceeds the end time " + String(weaDatEndTim) + " of the weather data file.",
    AssertionLevel.error);

  assert(canRepeatWeatherFile or noEvent(time >= weaDatStaTim),
    "In " + getInstanceName() + ": Insufficient weather data provided for the desired simulation period.
    The simulation time " + String(time) +
    " is less than the start time " + String(weaDatStaTim) + " of the weather data file.",
    AssertionLevel.error)

  ;
end ConvertTime;

within IDEAS.Media.Refrigerants.R410A;
function specificVolumeVap_pT
  "Function that calculates the specific volume R410A vapor based on pressure and temperature"
  input Modelica.Units.SI.AbsolutePressure p "Pressure of refrigerant vapor";
  input Modelica.Units.SI.Temperature T "Temperature of refrigerant";
  output Modelica.Units.SI.SpecificVolume v "Specific volume of refrigerant";

protected
  Modelica.Units.SI.SpecificVolume dv "Error on specific volume of refrigerant";

  Modelica.Units.SI.Pressure dp "Error on pressure of refrigerant";

  Real dpdv( final unit = "(Pa.kg)/m3") "Partial derivative dp/dv";

  Integer m "Counter";

algorithm

  // Initial guess of specific volume
  v := R*T/p + b;
  dv := 1e99;
  m := 0;
  while abs(dv/v) > 1e-10 loop
    assert(m < 1E3,
      "Failed to converge in IDEAS.Media.Refrigerants.R410A.specificVolumeVap_pT");
    m := m + 1;

    // Evaluate first derivative of pressure w.r.t. specific volume
    dpdv := IDEAS.Media.Refrigerants.R410A.dPressureVap_dSpecificVolume_Tv(T, v);
    // Error on pressure
    dp := p - IDEAS.Media.Refrigerants.R410A.pressureVap_Tv(T, v);
    // Corresponding linear adjustment of specific volume
    dv := dp/dpdv;
    v := v + dv;

end while

;
end specificVolumeVap_pT;

within IDEAS.Fluid.FixedResistances.Validation.PlugFlowPipes;
model PlugFlowULg "Validation against data from Université de Liège"
  extends Modelica.Icons.Example;
  package Medium = IDEAS.Media.Water;

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal=1
    "Nominal mass flow rate, used for regularization near zero flow";
  parameter Modelica.Units.SI.Temperature T_start_in=pipeDataULg.T_start_in +
      273.15 "Initial temperature at pipe inlet";
  parameter Modelica.Units.SI.Temperature T_start_out=pipeDataULg.T_start_out
       + 273.15 "Initial temperature at pipe outlet";
  parameter Modelica.Units.SI.SpecificHeatCapacity cp_default=
      Medium.specificHeatCapacityCp(state=sta_default)
    "Heat capacity of medium";
  parameter Medium.ThermodynamicState sta_default=Medium.setState_pTX(
      T=Medium.T_default,
      p=Medium.p_default,
      X=Medium.X_default) "Default medium state";

  Fluid.Sources.MassFlowSource_T WaterCityNetwork(
    redeclare package Medium = Medium,
    m_flow=1.245,
    use_m_flow_in=true,
    nPorts=1) "Mass flow source"
              ;
  Fluid.HeatExchangers.Heater_T Boiler(
    redeclare package Medium = Medium,
    m_flow_nominal=1,
    dp_nominal=0) "Boiler with adjustable outlet temperature"
                  ;
  Fluid.Sources.Boundary_pT Sewer1(
    redeclare package Medium = Medium,
    nPorts=1) "Mass flow sink"
    ;
  Fluid.Sensors.TemperatureTwoPort senTem_out(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    tau=0,
    T_start=T_start_out) "Temperature sensor"
    ;
  Fluid.Sensors.TemperatureTwoPort senTem_in(
    redeclare package Medium = Medium,
    m_flow_nominal=m_flow_nominal,
    tau=0,
    T_start=T_start_in) "Temperature sensor"
    ;
  Modelica.Blocks.Sources.CombiTimeTable DataReader(
    tableOnFile=true,
    tableName="dat",
    fileName=pipeDataULg.filNam,
    columns=2:pipeDataULg.nCol,
    extrapolation=Modelica.Blocks.Types.Extrapolation.HoldLastPoint)
    "Measurement data"
    ;

  Modelica.Blocks.Math.UnitConversions.From_degC Tout
    "Ambient temperature in degrees"
    ;
  Modelica.Thermal.HeatTransfer.Sources.FixedTemperature TBou(T=295.15)
    "Fixed boundary condition"
                         ;
  Modelica.Blocks.Math.UnitConversions.From_degC Tin
    "Input temperature into pipe"
    ;

  replaceable Data.PipeDataULg151202 pipeDataULg constrainedby
    Data.BaseClasses.PipeDataULg
    "Measurement dataset from ULg (use Change Class... to choose from different experiments)"
    ;
  Modelica.Blocks.Math.Gain gain(k=1)
    "Gain to test variations of mass flow rate within measurement uncertainty "
    ;
  PlugFlowPipe pipe(
    redeclare package Medium = Medium,
    dh=0.05248,
    length=39,
    dIns(displayUnit="mm") = 0.013,
    kIns=0.04,
    m_flow_nominal=m_flow_nominal,
    thickness=3.9e-3,
    T_start_out=T_start_out,
    T_start_in=T_start_in,
    R=((1/(2*pipe.kIns)*log((0.0603/2 + pipe.dIns)/(0.0603/2))) + 1/(5*(0.0603
         + 2*pipe.dIns)))/Modelica.Constants.pi,
    initDelay=true,
    m_flow_start=pipeDataULg.m_flowIni,
    cPip=500,
    rhoPip=8000) "Pipe"
    ;
  Fluid.Sensors.EnthalpyFlowRate senEntOut(redeclare package Medium = Medium,
      m_flow_nominal=m_flow_nominal) "Outlet enthalpy sensor"
    ;
  Modelica.Blocks.Math.Add heatLossSim(k1=-1)
    "Difference between inflowing and outflowing enthalpy streams"
    ;
  Modelica.Blocks.Continuous.Integrator eneLosInt "Integrate model error"
    ;
  Fluid.Sensors.EnthalpyFlowRate senEntIn(redeclare package Medium = Medium,
      m_flow_nominal=m_flow_nominal) "Inlet enthalpy sensor"
    ;
  Modelica.Blocks.Math.Add delT(k2=-1)
    "Temperature difference between in- and outlet"
    ;
  Modelica.Blocks.Math.Product heaLosMea
    "Heat loss from measurement (mflow*cp*DeltaT)"
    ;
  Modelica.Blocks.Math.Gain gain3(k=cp_default) "Specific heat of water"
    ;
  Modelica.Blocks.Math.Feedback heaLosDiff
    "Difference between simulated and measurement enthalpy flow difference"
    ;
  Modelica.Blocks.Sources.Constant Tamb(k=273 + 18)
    "Ambient temperature in Kelvin";
equation
  connect(DataReader.y[3], Tout.u) ;
  connect(DataReader.y[5], Tin.u)
    ;
  connect(DataReader.y[1], gain.u) ;
  connect(senTem_in.port_a, Boiler.port_b)
    ;
  connect(Boiler.port_a, WaterCityNetwork.ports[1])
    ;
  connect(gain.y, WaterCityNetwork.m_flow_in) ;
  connect(Tin.y, Boiler.TSet) ;
  connect(Sewer1.ports[1], senTem_out.port_b)
    ;
  connect(senTem_out.port_a, senEntOut.port_b)
    ;
  connect(senEntOut.port_a, pipe.port_b)
    ;
  connect(pipe.port_a, senEntIn.port_b)
    ;
  connect(senTem_in.port_b, senEntIn.port_a)
    ;
  connect(TBou.port, pipe.heatPort)
    ;
  connect(gain.y, gain3.u)
    ;
  connect(heaLosMea.y, heaLosDiff.u2)
    ;
  connect(heatLossSim.y, heaLosDiff.u1)
    ;
  connect(heaLosDiff.y, eneLosInt.u)
    ;
  connect(delT.u1, Tin.y) ;
  connect(Tout.y, delT.u2) ;
  connect(heaLosMea.u1, gain3.y) ;
  connect(heaLosMea.u2, delT.y) ;
  connect(heatLossSim.u2, senEntIn.H_flow)
    ;
  connect(heatLossSim.u1, senEntOut.H_flow)

  ;
end PlugFlowULg;

within IDEAS.ThermalZones.ReducedOrder.Validation.VDI6007.BaseClasses;
block VerifyDifferenceThreePeriods "Assert when condition is violated"
  extends IDEAS.Utilities.Diagnostics.BaseClasses.PartialInputCheck(
    message="Inputs differ by more than threShold.\n  Check output 'satisfied' for when violation(s) happened.");
  parameter Modelica.Units.SI.Time endTime=0
    "Start time for deactivating the assert (period one)";
  parameter Modelica.Units.SI.Time startTime2=0
    "Start time for activating the assert (period two)";
  parameter Modelica.Units.SI.Time endTime2=0
    "Start time for deactivating the assert (period two)";
  parameter Modelica.Units.SI.Time startTime3=0
    "Start time for activating the assert (period three)";
  parameter Modelica.Units.SI.Time endTime3=0
    "Start time for deactivating the assert (period three)";
  parameter Modelica.Units.SI.Time tau(min=1) = 60
    "Time constant for filtering signal";

  Modelica.Blocks.Interfaces.BooleanOutput satisfied(start=true, fixed=true)
    ;

  Modelica.Blocks.Interfaces.RealOutput diff "Difference abs(u1-u2) after filtering"
    ;

protected
  parameter Modelica.Units.SI.Time t1(fixed=false)
    "Simulation end time period one";
  parameter Modelica.Units.SI.Time t3(fixed=false)
    "Simulation end time period two";
  parameter Modelica.Units.SI.Time t5(fixed=false)
    "Simulation end time period three";
  parameter Modelica.Units.SI.Time t2(fixed=false)
    "Simulation start time period two";
  parameter Modelica.Units.SI.Time t4(fixed=false)
    "Simulation start time period three";
  Integer nFai "Number of test violations";
  Real diffExa "Exact, non-filtered value of the difference between the inputs";

initial equation
  t1 = time + endTime;
  t2 = time + startTime2;
  t3 = time + endTime2;
  t4 = time + startTime3;
  t5 = time + endTime3;
  nFai = 0;
  diff = if (time >= t0) and (time < t1) or
            (time >= t2) and (time < t3) or
            (time >= t4) and (time < t5)
         then
           abs(u1 - u2)
         else
           0;
equation
  if (time >= t0) and (time < t1) or
     (time >= t2) and (time < t3) or
     (time >= t4) and (time < t5) then
     diffExa = abs(u1 - u2);
  else
    diffExa = 0; // Test is not needed in this time domain
  end if;
  der(diff) = (diffExa-diff)/tau;

  // Output whether test is satisfied, using a small hysteresis that is scaled using threShold
  satisfied = not ( (pre(satisfied) and diff > 1.01*threShold) or (not pre(satisfied) and diff >= 0.99*threShold));

  // Count the number of failures and raise an assertion in the terminal section.
  // This ensures that if the model is in an FMU, no asserts are triggered during
  // the solver iterations.
  when not satisfied then
    nFai = pre(nFai) + 1;
  end when;

  when terminal() then
    assert(nFai == 0, message);
  end when

;
end VerifyDifferenceThreePeriods;

within IDEAS.Fluid.MixingVolumes.Validation.BaseClasses;
partial model MixingVolumeReverseFlow
  "Test model for mixing volume with flow reversal"
 extends Modelica.Icons.Example;
 package Medium = IDEAS.Media.Air "Medium model";

  constant Boolean prescribedHeatFlowRate = false
    "Flag that affects what steady state balance is used in the volume";
  parameter Modelica.Units.SI.Pressure dp_nominal=10 "Nominal pressure drop";
  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal=2.0
    "Nominal mass flow rate";

  Modelica.Fluid.Sources.MassFlowSource_T sou(
    redeclare package Medium = Medium,
    nPorts=1,
    m_flow=m_flow_nominal,
    use_m_flow_in=true,
    T=313.15) "Flow source and sink"
    ;
  Sources.Boundary_pT bou(
    redeclare package Medium = Medium,
    T=303.15,
    nPorts=2) "Boundary condition"
    ;
  replaceable IDEAS.Fluid.MixingVolumes.MixingVolume volDyn
    constrainedby IDEAS.Fluid.MixingVolumes.MixingVolume(
        redeclare package Medium = Medium,
        V=1,
        nPorts=2,
        m_flow_nominal=m_flow_nominal,
        energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial)
    "Volume with dynamic balance"
    ;

  replaceable IDEAS.Fluid.MixingVolumes.MixingVolume volSte
    constrainedby IDEAS.Fluid.MixingVolumes.MixingVolume(
        redeclare package Medium = Medium,
        final prescribedHeatFlowRate = prescribedHeatFlowRate,
        V=1,
        nPorts=2,
        m_flow_nominal=m_flow_nominal,
        energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState)
    "Volume with steady-state balance"
    ;

  Modelica.Blocks.Math.Gain gain
    "Gain to add heat, moisture or trace substance flow rate"
    ;
  Modelica.Fluid.Sources.MassFlowSource_T sou1(
    redeclare package Medium = Medium,
    nPorts=1,
    m_flow=m_flow_nominal,
    use_m_flow_in=true,
    T=313.15) "Flow source and sink"
    ;
  Modelica.Blocks.Sources.Ramp m_flow(
    height=-2*m_flow_nominal,
    duration=10,
    offset=m_flow_nominal) "Mass flow rate"
    ;
equation
  connect(sou.ports[1], volDyn.ports[1]) ;
  connect(sou1.ports[1], volSte.ports[1])
    ;
  connect(volSte.ports[2], bou.ports[1]) ;
  connect(volDyn.ports[2], bou.ports[2]) ;
  connect(sou.m_flow_in, m_flow.y) ;
  connect(m_flow.y, sou1.m_flow_in) ;
  connect(m_flow.y, gain.u) 
  ;
end MixingVolumeReverseFlow;

within IDEAS.Fluid.FMI.Adaptors;
model ThermalZone
  "Adaptor for connecting a thermal zone to signal ports which then can be exposed at an FMI interface"

  replaceable package Medium =
    Modelica.Media.Interfaces.PartialMedium "Medium in the component"
      ;

  // Don't use  for nPorts because
  // otherwise, in IDEAS.Fluid.FMI.ExportContainers.Examples.FMUs.HVACZones
  // the fluid ports can not be assigned between the different zones by the user.
  parameter Integer nPorts(final min=2) "Number of fluid ports"
    ;

  Interfaces.Inlet fluPor[nPorts](
    redeclare each final package Medium = Medium,
    each final allowFlowReversal=true,
    each final use_p_in=false) "Fluid connector" ;

  Modelica.Fluid.Interfaces.FluidPorts_b ports[nPorts](
    redeclare each final package Medium = Medium)
    ;

  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heaPorAir
    "Heat port for sensible heat input" ;

protected
  x_i_toX_w x_i_toX(
    redeclare final package Medium = Medium)
 if Medium.nXi > 0 "Conversion from x_i to X_w"
    ;

  RealVectorExpression XiSup(
    final n=Medium.nXi,
    final y=inStream(ports[1].Xi_outflow))
    if Medium.nXi > 0
      "Water vapor concentration of supply air"
    ;

  RealVectorExpression CSup(
    final n=Medium.nC,
    final y=inStream(ports[1].C_outflow))
 if Medium.nC > 0 "Trace substance concentration of supply air"
    ;

  Sources.MassFlowSource_T bou[nPorts](
    each final nPorts=1,
    redeclare each final package Medium = Medium,
    each final use_T_in=true,
    each final use_C_in=Medium.nC > 0,
    each final use_X_in=Medium.nXi > 0,
    each use_m_flow_in=true) "Mass flow source"
    ;

  Conversion.InletToAir con[nPorts](redeclare each final package Medium =
        Medium) "Connector between FMI signals and real input and real outputs"
    ;

  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor senTemAir
    "Room air temperature sensor"
    ;

  BaseClasses.X_w_toX x_w_toX[nPorts](redeclare final package Medium = Medium)
    if Medium.nXi > 0 "Conversion from X_w to X"
    ;

  Modelica.Blocks.Math.MultiSum multiSum(final nu=nPorts, final k=fill(1,
        nPorts)) "Sum of air mass flow rates"
    ;

  IDEAS.Utilities.Diagnostics.AssertEquality assEqu(
    message="\"Mass flow rate does not balance. The sum needs to be zero.",
      threShold=1E-4)
    "Tests whether the mass flow rates balance to zero"
    ;
  Modelica.Blocks.Sources.Constant const(final k=0) "Outputs zero"
    ;

  ///////////////////////////////////////////////////////////////////////////
  // Internal blocks
  block RealVectorExpression
    "Set vector output signal to a time varying vector Real expression"
    parameter Integer n "Dimension of output signal";
    Modelica.Blocks.Interfaces.RealOutput[n] y "Value of Real output"

    ;
  end RealVectorExpression;

  block x_i_toX_w "Conversion from Xi to X"
    extends Modelica.Blocks.Icons.Block;

    replaceable package Medium =
      Modelica.Media.Interfaces.PartialMedium "Medium model within the source"
     ;
    Modelica.Blocks.Interfaces.RealInput Xi[Medium.nXi](each final unit="kg/kg")
   if Medium.nXi > 0 "Water vapor concentration in kg/kg total air"
      ;

    Modelica.Blocks.Interfaces.RealOutput X_w(
      final unit="kg/kg") "Water vapor concentration in kg/kg total air"
      ;
  protected
    Modelica.Blocks.Interfaces.RealInput Xi_internal[Medium.nXi](
      each final unit = "kg/kg")
      "Internal connector for water vapor concentration in kg/kg total air";

    Modelica.Blocks.Interfaces.RealInput X_w_internal(
      final unit = "kg/kg")
      "Internal connector for water vapor concentration in kg/kg total air";

  equation
  // Conditional connector
  connect(Xi_internal, Xi);
  if Medium.nXi == 0 then
    Xi_internal = zeros(Medium.nXi);
  end if;

  X_w_internal = sum(Xi_internal);
  connect( X_w, X_w_internal)
  ;
  end x_i_toX_w;

initial equation
   assert(Medium.nXi < 2,
   "The medium must have zero or one independent mass fraction Medium.nXi.");
equation

  for i in 1:nPorts loop
    connect(bou[i].ports[1], ports[i]) ;
  end for;
  connect(con.inlet, fluPor)
    ;
  connect(con.X_w, x_w_toX.X_w) ;

  connect(x_w_toX.X, bou.X_in)
    ;
  connect(con.C, bou.C_in) ;
  connect(heaPorAir, senTemAir.port) ;
  connect(XiSup.y, x_i_toX.Xi)
    ;
  connect(con.T, bou.T_in) ;
  connect(con[1:nPorts].m_flow, multiSum.u[1:nPorts]) ;
  connect(multiSum.y, assEqu.u2) ;
  connect(const.y, assEqu.u1) ;
  for i in 1:nPorts loop
  connect(senTemAir.T, con[i].TAirZon) ;
  if Medium.nXi > 0 then
    connect(x_i_toX.X_w, con[i].X_wZon) ;
  end if;
  connect(CSup.y, con[i].CZon)
    ;
  end for;
  connect(bou.m_flow_in, con.m_flow) 
  ;
end ThermalZone;

within IDEAS.Fluid.HeatPumps.Validation;
model Carnot_TCon_reverseFlow
  "Test model for heat pump based on Carnot efficiency and condenser outlet temperature control signal"
  extends Modelica.Icons.Example;
 package Medium1 = IDEAS.Media.Water "Medium model";
 package Medium2 = IDEAS.Media.Water "Medium model";

  parameter Modelica.Units.SI.TemperatureDifference dTEva_nominal=-10
    "Temperature difference evaporator inlet-outlet";
  parameter Modelica.Units.SI.TemperatureDifference dTCon_nominal=10
    "Temperature difference condenser outlet-inlet";
  parameter Modelica.Units.SI.HeatFlowRate QCon_flow_nominal=100E3
    "Evaporator heat flow rate";
  parameter Modelica.Units.SI.MassFlowRate m1_flow_nominal=QCon_flow_nominal/
      dTCon_nominal/4200 "Nominal mass flow rate at condenser";

  Modelica.Blocks.Sources.Constant TConLvg(k=273.15 + 40)
    "Control signal for condenser leaving temperature"
    ;

  final parameter Modelica.Units.SI.SpecificHeatCapacity cp2_default=
      Medium2.specificHeatCapacityCp(Medium2.setState_pTX(
      Medium2.p_default,
      Medium2.T_default,
      Medium2.X_default))
    "Specific heat capacity of medium 2 at default medium state";
  Modelica.Blocks.Sources.Ramp mCon_flow(
    duration=60,
    startTime=1800,
    height=-2*m1_flow_nominal,
    offset=m1_flow_nominal) "Mass flow rate for condenser"
    ;
  Carnot_TCon heaPum(
    redeclare package Medium1 = Medium1,
    redeclare package Medium2 = Medium2,
    dTEva_nominal=dTEva_nominal,
    dTCon_nominal=dTCon_nominal,
    m1_flow_nominal=m1_flow_nominal,
    show_T=true,
    use_eta_Carnot_nominal=true,
    etaCarnot_nominal=0.3,
    QCon_flow_nominal=QCon_flow_nominal,
    allowFlowReversal1=true,
    allowFlowReversal2=true,
    dp1_nominal=6000,
    dp2_nominal=6000) "Heat pump"
    ;
  Sources.MassFlowSource_T sou1(nPorts=1,
    redeclare package Medium = Medium1,
    use_m_flow_in=true,
    T=293.15)
    ;
  Sources.MassFlowSource_T sou2(nPorts=1,
    redeclare package Medium = Medium2,
    use_T_in=false,
    use_m_flow_in=true,
    T=288.15)
    ;
  IDEAS.Fluid.Sources.Boundary_pT sin1(
    redeclare package Medium = Medium1,
    nPorts=1)
    ;
  IDEAS.Fluid.Sources.Boundary_pT sin2(
    nPorts=1,
    redeclare package Medium = Medium2)
    ;
  Modelica.Blocks.Math.Gain mEva_flow(k=-1/cp2_default/dTEva_nominal)
    "Evaporator mass flow rate"
    ;
  Modelica.Blocks.Math.Add QEva_flow(k2=-1) "Evaporator heat flow rate"
    ;
equation
  connect(sou1.ports[1],heaPum. port_a1) ;
  connect(sou2.ports[1],heaPum. port_a2) ;
  connect(sin2.ports[1],heaPum. port_b2) ;
  connect(QEva_flow.y,mEva_flow. u) ;
  connect(heaPum.port_b1,sin1. ports[1]) ;
  connect(mEva_flow.y, sou2.m_flow_in) ;
  connect(TConLvg.y, heaPum.TSet) ;
  connect(mCon_flow.y, sou1.m_flow_in) ;
  connect(heaPum.QCon_flow, QEva_flow.u1) ;
  connect(QEva_flow.u2, heaPum.P) 
  ;
end Carnot_TCon_reverseFlow;

within IDEAS.Buildings.Examples;
model ZoneCO2 "Zone with CO2 concentration model"
  extends Modelica.Icons.Example;
  replaceable package Medium = IDEAS.Media.Air(extraPropertiesNames={"test", "CO2"});
  inner BoundaryConditions.SimInfoManager       sim
    "Simulation information manager for climate data"
    ;

  IDEAS.Buildings.Components.Examples.BaseClasses.SimpleZone zone(
    redeclare Components.Occupants.Input occNum,
    redeclare package Medium = Medium)
    "Zone model"
    ;
  Modelica.Blocks.Sources.Pulse pulse(
    offset=0,
    period=7200,
    amplitude=5)
              ;

  IDEAS.Fluid.Sources.Boundary_pT bou(
    redeclare package Medium = Medium, nPorts=1)
    "Ideal pressure source"
    ;
  IDEAS.Fluid.Sources.MassFlowSource_T boundary(
    redeclare package Medium = Medium,
    use_T_in=true,
    use_Xi_in=true,
    use_C_in=true,
    use_m_flow_in=true,
    nPorts=1)           "Ideal flow rate source" ;
  Modelica.Blocks.Logical.Hysteresis hys(uLow=750, uHigh=850)
    "Hysteresis controller using CO2 concentration" ;
  Modelica.Blocks.Math.BooleanToReal m_flow(              realFalse=0, realTrue=
       0.04)
    "Flow rate when ventilation is enabled" ;
protected
  BoundaryConditions.WeatherData.Bus weaDatBus1
                            "Weather data bus connectable to weaBus connector from Buildings Library"
    ;
  Modelica.Blocks.Sources.RealExpression CEnv[max(Medium.nC,1)](y=sim.CEnv.y*
        s_co2)
    ;
protected
  final parameter Real s_co2[max(Medium.nC,1)] = {if Modelica.Utilities.Strings.isEqual(string1=if Medium.nC>0 then Medium.extraPropertiesNames[i] else "",
                                             string2="CO2",
                                             caseSensitive=false)
                                             then 1 else 0 for i in 1:max(Medium.nC,1)};

equation
  connect(pulse.y, zone.yOcc) ;
  connect(sim.weaDatBus, weaDatBus1) ;
  connect(boundary.T_in, weaDatBus1.TDryBul)
    ;
  connect(boundary.Xi_in[1], weaDatBus1.X_wEnv)
    ;
  connect(hys.u, zone.ppm)
    ;
  connect(m_flow.y, boundary.m_flow_in)
    ;
  connect(m_flow.u, hys.y)
    ;
  connect(CEnv.y, boundary.C_in)
    ;
  connect(boundary.ports[1], zone.ports[2])
    ;
  connect(bou.ports[1], zone.ports[1])

  ;
end ZoneCO2;

