model PPM "Test model for the extra property sensor outputting PPM"
  extends Modelica.Icons.Example;
  package Medium = IDEAS.Media.Air(extraPropertiesNames={"CO2"})
    "Medium model";

  parameter Modelica.Units.SI.MassFlowRate m_flow_nominal=volDyn.V*
      senPPMTwoPort.tau*3*rho_default
    "Mass flow rate into and out of the volume";

  IDEAS.Fluid.MixingVolumes.MixingVolume volDyn(
    redeclare package Medium = Medium,
    nPorts=3,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    V=1,
    use_C_flow=true,
    m_flow_nominal=m_flow_nominal) "Mixing volume with dynamics"
    ;
  IDEAS.Fluid.Sources.MassFlowSource_T mSou(
    redeclare package Medium = Medium,
    nPorts=2,
    m_flow=m_flow_nominal) "Fresh air supply"
    ;

  IDEAS.Fluid.Sensors.PPM senPPMVol(
    redeclare package Medium = Medium,
    warnAboutOnePortConnection=false)
    "PPM sensor for mixing volume"
    ;
  Modelica.Blocks.Sources.Constant CO2In(k=m_flow_nominal/1000)
    "CO2 mass flow rate entering mixing volume"
    ;
  IDEAS.Fluid.Sensors.PPMTwoPort senPPMTwoPort(
    redeclare package Medium = Medium,
    allowFlowReversal=true,
    m_flow_nominal=m_flow_nominal) "PPM sensor" ;
  IDEAS.Fluid.Sensors.PPM senPPMIn(redeclare package Medium = Medium,
      warnAboutOnePortConnection=false)
    "PPM sensor for inlet"
    ;
  IDEAS.Fluid.Sensors.PPMTwoPort senPPMNoRev(
    redeclare package Medium = Medium,
    allowFlowReversal=false,
    m_flow_nominal=m_flow_nominal) "PPM sensor without flow reversal disabled"
    ;
  IDEAS.Fluid.Sensors.PPMTwoPort senPPMRev(
    redeclare package Medium = Medium,
    allowFlowReversal=true,
    m_flow_nominal=m_flow_nominal) "PPM sensor with flow in reverse direction"
    ;
  IDEAS.Fluid.Sensors.PPMTwoPort senPPMSta(
    redeclare package Medium = Medium,
    allowFlowReversal=true,
    tau=0,
    m_flow_nominal=m_flow_nominal) "Static PPM sensor" ;
  IDEAS.Fluid.MixingVolumes.MixingVolume volSte(
    redeclare package Medium = Medium,
    nPorts=3,
    V=1,
    use_C_flow=true,
    m_flow_nominal=m_flow_nominal,
    energyDynamics=Modelica.Fluid.Types.Dynamics.SteadyState)
    "Mixing volume without dynamics"
    ;
  IDEAS.Fluid.Sensors.PPM senPPMVol2( redeclare package Medium = Medium,
      warnAboutOnePortConnection=false)
    "PPM sensor for mixing volume"
    ;
  IDEAS.Fluid.Sources.MassFlowSource_T mSouSta(
    redeclare package Medium = Medium,
    nPorts=1,
    m_flow=m_flow_nominal) "Fresh air supply for steady state volume"
    ;
  IDEAS.Fluid.Sources.Boundary_pT sin(
    redeclare package Medium = Medium,
    nPorts=2) "Exhaust air"
    ;

protected
  final parameter Medium.ThermodynamicState state_default = Medium.setState_pTX(
      T=Medium.T_default,
      p=Medium.p_default,
      X=Medium.X_default[1:Medium.nXi]) "Medium state at default values";
  // Density at medium default values, used to compute the size of control volumes
  final parameter Modelica.Units.SI.Density rho_default=Medium.density(state=
      state_default) "Density, used to compute fluid mass";

equation
  connect(mSou.ports[1], volDyn.ports[1]) ;
  connect(CO2In.y, volDyn.C_flow[1]) ;
  connect(senPPMVol.port, volDyn.ports[2]) ;
  connect(senPPMIn.port, mSou.ports[2])
    ;
  connect(senPPMTwoPort.port_a, volDyn.ports[3]) ;
  connect(senPPMNoRev.port_a, senPPMTwoPort.port_b)
    ;
  connect(senPPMRev.port_b, senPPMNoRev.port_b) ;
  connect(senPPMSta.port_a, senPPMRev.port_a)
    ;
  connect(CO2In.y,volSte. C_flow[1]) ;
  connect(volSte.ports[1], senPPMVol2.port) ;
  connect(mSouSta.ports[1], volSte.ports[2]) ;
  connect(sin.ports[1], senPPMSta.port_b) ;
  connect(sin.ports[2], volSte.ports[3]) 
    ;
end PPM;

within IDEAS.Buildings.Validation.BaseClasses.HeatingSystem;
model Bangbang "BESTEST bang-bang heating system"
  extends IDEAS.Templates.Interfaces.BaseClasses.HeatingSystem(
    final nEmbPorts = 0, final nLoads=1, final nTemSen = nZones);

  parameter Modelica.Units.SI.Volume[nZones] VZones;
  parameter Real mSenFac = 5 "Correction factor for thermal mass in zone";
  parameter Real[nZones] C = VZones * mSenFac * 1012 * 1.204;

protected
  parameter Modelica.Units.SI.Temperature Theat=293.15
    "Heating on below 20degC";
  parameter Modelica.Units.SI.Temperature Tcool=293.15
    "Cooling on above 27degC";

equation
  for i in 1:nZones loop
    if Theat > TSensor[i] then
      heatPortCon[i].Q_flow = -100*C[i]*(Theat - TSensor[i]);
    elseif Tcool < TSensor[i] then
      heatPortCon[i].Q_flow = -100*C[i]*(Tcool - TSensor[i]);
    else
      heatPortCon[i].Q_flow = 0;
    end if;

    heatPortRad[i].Q_flow = 0;
  end for;
  heatPortEmb.Q_flow=zeros(nEmbPorts)


  ;
end Bangbang;

within IDEAS.Utilities.Math.Functions.Examples;
model InverseXDerivativeCheck
  "Model that checks the correct implementation of the 1st order derivative of InverseXRegularized"
  extends Modelica.Icons.Example;

  constant Real gain = 4 "Gain for computing the mass flow rate";

  parameter Real delta = 0.7 "Smoothing coefficient";

  Real x "Independent variable";
  Real y_comp "Comparison value";
  Real y "Dependent variable";

  Real err "Integration error";
initial equation
 y = y_comp;
equation
  x = time^3*gain;
  y = IDEAS.Utilities.Math.Functions.inverseXRegularized(
    x = x,
    delta = delta);
  der(y_comp) = IDEAS.Utilities.Math.Functions.BaseClasses.der_inverseXRegularized(x=x,delta=delta,x_der=der(x));
  err = y-y_comp;
  assert(abs(err) < 1E-3, "Error in implementation.")
;
end InverseXDerivativeCheck;

