within IDEAS.Utilities.Math.Functions.Examples;
model IsMonotonic
  "Tests the correct implementation of the function isMonotonic"
  extends Modelica.Icons.Example;
  Real x_incStrict[3] = {0, 1, 2} "strictly increasing";
  Real x_notMon[3] = {0, 3, 2} "not monotonic";
  Real x_incWeak[4] = {0, 1, 1, 2} "weakly increasing";
  Real x_notWeak[4] = {0, 3, 3, 2} "not weakly monotonic";
  Real x_decStrict[3] = {2.5, 2, 0.1} "strictly decreasing";
  Real x_decWeak[4] = {3, 1, 1, 0.5} "weakly decreasing";

equation
// Tests with weak monotonicity
    //strictly increasing
assert(IDEAS.Utilities.Math.Functions.isMonotonic(x_incStrict, strict=false),
   "Error. Function should have returned true.");
     //not monotonic
assert(false == IDEAS.Utilities.Math.Functions.isMonotonic(x_notMon, strict=false),
   "Error. Function should have returned true.");
     //weakly increasing
assert(IDEAS.Utilities.Math.Functions.isMonotonic(x_incWeak, strict=false),
   "Error. Function should have returned true.");
     //not weakly monotonic
assert(false == IDEAS.Utilities.Math.Functions.isMonotonic(x_notWeak, strict=false),
   "Error. Function should have returned true.");

    //strictly decreasing
assert(IDEAS.Utilities.Math.Functions.isMonotonic({2.5, 2, 0.1}, strict=false),
   "Error. Function should have returned true.");
     //weakly decreasing
assert(IDEAS.Utilities.Math.Functions.isMonotonic({3, 1, 1, 0.5}, strict=false),
   "Error. Function should have returned true.");

// Tests with strict monotonicity
    //strictly increasing
assert(IDEAS.Utilities.Math.Functions.isMonotonic(x_incStrict, strict=true),
   "Error. Function should have returned true.");
     //not monotonic
assert(false == IDEAS.Utilities.Math.Functions.isMonotonic(x_notMon, strict=true),
   "Error. Function should have returned true.");
     //weakly increasing
assert(false == IDEAS.Utilities.Math.Functions.isMonotonic(x_incWeak, strict=true),
   "Error. Function should have returned true.");
     //not weakly monotonic
assert(false == IDEAS.Utilities.Math.Functions.isMonotonic(x_notWeak, strict=true),
   "Error. Function should have returned true.");

    //strictly decreasing
assert(IDEAS.Utilities.Math.Functions.isMonotonic(x_decStrict, strict=true),
   "Error. Function should have returned true.");
     //weakly decreasing
assert(false == IDEAS.Utilities.Math.Functions.isMonotonic(x_decWeak, strict=true),
   "Error. Function should have returned true.")

  ;
end IsMonotonic;

within IDEAS.Buildings.Components.BaseClasses.ConvectiveHeatTransfer;
model CavityAirflow "Model for air flow through a cavity"
  parameter Boolean linearise = false
    "=true, to linearise the relation between heat flow rate and temperature difference";

  parameter Real CD=0.65 "Discharge coefficient";
  parameter Modelica.Units.SI.Length h=2
    "Height of (rectangular) cavity in wall";
  parameter Modelica.Units.SI.Length w=1
    "Width of (rectangular) cavity in wall";
  parameter Modelica.Units.SI.Acceleration g=Modelica.Constants.g_n
    "Gravity, for computation of buoyancy";
  parameter Modelica.Units.SI.Pressure p=101300
    "Absolute pressure for computation of buoyancy";
  parameter Modelica.Units.SI.Density rho=p/r/T
    "Nominal density for computation of buoyancy mass flow rate";
  parameter Modelica.Units.SI.SpecificHeatCapacity c_p=1013
    "Nominal heat capacity for computation of buoyancy heat flow rate";
  parameter Modelica.Units.SI.Temperature T=293
    "Nominal temperature for linearising heat flow rate";
  parameter Modelica.Units.SI.TemperatureDifference dT=1
    "Nominal temperature difference when linearising heat flow rate"
    ;

  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a port_a
    "Port for connections between layers"
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_b port_b
    "Port for connections between layers"
    ;
protected
  constant Real r = 287 "Gas constant";
  // Assuming the same entering and leaving flow rate
  // between .bottom and top half of the cavity
  // Assuming uniform flow through both parts.
  // dp= rho * g * h/4 * (1-T1/T2) - buoyancy: horizontal pressure differences
  // factor 4: distance between door center and center of top/bottom door half
  // v = sqrt(2 * dp/rho) - Bernoulli
  // dotm = v*h/2*w*rho*cp  - Mass flow rate
  // G = dotm * c_p
  final parameter Real coeff1 = CD*c_p*rho*w*h/2*sqrt(0.5*g*h) "Bernoulli-based thermal conductance";
  final parameter Real coeff2 = sqrt(abs(1-T/(T+dT)));
  Modelica.Units.SI.ThermalConductance G=coeff1*(if linearise then coeff2 else
      sqrt(abs(1 - port_a.T/port_b.T)));
    // We don't need a regularisation for the square root since this
    // equation should not end up in an algebraic loop
    // when used correctly in IDEAS.
    // However, laminar flow could be approximated better.

equation

  port_a.Q_flow+port_b.Q_flow=0;
  port_a.Q_flow=(port_a.T-port_b.T)*G
  ;
end CavityAirflow;

