          1:nConvPorts}) + sum({max(0, heatPortRad[i].Q_flow) for i in 1:
      nRadPorts}) + sum({max(0, heatPortEmb[i].Q_flow) for i in 1:nEmbPorts})
    "Total thermal power use for cooling";

