within IDEAS.Experimental.Electric.BaseClasses.AC;
model WattsLawPlug "For use  with loads."
  parameter Integer numPha=1 "Choose the number of phases" ;
  parameter Integer nLoads=1;
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.NegativePlug vi(m=numPha)
    ;
  Modelica.Blocks.Interfaces.RealInput[nLoads] P ;
  Modelica.Blocks.Interfaces.RealInput[nLoads] Q ;

  Modelica.Blocks.Math.Sum sum_P(final nin=nLoads)
    ;
  Modelica.Blocks.Math.Sum sum_Q(final nin=nLoads)
    ;
equation
  for i in 1:numPha loop
    sum_P.y/numPha = Modelica.ComplexMath.real(vi.pin[i].v*
      Modelica.ComplexMath.conj(vi.pin[i].i));
    sum_Q.y/numPha = Modelica.ComplexMath.imag(vi.pin[i].v*
      Modelica.ComplexMath.conj(vi.pin[i].i));
  end for;

  connect(P, sum_P.u) ;
  connect(Q, sum_Q.u) 
  ;
end WattsLawPlug;

within IDEAS.Utilities.Psychrometrics.Functions;
function density_pTX
  "Density of air as a function of pressure, temperature and species concentration"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Absolute pressure of the medium";
  input Modelica.Units.SI.Temperature T "Dry bulb temperature";
  input Modelica.Units.SI.MassFraction X_w
    "Water vapor mass fraction per unit mass total air";
  output Modelica.Units.SI.Density d "Mass density";
protected
  Modelica.Units.SI.SpecificHeatCapacity R
    "Gas constant (of mixture if applicable)";
algorithm
  R :=Modelica.Media.IdealGases.Common.SingleGasesData.Air.R_s*(1 - X_w) +
    Modelica.Media.IdealGases.Common.SingleGasesData.H2O.R_s*X_w;
  d := p/(R*T)

  ;
end density_pTX;

