function powerLawFixedM
  "Power law used in orifice equations when m is constant"
  extends Modelica.Icons.Function;

  input Real C "Flow coefficient, C = V_flow/ dp^m";
  input Modelica.Units.SI.PressureDifference dp(displayUnit="Pa")
    "Pressure difference";
  input Real m(min=0.5, max=1)
    "Flow exponent, m=0.5 for turbulent, m=1 for laminar";
  input Real a "Polynomial coefficient";
  input Real b "Polynomial coefficient";
  input Real c "Polynomial coefficient";
  input Real d "Polynomial coefficient";
  input Modelica.Units.SI.PressureDifference dp_turbulent(min=0) = 0.001
    "Pressure difference where regularization starts";
  output Modelica.Units.SI.VolumeFlowRate V_flow "Volume flow rate";
protected
  constant Real gamma(min=1) = 1.5
    "Normalized flow rate where dphi(0)/dpi intersects phi(1)";
  Real pi "Normalized pressure";
  Real pi2 "Square of normalized pressure";
algorithm
 if (dp >= dp_turbulent) then
   V_flow :=C *dp^m;
 elseif (dp <= -dp_turbulent) then
   V_flow :=-C*(-dp)^m;
 else
   pi  := dp/dp_turbulent;
   pi2 := pi*pi;
   V_flow :=C *dp_turbulent^m * pi * ( a + pi2 * ( b + pi2 * ( c + pi2 * d)));
 end if

  ;
end powerLawFixedM;

within IDEAS.Utilities.Math;
block MovingAverage "Calculates the moving average of a Real input"

  extends Modelica.Blocks.Interfaces.SISO;

  parameter Modelica.Units.SI.Time period=1
    "Period over wich running average is to be computed";

  parameter Real resetIntegral(min=10) = 1000000
    "Number of period before reseting the integral of the moving average"
    ;

protected
  Real iDelay "delayed integration";
  Real iStop(start=0, fixed=true) "integrator until stop time";

initial algorithm
  iDelay := -u*period;

equation
  der(iStop) = u;
  der(iDelay) = delay(
    u,
    period,
    period);

  when sample(resetIntegral*period,resetIntegral*period) then
    reinit(iStop,iStop - iDelay);
    reinit(iDelay,0);
  end when;

  if time >= 0.1 and time <= period then
    y = iStop/time;
  elseif time > period then
    y = (iStop - iDelay)/period;
  else
    y = u;
  end if;

end MovingAverage;

