within IDEAS.Experimental.Electric.Photovoltaics.Components;
model PvVoltageCtrlGeneral_InputVGrid
  "Basic controller, with fixed shut down time, with RealInput for grid voltage"

  //extends Modelica.Blocks.Interfaces.BlockIcon;

  parameter Real VMax=253;
  parameter Real timeOff=300;
  parameter Integer numPha=1
    "1 or 3, just indicates if it's a single or 3 phase PV system";

  Boolean switch(start=true, fixed=true) "if true, system is producing";

  Modelica.Blocks.Interfaces.RealInput PInit ;
  Modelica.Blocks.Interfaces.RealInput QInit ;
  Modelica.Blocks.Interfaces.RealOutput PFinal
    ;
  Modelica.Blocks.Interfaces.RealOutput QFinal
    ;

  discrete Real restartTime(start=-1, fixed=true)
    "system is off until time>restartTime";

public
  Modelica.Blocks.Interfaces.RealInput VGrid ;
equation

  when {VGrid > VMax,time > pre(restartTime)} then
    if VGrid > VMax and time > pre(restartTime) then
      // some voltage limit was crossed while system was on.  Switch off and set restarttime
      switch = false;
      restartTime = time + timeOff;
    elseif VGrid > VMax and time < pre(restartTime) then
      // some voltage limit was crossed during an offtime: keep off but don't change the restarTime
      switch = false;
      restartTime = pre(restartTime);
    else
      switch = true;
      restartTime = -1;
    end if;
  end when;

  if pre(switch) then
    PFinal = PInit;
  else
    PFinal = 0;
  end if;

  QFinal = QInit

  ;
end PvVoltageCtrlGeneral_InputVGrid;

within IDEAS.Controls.ControlHeating;
model Ctrl_Heating_TES_SetBack_MinOffTime
  "Heating curve control for heating based on a water storage tank, temperature set back + minimum off-time"
  extends Interfaces.Partial_Ctrl_Heating_TES;

  parameter Modelica.Units.SI.Time timeOff=60*15;
  Real debug(start=-1);
  Real smoothed;

  Modelica.Blocks.Sources.CombiTimeTable daytime(extrapolation=Modelica.Blocks.Types.Extrapolation.Periodic,
      table=[0, 0; 43200, 0; 43200, 1; 68400, 1; 68400, 0; 86400, 0])
    "Defines daytime, means period where storage tank can be charged"
    ;
  // this timer gives 0 during timing and 1 outside of timing
  IDEAS.BaseClasses.Control.Timer_NoEvents timerOff(duration=timeOff)
    ;
equation
  smoothed = smooth(1, timerOff.y);
  TTopSet = max(TDHWSet, heatingCurve.TSup) + dTSafetyTop + smooth(1, daytime.y[
    1])*5;
  TBotSet = max(TDHWSet, heatingCurve.TSup) + dTSafetyBot + smooth(1, daytime.y[
    1])*5;
  THPSet = TTopSet + dTHPTankSet;

  if noEvent(smooth(2, timerOff.y) > 0.5) then
    // with noEvent it is NOT possible to run this model:
    // Error: Cannot reduce the DAE index and select states.
    if noEvent(TTankTop < TTopSet and TTankBot < (TBotSet - dTSafetyBot)) then
      // top too cold, off-time passed: system MUST be on except if bottom is still very hot (temp inversion?)
      onOff = 1;
      debug = 1;
    elseif noEvent(TTankBot < TBotSet and onOff > 0.5) then
      // HP running, top is fine, bottom too cold: keep running
      onOff = 1;
      debug = 2;
    else
      // all other cases: shut down
      onOff = 0;
      debug = 3;
    end if;
  else
    onOff = 0;
    debug = 4;
  end if;

algorithm
  timerOff.u := onOff

  ;
end Ctrl_Heating_TES_SetBack_MinOffTime;

within IDEAS.Fluid.HeatExchangers.BaseClasses;
function dynamicViscosityWater "Returns the dynamic viscosity for water"
  input Modelica.Units.SI.Temperature T "Thermodynamic state record";
  output Modelica.Units.SI.DynamicViscosity mu "Dynamic viscosity";
algorithm
        mu := ((2.86651*10^(-5))*T^4-0.039376307*T^3+20.32805026*T^2-
        4680.303158*T+406389.0375)*10^(-6);
        //Equation is a fourth order polynomial fit to data from Fundamentals of
        //Heat and Mass Transfer (Fourth Edition), Frank Incropera & David DeWitt,
        //John Wiley & Sons, 1996

;
end dynamicViscosityWater;

