    CSmax=5,
    permOxPeriodPerc=5,
    nOxMin=3,
    AntiWindup=true,
    CSmin=-5,
    pm=65)
    ;
  Controllers.AutoTuning.ATPIrelayNCmixedMode
                R_iD(
    Ts=0.1,
    CSmax=5,
    Kp=5,
    Ti=30,
    slope=0.01,
    CSmin=-5,
    nOxMin=3,
    permOxPeriodPerc=30,
    pm=70,
    AntiWindup=true)
    ;
  Controllers.AutoTuning.ATPIrelayNCmixedMode
                R_OS(
    Ts=0.1,
    CSmin=0,
    CSmax=5,
    permOxPeriodPerc=5,
    pm=65,
    nOxMin=3,
    AntiWindup=true)
    ;
  Controllers.AutoTuning.ATPIrelayNCmixedMode
                R_US(
    Ts=0.1,
    CSmin=0,
    CSmax=5,
    slope=0.05,
    pm=45,
    Ti=1,
    Kp=0.1,
    permOxPeriodPerc=5,
    nOxMin=3,
    AntiWindup=true)
    ;
  Controllers.AutoTuning.ATPIrelayNCmixedMode
                R_Osc(
    Ts=0.1,
    CSmin=0,
    CSmax=5,
    Ti=5,
    Kp=1,
    permOxPeriodPerc=5,
    pm=65,
    nOxMin=3,
    slope=0.1,
    AntiWindup=true)
    ;
  Controllers.AutoTuning.ATPIrelayNCmixedMode
                R_FS(
    Ts=0.1,
    CSmin=0,
    CSmax=5,
    permOxPeriodPerc=5,
    pm=65,
    nOxMin=3,
    AntiWindup=true)
    ;
  Modelica.Blocks.Sources.BooleanTable      ATpulse(table={120,120.1})
                          ;
equation
  connect(step.y, NoControl.FO_u) ;
  connect(step.y, NoControl.FOD_u) ;
  connect(step.y, NoControl.i_u) ;
  connect(step.y, NoControl.iD_u) ;
  connect(step.y, NoControl.OS_u) ;
  connect(step.y, NoControl.Osc_u) ;
  connect(R_FO.CS, Controlled.FO_u) ;
  connect(Controlled.FO_y, R_FO.PV) ;
  connect(step.y, R_FO.SP) ;
  connect(step.y, R_FOD.SP) ;
  connect(R_FOD.CS, Controlled.FOD_u) ;
  connect(Controlled.FOD_y, R_FOD.PV) ;
  connect(step.y, R_i.SP) ;
  connect(R_i.CS, Controlled.i_u) ;
  connect(Controlled.i_y, R_i.PV) ;
  connect(R_iD.CS, Controlled.iD_u) ;
  connect(Controlled.iD_y, R_iD.PV) ;
  connect(step.y, R_OS.SP) ;
  connect(R_OS.CS, Controlled.OS_u) ;
  connect(Controlled.OS_y, R_OS.PV) ;
  connect(step.y, R_Osc.SP) ;
  connect(R_Osc.CS, Controlled.Osc_u) ;
  connect(Controlled.Osc_y, R_Osc.PV) ;
  connect(step.y, NoControl.FS_u) ;
  connect(step.y, R_FS.SP) ;
  connect(R_FS.CS, Controlled.FS_u) ;
  connect(Controlled.FS_y, R_FS.PV) ;

  connect(ATpulse.y, R_FO.ATreq) ;
  connect(ATpulse.y, R_FOD.ATreq) ;
  connect(ATpulse.y, R_i.ATreq) ;
  connect(ATpulse.y, R_OS.ATreq) ;
  connect(ATpulse.y, R_Osc.ATreq) ;
  connect(ATpulse.y, R_FS.ATreq) ;
  connect(step.y, NoControl.US_u) ;
  connect(R_US.CS, Controlled.US_u) ;
  connect(Controlled.US_y, R_US.PV) ;
  connect(ATpulse.y, R_iD.ATreq) ;
  connect(R_US.ATreq, ATpulse.y) ;
  connect(R_iD.SP, step.y) ;
  connect(R_US.SP, step.y) 
  ;
end ATProcessControl;

