  connect(PID_inner_extLock.satHI, PID_outer_extLock.Finc) ;
  connect(PID_inner_extLock.satLOW, PID_outer_extLock.Fdec) ;
  connect(P1.y, PID_inner_extLock.PV) ;
  connect(PID_inner.CS, P3.u) ;
  connect(P3.y, P4.u) ;
  connect(P4.y, PID_outer.PV) ;
  connect(SetPoint.y, PID_outer.SP) ;
  connect(PID_outer.CS, PID_inner.SP) ;
  connect(P3.y, PID_inner.PV) 
  ;
end CascadeAntiWindup;

within IndustrialControlSystems.Applications.ControlProblems;
model CascadeControl "Cascade control"
  extends Modelica.Icons.Example;
  parameter Real Ts = 0.5 "|Sampling time| Outer loop sampling time";
  parameter Real Ts_inner = 0.01 "|Sampling time| Inner loop sampling time";
  LinearSystems.Continuous.TransferFunction
                                      P1(
    y_start=0,
    num={1},
    den={0.05,1})
          ;
  LinearSystems.Continuous.TransferFunction
                                      P2(
    y_start=0,
    num={1},
    den={1,2,1})
          ;
  Controllers.PI            R(
    CSmax=5,
    CSmin=0,
    Ti=1,
    Kp=0.5,
    Ts=Ts,
    CS_start=0,
    AntiWindup=true)
    ;
  Modelica.Blocks.Math.Add add
    ;
  Modelica.Blocks.Sources.Step Disturb(height=-2, startTime=50)
    ;
  LinearSystems.Continuous.TransferFunction
                                      P_inner(
    y_start=0,
    num={1},
    den={0.05,1})
          ;
  LinearSystems.Continuous.TransferFunction
                                        P_outer(
    y_start=0,
    num={1},
    den={1,2,1})
          ;
  Controllers.PI R_outer(
    CSmax=5,
    CSmin=0,
    Ti=1,
    Kp=0.5,
    Ts=Ts,
    CS_start=0,
    AntiWindup=true)
    ;
  Modelica.Blocks.Sources.Step SetPoint(height=1, startTime=2)
    ;
  Modelica.Blocks.Math.Add add_C
    ;
  Controllers.PI R_inner(
    CSmax=5,
    CSmin=0,
    Ti=0.05,
    Kp=5,
    Ts=Ts_inner,
    CS_start=0,
    AntiWindup=true)
    ;
equation
  connect(P2.y, R.PV)      ;
  connect(add.y, P2.u) ;
  connect(add.u2, P1.y) ;
  connect(Disturb.y, add.u1) ;
  connect(R.CS, P1.u) ;
  connect(P_outer.y, R_outer.PV)
                           ;
  connect(SetPoint.y, R_outer.SP)
                                 ;
  connect(add_C.y, P_outer.u)
                           ;
  connect(add_C.u2, P_inner.y)
                            ;
  connect(R_inner.CS, P_inner.u)
                           ;
  connect(Disturb.y, add_C.u1) ;
  connect(add_C.y, R_inner.PV)
                            ;
  connect(SetPoint.y, R.SP)  ;
  connect(R_outer.CS, R_inner.SP) 
  ;
end CascadeControl;

