model SmithPredictor "Smith predictor controller for delayed processes"
  extends Modelica.Icons.Example;

  LinearSystems.Continuous.TransferFunction process(num={1}, den={0.2,1.2,1})
    ;
  IndustrialControlSystems.LinearSystems.Continuous.Delay delay(T=8)
    ;
  Modelica.Blocks.Sources.Step SetPoint(height=1, startTime=2)
    ;
  LinearSystems.Continuous.TransferFunction processSmith1(num={1}, den={0.2,1.2,
        1}) ;
  IndustrialControlSystems.LinearSystems.Continuous.Delay delay1(T=8)
    ;
  Controllers.PI Regulator1(Ti=1, Kp=2,
    AntiWindup=true,
    CSmin=0,
    CSmax=2)
    ;
  LinearSystems.Continuous.TransferFunction processModel1(num={1}, den={0.2,1.2,
        1}) ;
  IndustrialControlSystems.LinearSystems.Continuous.SmithDelay smithDelay1(T=8)
    ;
  Modelica.Blocks.Math.Add add1
    ;
  LinearSystems.Continuous.TransferFunction processSmith2(num={1}, den={0.2,1.2,
        1}) ;
  IndustrialControlSystems.LinearSystems.Continuous.Delay delay2(T=8)
    ;
  Controllers.PI Regulator2(Ti=1, Kp=2,
    AntiWindup=true,
    CSmin=0,
    CSmax=2)
    ;
  LinearSystems.Continuous.TransferFunction processModel2(num={1}, den={1.2,1})
    ;
  IndustrialControlSystems.LinearSystems.Continuous.SmithDelay smithDelay2(T=8)
    ;
  Modelica.Blocks.Math.Add add2
    ;
equation
  connect(delay.y, process.u) ;
  connect(delay1.y, processSmith1.u) ;
  connect(Regulator1.CS, delay1.u) ;
  connect(SetPoint.y, Regulator1.SP) ;
  connect(processSmith1.y, add1.u1) ;
  connect(add1.y, Regulator1.PV) ;
  connect(SetPoint.y, delay.u) ;
  connect(Regulator1.CS, smithDelay1.u) ;
  connect(smithDelay1.y, processModel1.u) ;
  connect(processModel1.y, add1.u2) ;
  connect(delay2.y, processSmith2.u) ;
  connect(Regulator2.CS, delay2.u) ;
  connect(SetPoint.y, Regulator2.SP) ;
  connect(processSmith2.y, add2.u1) ;
  connect(add2.y, Regulator2.PV) ;
  connect(Regulator2.CS, smithDelay2.u) ;
  connect(smithDelay2.y, processModel2.u) ;
  connect(processModel2.y, add2.u2) 
  ;
end SmithPredictor;

within IndustrialControlSystems.Applications.ControlProblems.DecoupledControl;
model Decoupler "Model of the 2x2 decoupler"
  parameter Real P_21_22_num[:] = {1} "|P_21_22| Transfer function num.";
  parameter Real P_21_22_den[:] = {1,1} "|P_21_22| Transfer function den.";
  parameter Real P_12_11_num[:] = {1} "|P_12_11| Transfer function num.";
  parameter Real P_12_11_den[:] = {1,1} "|P_12_11| Transfer function den.";
  Modelica.Blocks.Interfaces.RealInput u1 "input" ;
  Modelica.Blocks.Interfaces.RealInput u2 "input" ;
  Modelica.Blocks.Interfaces.RealOutput y1 "output" ;
  Modelica.Blocks.Interfaces.RealOutput y2 "output" ;
  LinearSystems.Continuous.TransferFunction P_21_22(
                    num=P_21_22_num, den=P_21_22_den)
    ;
  LinearSystems.Continuous.TransferFunction P_12_11(num=P_12_11_num, den=
        P_12_11_den)
    ;
  Modelica.Blocks.Interfaces.RealOutput toU1 "output"
    ;
  Modelica.Blocks.Interfaces.RealOutput toU2 "output"
    ;
  Modelica.Blocks.Math.Gain gainA(k=-1)
    ;
  Modelica.Blocks.Math.Gain gainB(k=-1)
    ;
equation
  connect(u1, y1) ;
  connect(u2, y2) ;
  connect(P_21_22.y, gainA.u)
                         ;
  connect(gainB.u,P_12_11. y)
                         ;
  connect(u1, P_21_22.u) ;
  connect(u2, P_12_11.u) ;
  connect(gainA.y, toU2) ;
  connect(gainB.y, toU1) 
  ;
end Decoupler;

within IndustrialControlSystems.Applications.ControlProblems.DecoupledControl;
model Process "Two inputs Two outputs process
  Y1 = P11*u1 + P12*u2  and  Y2 = P21*u1 + P22*u2
  "
  parameter Real P11_num[:] = {1} "| P11 | Transfer function num.";
  parameter Real P11_den[:] = {1,1} "| P11 | Transfer function den.";
  parameter Real P12_num[:] = {1} "| P12 | Transfer function num.";
  parameter Real P12_den[:] = {1,1} "| P12 | Transfer function den.";
  parameter Real P21_num[:] = {1} "| P21 | Transfer function num.";
  parameter Real P21_den[:] = {1,1} "| P21 | Transfer function den.";
  parameter Real P22_num[:] = {1} "| P22 | Transfer function num.";
  parameter Real P22_den[:] = {1,1} "| P22 | Transfer function den.";
  LinearSystems.Continuous.TransferFunction
                                      P11(num=P11_num, den=P11_den)
    ;
  LinearSystems.Continuous.TransferFunction
                                      P12(num=P12_num, den=P12_den)
    ;
  LinearSystems.Continuous.TransferFunction
                                      P21(             den=P21_den, num=P21_num)
                                                         ;
  LinearSystems.Continuous.TransferFunction
                                      P22(num=P22_num, den=P22_den)
                                                       ;
  Modelica.Blocks.Interfaces.RealInput u1 "input" ;
  Modelica.Blocks.Interfaces.RealInput u2 "input" ;
  Modelica.Blocks.Interfaces.RealOutput y1 "output" ;
  Modelica.Blocks.Interfaces.RealOutput y2 "output" ;
  Modelica.Blocks.Math.Add add
    ;
  Modelica.Blocks.Math.Add add1
    ;
equation
  connect(P11.u, u1) ;
  connect(u1, P21.u) ;
  connect(u2, P12.u) ;
  connect(u2, P22.u) ;
  connect(P11.y, add.u1) ;
  connect(P12.y, add.u2) ;
  connect(add.y, y1) ;
  connect(P21.y, add1.u1) ;
  connect(P22.y, add1.u2) ;
  connect(add1.y, y2) 
  ;
end Process;

within IndustrialControlSystems.Applications.ProcessControl;
model CascadeLevelControl "Cascade level control with PI controllers"
  extends Modelica.Icons.Example;
  import Modelica.Units.SI.*;
  parameter Length PipeL = 1 "|Process| Pipe length";
  parameter Length PipeD = 0.0254 "|Process| Pipe diameter";
  parameter Length Lstart = 1 "|Process| Initial water level";
  parameter Length H = 2 "|Process| Storage height";
  parameter Area A = 1.5 "|Process| Cross section storage area";
  parameter Real Tact = 2 "|Process| Actuator dynamics";

  parameter Real Ts_l = 0
    "|Controller level| Sampling time for the valve controller";
  parameter Real Kp_l = -200 "|Controller level| Proportional gain";
  parameter Real Ti_l = 100 "|Controller level| Integral time";
  parameter Boolean AntiWindup_l = true
    "|Controller level| Flag that enables the antiwindup feature";
  parameter Real CSmin_l = -2 "|Controller level| minimum value of the CS";
  parameter Real CSmax_l= 2 "|Controller level| maximum value of the CS";
  parameter Real CS_start_l = 0 "|Controller level| output initial value";

  parameter Real Ts_v = 0
    "|Controller valve| Sampling time for the valve controller";
  parameter Real Kp_v = 50 "|Controller valve| Proportional gain";
  parameter Real Ti_v = 2 "|Controller valve| Integral time";
  parameter Boolean AntiWindup_v = true
    "|Controller| Flag that enables the antiwindup feature";
  parameter Real CSmin_v = 0 "|Controller valve| minimum value of the CS";
  parameter Real CSmax_v = 1 "|Controller valve| maximum value of the CS";
  parameter Real CS_start_v = 0 "|Controller valve| output initial value";

  parameter Boolean FixedPoint = false
    "|Conversion| Use FP operations for level measurement operations";
  parameter Integer Nbit = 24 "|Conversion| number of bit for FP operations";
  parameter Real scaleF_div = 500 "|Conversion| division scale factor";
  parameter Real scaleF_sub = 20 "|Conversion| subtraction scale factor";
  Controllers.PID          PI_Level(
    Ts=Ts_l,
    CS_start=CS_start_l,
    Kp=Kp_l,
    Ti=Ti_l,
    AntiWindup=AntiWindup_l,
    CSmin=CSmin_l,
    CSmax=CSmax_l) "PI level controller"
    ;
  Modelica.Blocks.Sources.Step disturb(
    startTime=3600,
    height=0.4,
    offset=0.4) "inlet water disturb"
    ;
  Modelica.Blocks.Sources.Step levelSetPoint(
    offset=1,
    height=-0.5,
    startTime=1200) "Set Point level"
    ;
  Modelica.Fluid.Vessels.OpenTank tank(nPorts=3, redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater,
    level_start=Lstart,
    use_HeatTransfer=false,
    height=H,
    crossArea=A,
    m_flow_small=0.001,
    portsData={Modelica.Fluid.Vessels.BaseClasses.VesselPortsData(diameter=
        PipeD, height=H),Modelica.Fluid.Vessels.BaseClasses.VesselPortsData(
        diameter=PipeD, height=0),
        Modelica.Fluid.Vessels.BaseClasses.VesselPortsData(diameter=PipeD)},
    use_portsData=false) "water tank"
    ;
  Modelica.Fluid.Valves.ValveLinear valveLinear(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater,
    m_flow_nominal=2,
    dp_nominal=1000) "outlet valve"
    ;
  Modelica.Fluid.Pipes.StaticPipe pipe(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater,
    nParallel=1,
    length=PipeL,
    isCircular=true,
    height_ab=0,
    diameter=PipeD,
    redeclare model FlowModel =
        Modelica.Fluid.Pipes.BaseClasses.FlowModels.NominalLaminarFlow (
          dp_nominal=10000, m_flow_nominal=2)) "outlet pipe"
    ;
  Modelica.Fluid.Sources.FixedBoundary boundary(nPorts=1, redeclare package
      Medium = Modelica.Media.Water.ConstantPropertyLiquidWater,
    use_p=true) "boundary pressure condition"             ;
  Modelica.Fluid.Sources.MassFlowSource_T Inlet(
    nPorts=1,
    use_m_flow_in=true,
    redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater) "disturb water inlet"
    ;
  inner Modelica.Fluid.System system
    ;
  Modelica.Blocks.Continuous.FirstOrder actuator(
    k=1,
    initType=Modelica.Blocks.Types.Init.NoInit,
    T=Tact) "actuator dynamics"
    ;
  Modelica.Fluid.Sensors.Pressure pSensor(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater) "pressure sensor"
    ;
  MathOperations.RealType.Div div(
    Nbit=Nbit,
    FixedPoint=FixedPoint,
    scaleFactor=scaleF_div,
    Ts=Ts_l) "water level"
                     ;
  Modelica.Blocks.Sources.RealExpression rho_times_g(y=system.g*995.586)
    "density times the gravity acceleration"
    ;
  MathOperations.RealType.Sub sub(
    Nbit=Nbit,
    FixedPoint=FixedPoint,
    scaleFactor=scaleF_sub,
    Ts=Ts_l) "hydrostatic pressure"
    ;
  Modelica.Blocks.Sources.RealExpression p_amb(y=system.p_ambient)
    "ambient pressure"
    ;
  Controllers.PID          PI_Valve(
    Ts=Ts_v,
    AntiWindup=AntiWindup_v,
    CSmin=CSmin_v,
    CSmax=CSmax_v,
    CS_start=CS_start_v,
    Kp=Kp_v,
    Ti=Ti_v)
    ;
  Modelica.Fluid.Sensors.MassFlowRate   flowRateSensor(redeclare package Medium =
        Modelica.Media.Water.ConstantPropertyLiquidWater)
    ;
equation
  connect(levelSetPoint.y, PI_Level.SP)
                               ;
  connect(valveLinear.port_b,boundary. ports[1]) ;
  connect(Inlet.ports[1], tank.ports[1])     ;
  connect(pipe.port_a,tank. ports[2]) ;
  connect(actuator.y, valveLinear.opening)        ;
  connect(disturb.y, Inlet.m_flow_in)     ;
  connect(pSensor.port, tank.ports[3]) ;
  connect(rho_times_g.y, div.u2) ;
  connect(pSensor.p, sub.u1) ;
  connect(p_amb.y, sub.u2) ;
  connect(sub.y, div.u1) ;
  connect(div.y, PI_Level.PV) ;

  connect(PI_Level.CS, PI_Valve.SP) ;
  connect(PI_Valve.CS, actuator.u) ;
  connect(flowRateSensor.port_a, pipe.port_b) ;
  connect(flowRateSensor.port_b, valveLinear.port_a) ;
  connect(flowRateSensor.m_flow, PI_Valve.PV) 
  ;
end CascadeLevelControl;

