  Modelica.Blocks.Interfaces.RealOutput FS_y "Fast Slow output"
                                                    ;
  LinearSystems.Continuous.LeadLag leadLag2(
    T1=Tau_FS,
    T2=T1_FS,
    mu=mu_FS)
