within IndustrialControlSystems.Controllers;
model D "Real derivative controller"
  extends Interfaces.Controller;
  parameter Real Td = 1 "|Parameters| Derivative time" ;
  parameter Real N =  10 "|Parameters| Limitation of the derivative action"  ;
  Real Fin "Filtered input";
  Real satin "input of the saturation block";
initial equation

  if Ts > 0 then
    // Discrete time initialisation
    pre(Fin) = if AntiWindup then max(CSmin,min(CSmax,CS_start)) else CS_start - bias;
  else
    // Continuous time initialisation
    Fin = if AntiWindup then max(CSmin,min(CSmax,CS_start)) else CS_start - bias;
  end if;

equation

  if Ts > 0 then
    // Discrete time controller
    when sample(0,Ts) then
      CS    = if AntiWindup then max(CSmin,min(CSmax,satin)) else satin;
      satin = if ts then tr else N*(SP - PV) + pre(bias) - N*Fin;
      Fin = IndustrialControlSystems.LinearSystems.Discrete.Functions.f1Pole(
        alfa,
        SP - PV,
        pre(SP) - pre(PV),
        pre(Fin),
        Ts,
        1,
        Td/N);
    end when;
  else
    // Continuous time controller
    CS    = if AntiWindup then max(CSmin,min(CSmax,satin)) else satin;
    satin = if ts then tr else N*(SP - PV) + bias - N*Fin;
    Fin   = (SP - PV) - Td/N*der(Fin);
  end if

  ;
end D;

within IndustrialControlSystems.Controllers;
model I "Integral controller"
  extends Interfaces.Controller;
  parameter Real T = 1 "|Parameters| Integral time" ;
  Real Iout "output of the Integral block";
  Real satin "input of the saturation block";
initial equation

  if Ts > 0 then
    // Discrete time initialisation
    pre(Iout) = if AntiWindup then max(CSmin,min(CSmax,CS_start)) else CS_start - bias;
  else
    // Continuous time initialisation
    Iout = if AntiWindup then max(CSmin,min(CSmax,CS_start)) else CS_start - bias;
  end if;

equation

  if Ts > 0 then
    // Discrete time controller
    when sample(0,Ts) then
      CS    = if AntiWindup then max(CSmin,min(CSmax,(if ts then tr else satin))) else satin;
      satin = Iout + pre(bias);
      Iout = if ts then tr else
        IndustrialControlSystems.LinearSystems.Discrete.Functions.fIntegrator(
        alfa,
        SP - PV,
        pre(SP) - pre(PV),
        pre(CS) - pre(bias),
        Ts,
        1/T);
    end when;
  else
    // Continuous time controller
    CS    = if AntiWindup then max(CSmin,min(CSmax,(if ts then tr else satin))) else satin;
    satin = Iout + bias;
    if not ts then
      der(Iout)   = 1/T*(SP - PV) + 1/eps*(CS - (satin - bias));
    else
      eps*der(Iout) = -Iout + tr;
    end if;

  end if

  ;
end I;

within IndustrialControlSystems.Controllers;
model P "Proportional controller"
  extends Interfaces.Controller;
  parameter Real Kp = 5 "|Parameters| Proportional gain" ;
  Real Pout "output of the proportional block";
  Real satin "input of the saturation block";
equation

  if Ts > 0 then
    // Discrete time controller
    when sample(0,Ts) then
      CS    = if AntiWindup then max(CSmin,min(CSmax,satin)) else satin;
      satin = if ts then tr else Pout;
      Pout  = Kp*(SP-PV) + pre(bias);
    end when;
  else
    // Continuous time controller
    CS    = if AntiWindup then max(CSmin,min(CSmax,satin)) else satin;
    satin = if ts then tr else Pout;
    Pout  = Kp*(SP-PV) + bias;
  end if

  ;
end P;

within IndustrialControlSystems.Controllers;
model PI "Proportional + Integral controller"
  extends Interfaces.Controller;
  parameter Real Kp = 5 "|Parameters| Proportional gain" ;
  parameter Real Ti = 1 "|Parameters| Integral time" ;
  Real FBout "output (and state) of the feedback block 1/(1+sTi)";
  Real cs "Pre-biased Control Signal";
  Real satin "input of the saturation block";
initial equation

  if Ts > 0 then
    // Discrete time initialisation
    pre(FBout) = if AntiWindup then max(CSmin,min(CSmax,CS_start)) else CS_start - bias - Kp*(SP - PV);
  else
    // Continuous time initialisation
    FBout = if AntiWindup then max(CSmin,min(CSmax,CS_start)) else CS_start - bias - Kp*(SP - PV);
  end if;

equation

  if Ts > 0 then
    // Discrete time controller
    when sample(0,Ts) then
      satin =  pre(FBout) + Kp*(SP-PV);
      cs    =  if ts then tr else (if AntiWindup then max(CSmin,min(CSmax,satin)) else satin);
      FBout = IndustrialControlSystems.LinearSystems.Discrete.Functions.f1Pole(
        alfa,
        cs,
        pre(cs),
        pre(FBout),
        Ts,
        1,
        if not ts then Ti else eps);
      CS    =  if AntiWindup then max(CSmin,min(CSmax,cs + (if ts then 0 else pre(bias)))) else cs + (if ts then 0 else pre(bias));
    end when;
  else
    // Continuous time controller
    satin = FBout + Kp*(SP-PV);
    cs    = if ts then tr else (if AntiWindup then max(CSmin,min(CSmax,satin)) else satin);
    FBout = cs + (if not ts then -Ti*der(FBout) else -eps*der(FBout));
    CS    = if AntiWindup then max(CSmin,min(CSmax,cs + (if ts then 0 else bias))) else cs + (if ts then 0 else bias);
  end if

  ;
end PI;

within IndustrialControlSystems.Controllers;
model PID
  "Proportional + Integral + Derivative two degree of freedom controller"
  extends Interfaces.Controller;
  parameter Real Kp = 5 "|Parameters| Proportional gain" ;
  parameter Real Ti = 1 "|Parameters| Integral time" ;
  parameter Real Tt = max(1e3*eps,sqrt(Ti*Td))
    "|Parameters| Reset time for the integrator (it should be larger than Td and smaller than Ti)"      ;
  parameter Real Td = 1 "|Parameters| Derivative time" ;
  parameter Real N =  10 "|Parameters| Derivative filter ratio"  ;
  parameter Real b = 1
    "|Parameters| Set point weighting for the proportional action" ;
  parameter Real c = 1
    "|Parameters| Set point weighting for the derivative action" ;
  Real Paction "proportional action";
  Real Iaction "integral action";
  Real Daction "derivative action";
  Real Fder "filtered weigthed error";
  Real satin "saturation input";
  Real satDiff "difference between saturation input and output signals";
  Real cs "Control Signal before the biasing";
initial equation

  if Ts > 0 then
    // Discrete time initialisation
    pre(Iaction) = 0;
    pre(Fder)    = 0;
  else
    // Continuous time initialisation
    Iaction = 0;
    Fder    = 0;
  end if;

equation
  assert(Ti>0, "Integral time must be positive");
  assert(Tt>0, "Reset time must be positive");
  assert(Td>=0,"derivative time must be >= 0");

  if Ts > 0 then
    // Discrete time controller
    when sample(0,Ts) then
      // proportional action
      Paction = Kp*(b*SP - PV);
      // integral action
      //Iaction = ControlLibrary.LinearSystems.Discrete.Functions.fIntegrator(alfa,Kp/Ti*(SP-PV)+ 1/Tt*satDiff,Kp/Ti*(pre(SP)-pre(PV))+1/Tt*pre(satDiff),pre(Iaction),Ts,1);
      if not ts then
        Iaction =
          IndustrialControlSystems.LinearSystems.Discrete.Functions.fIntegrator(
          alfa,
          Kp/Ti*(SP - PV) + 1/Tt*satDiff,
          Kp/Ti*(pre(SP) - pre(PV)) + 1/Tt*pre(satDiff),
          pre(Iaction),
          Ts,
          1);
      else
        Iaction =
          IndustrialControlSystems.LinearSystems.Discrete.Functions.f1Pole(
          alfa,
          cs,
          pre(cs),
          pre(Iaction),
          Ts,
          1,
          eps);
      end if;
      // derivative action
      Daction = Kp*N*(c*SP - PV) - Fder;
      Fder = if Td > 0 then
        IndustrialControlSystems.LinearSystems.Discrete.Functions.f1Pole(
        alfa,
        c*SP - PV,
        c*pre(SP) - pre(PV),
        pre(Fder),
        Ts,
        Kp*N,
        Td/N) else 0;

      // sum of the three actions
      satin = Iaction + Paction + (if Td>0 then Daction else 0);

      // Anti-windup
      cs = if AntiWindup then max(CSmin,min(CSmax,(if ts then tr else satin))) else (if ts then tr else satin);

      // Signal for preventing antiwindup (integrator reset signal)
      satDiff = cs - satin;

      // biasing the output
      CS = if AntiWindup then max(CSmin,min(CSmax,cs + pre(bias))) else cs + pre(bias);

    end when;
  else
    // Continuous time controller

    // proportional action
    Paction = Kp*(b*SP - PV);

    // integral action
    if not ts then
      der(Iaction) = Kp/Ti*(SP - PV) + 1/Tt*satDiff;
    else
      Iaction + eps*der(Iaction) = cs;
    end if;

    // derivative action
    Daction = Kp*N*(c*SP - PV) - Fder;
    Fder    = if Td >0 then (-Td/N*der(Fder) + Kp*N*(c*SP - PV)) else 0;

    // sum of the three actions
    satin = Iaction + Paction + (if Td>0 then Daction else 0);

    // Anti-windup
    cs = if AntiWindup then max(CSmin,min(CSmax,(if ts then tr else satin))) else (if ts then tr else satin);

    // Signal for preventing antiwindup (integrator reset signal)
    satDiff = cs - satin;

    // biasing the output
    CS = if AntiWindup then max(CSmin,min(CSmax,cs + bias)) else cs + bias;

  end if
  ;
end PID;

within IndustrialControlSystems.Controllers.AutoTuning;
model ATPIrelayNCdigital
  "PI controller with Auto Tuning algorithm - discrete time version -"
  extends IndustrialControlSystems.Controllers.Interfaces.Controller(final
      useAT=true);
  import Modelica.Constants.*;
  parameter Real Kp = 5 "|Parameters| Proportional gain (initial value)" ;
  parameter Real Ti = 1 "|Parameters| Integral time (initial value)" ;
  parameter Real slope = 1 "|Auto Tuning Algorithm| Slope of the signal";
  parameter Real permOxPeriodPerc = 5
    "|Auto Tuning Algorithm| allowed % difference between period measurements";
  parameter Real pm = 45 "|Auto Tuning Algorithm| Phase Margin required";
  parameter Integer nOxMin = 3
    "|Auto Tuning Algorithm| minimum number of oscillations";
  discrete Real K;
  discrete Real TI;
  discrete Integer iMode " 0: PI, 1: AT";
protected
  discrete Boolean UP;
  discrete Real lastToggleUp;
  discrete Real period;
  discrete Real wox;
  discrete Real Pox;
  discrete Real rPVmax;
  discrete Real rPVmin;
  discrete Real rCSmax;
  discrete Real rCSmin;
  discrete Real e;
  discrete Real CSp;
  discrete Real CSi;
  discrete Integer nOx;
algorithm
  // the sampling time must be greater than zero
  assert(Ts>0,"This is a discrete time controller, Ts MUST be >0");

  // Initial set of parameters (before auto tuning)
  when initial() then
       iMode := 0;
       K     := Kp;
       TI    := Ti;
  end when;

  // Events that starts the Auto Tuning phase
  when at_req == true then
       iMode := 1;
  end when;

  // State machine that represent the behaviour of the controller
  // when iMode == 0 it acts as a standard PI controller,
  // when iMode == 1 the tuning phase is activated
  when sample(0,Ts) then

    // error signal
    e  := SP-PV;

    // Normal PI mode
    if iMode==0 then          // PI
        CSp := K*e;
        CSi := pre(CSi) + K*Ts/TI*e;
        CS  := if ts then tr else CSp + CSi + bias;
        if CS>CSmax then
           CS:=CSmax;
        end if;
        if CS<CSmin then
           CS:=CSmin;
        end if;
        CSi := if ts then tr else CS - CSp - bias;
    end if;
    // AutoTuning PHASE
    if iMode==1 then          // AT
        // 1st step, initialise test
        if pre(iMode)==0 then
           wox          := 0;
           Pox          := 0;
           rPVmax       := PV;
           rPVmin       := PV;
           rCSmax       := CS;
           rCSmin       := CS;
           lastToggleUp := time;
           nOx          := 0;
        end if;

        // Manage relay
        if UP==false and PV<=SP then
           UP    := true;
        end if;
        if UP==true and PV>SP then
           UP    := false;
        end if;
        if UP==true then
           CS := CS + slope*Ts;
        else
           CS := CS - slope*Ts;
        end if;

        // record relay id max and min for PV and CS
        if PV>rPVmax then
           rPVmax := PV;
        end if;
        if PV<rPVmin then
           rPVmin := PV;
        end if;
        if CS>rCSmax then
           rCSmax := CS;
        end if;
        if CS<rCSmin then
           rCSmin := CS;
        end if;

        // toggled up, compute ox data and tune if perm
        if UP==true and pre(UP)==false then
           // count and measure the period and number of oscillations
           period       := time-lastToggleUp;
           lastToggleUp := time;

           // if the number of induced oscillations is higher than the minimum
           // required number, then compute the controller parameters
           if period>0 and nOx>=nOxMin
              and abs(period-pre(period))/period < permOxPeriodPerc/100 then
              iMode  := 0;
              wox    := 2*Modelica.Constants.pi/period;
              Pox    := Modelica.Constants.pi^2*(rPVmax-rPVmin)/8/(rCSmax-rCSmin);
              TI     := tan(pm/180*Modelica.Constants.pi)/wox;
              K      := tan(pm/180*Modelica.Constants.pi)/(Pox*sqrt(1+(tan(pm/180*Modelica.Constants.pi))^2));
              CSi    := CS-K*Ts/TI*e;
           end if;
           rPVmax       := PV;
           rPVmin       := PV;
           rCSmax       := CS;
           rCSmin       := CS;
           nOx          := nOx+1;
        end if;
   end if;
end when

  ;
end ATPIrelayNCdigital;

within IndustrialControlSystems.Controllers.AutoTuning;
model ATPIrelayNCmixedMode
  "PI controller with Auto Tuning algorithm - mixed continuous/discrete time version -"
  extends IndustrialControlSystems.Controllers.Interfaces.Controller(final
      useAT=true);
  import Modelica.Constants.*;
  parameter Real Kp = 5 "|Parameters| Proportional gain (initial value)" ;
  parameter Real Ti = 1 "|Parameters| Integral time (initial value)" ;
  parameter Real slope = 1 "|Auto Tuning Algorithm| Slope of the signal";
  parameter Real permOxPeriodPerc = 5
    "|Auto Tuning Algorithm| allowed % difference between period measurements";
  parameter Real pm = 45 "|Auto Tuning Algorithm| Phase Margin required";
  parameter Integer nOxMin = 3
    "|Auto Tuning Algorithm| minimum number of oscillations";
  Integer iMode;
  Real K;
  Real TI;
protected
  Real satIn;
  Real linFBout(start=0,stateSelect=StateSelect.always);
  Real CSpi;
  discrete Real CSat;
  discrete Boolean AT;
  discrete Boolean UP;
  discrete Real rPVmax;
  discrete Real rPVmin;
  discrete Real rCSmax;
  discrete Real rCSmin;
  discrete Real lastToggleUp;
  discrete Real period;
  discrete Real wox;
  discrete Real Pox;
  discrete Integer nOx;
equation
  // the sampling time must be greater than zero
  assert(Ts>0,"Ts MUST be >0 for the AutoTuning phase");

  // The PI controller is implemented with its continuous time version
  satIn    = linFBout + K*(SP-PV);
  linFBout = CSpi  - TI*der(linFBout);
  CSpi     = if ts then tr else noEvent( if AntiWindup then max(CSmin,min(CSmax,satIn)) else satIn);

  // Manage the Control Signal selection:
  // if the flag
  //  iMode == 0 PI controller
  //  iMode == 1 Auto Tuning initialisation
  //  iMode == 2 Auto Tuning is running
  if iMode==0 or iMode==1 then
     CS = CSpi + (if ts then 0 else bias);
  else
     CS = CSat;
  end if;

algorithm
  // the algorithmic section takes into accout the Auto Tuning procedure

  // parameters initialisation
  when initial() then
       K  := Kp;
       TI := Ti;
       AT := false;
  end when;

  // Turn on AT when requested
  when at_req then
       if not AT then
          AT    := true;           // set AT flag on
          iMode := 1;              // set next mode to AT init
       end if;
  end when;

  // Auto Tuning init mode
  when AT and iMode==1 and sample(0,Ts) then
       iMode        := 2;          // set next mode to AT run
       CSat         := pre(CSpi);
       UP           := false;
       period       := 0;
       wox          := 0;
       Pox          := 0;
       rPVmax       := pre(PV);
       rPVmin       := pre(PV);
       rCSmax       := CSat;
       rCSmin       := CSat;
       lastToggleUp := time;
       nOx          := 0;
  end when;

  // Auto Tuning shutdown
  when (iMode==1 or iMode==2) and not AT and sample(0,Ts) then
       iMode := 0;
       reinit(linFBout,CSat);
  end when;

  // Auto Tuning run mode
  when AT and iMode==2 and sample(0,Ts) then
        // Manage relay
        if UP==false and PV<=SP then
           UP    := true;
        end if;
        if UP==true and PV>SP then
           UP    := false;
        end if;
        if UP==true then
           CSat := CSat + slope*Ts;
        else
           CSat := CSat - slope*Ts;
        end if;

        // record relay id max and min for PV and CS
        if PV>rPVmax then
           rPVmax := PV;
        end if;
        if PV<rPVmin then
           rPVmin := PV;
        end if;
        if CSat>rCSmax then
           rCSmax := CSat;
        end if;
        if CSat<rCSmin then
           rCSmin := CSat;
        end if;

        // toggled up, compute ox data and tune if perm
        if UP==true and pre(UP)==false then
           // count and measure the period and number of oscillations
           period       := time-lastToggleUp;
           lastToggleUp := time;

           // if the number of induced oscillations is higher than the minimum
           // required number, then compute the controller parameters
           if period>0 and nOx>=nOxMin
              and abs(period-pre(period))/period < permOxPeriodPerc/100 then
              AT     := false;
              wox    := 2*Modelica.Constants.pi/period;
              Pox    := Modelica.Constants.pi^2*(rPVmax-rPVmin)/8/(rCSmax-rCSmin);
              TI     := tan(pm/180*Modelica.Constants.pi)/wox;
              K      := wox*TI/Pox/sqrt(1+(wox*TI)^2);
           end if;
           rPVmax       := PV;
           rPVmin       := PV;
           rCSmax       := CSat;
           rCSmin       := CSat;
           nOx          := nOx+1;
        end if;
  end when
  ;
end ATPIrelayNCmixedMode;

