  connect(ControllerPm60.CS, sum1.u1) ;
  connect(Disturb.y, sum1.u2) ;
  connect(ProcessPm60.y, ControllerPm60.PV) ;

  connect(ATpulse.y, ControllerPm60.ATreq) ;
  connect(SP.y, ControllerPm60.SP) ;
  connect(ATpulse.y, ControllerPm45.ATreq) ;
