within IndustrialControlSystems.Controllers.Blocks;
model ComplexPoles "Process with complex poles and tracking mode (and limiter)"
  extends IndustrialControlSystems.Controllers.Interfaces.Block;
  parameter Real mu = 1 "Gain of the system" ;
  parameter Real omega = 1 "natural frequency of the complex poles" ;
  parameter Real xi = 1 "damping factor" ;
  parameter Real y_start = 0 "output initial value" ;
  parameter Real y_der_start = 0 "output initial slope" ;
protected
  Real Y "output before saturation";
  Real dY "derivative of the output";
initial equation
  y  = y_start;
  dY = y_der_start;
equation

  if not ts then
    if AntiWindup then
      y = min(Ymax,max(Ymin,Y));
      mu*u = Y + 2*xi/omega*dY + der(dY)/(omega^2);
      dY = der(Y);
    else
      y = Y;
      mu*u = Y + 2*xi/omega*dY + der(dY)/(omega^2);
      dY = der(Y);
    end if;
  else
    if AntiWindup then
      y = min(Ymax,max(Ymin,tr));
      Y + eps*der(Y) = tr;
      dY = der(Y);
    else
      y = tr;
      Y + eps*der(Y) = tr;
      dY = der(Y);
    end if;
  end if
  ;
end ComplexPoles;

within IndustrialControlSystems.Controllers.Blocks;
model FO "First Order process with tracking mode (and limiter)"
  extends IndustrialControlSystems.Controllers.Interfaces.Block;
  parameter Real mu = 1 "Gain of the system" ;
  parameter Real T = 1 "Pole time constant" ;
  parameter Real y_start = 0 "output initial value" ;
protected
  Real Y "output before saturation";
initial equation
  Y = y_start;
equation
  if not ts then
    if AntiWindup then
      y = min(Ymax,max(Ymin,Y));
      // T*der(Y) = mu*u - y;
      der(Y) = 1/T*(mu*u - Y) + 1/eps*(y-Y);
    else
      y = Y;
      T*der(Y) = mu*u - Y;
    end if;
  else
    if AntiWindup then
      y = min(Ymax,max(Ymin,Y));
      Y + eps*der(Y) = tr;
    else
      y = Y;
      Y + eps*der(Y) = tr;
    end if;
  end if
  ;
end FO;

within IndustrialControlSystems.Controllers.Blocks;
model LeadLAG "Lead lag process with tracking mode (and limiter)"
  extends IndustrialControlSystems.Controllers.Interfaces.Block;
  parameter Real mu = 1 "Gain of the system" ;
  parameter Real Tp = 1 "Pole time constant" ;
  parameter Real Tz = 2 "Zero time constant" ;
  parameter Real y_start = 0 "output initial value" ;
protected
  Real Y "output before saturation";
  Real uF "input filtered";
  parameter Real K1 = mu*(Tp - Tz)/Tp "first gain";
  parameter Real K2 = Tz/(Tp - Tz) "second gain";
initial equation
  y = y_start;
equation
  // assert that Td <> Tp
  assert(abs(Tp - Tz)>1e-4, "Td and Tp must be different!");

  if not ts then
    if AntiWindup then
      y = min(Ymax,max(Ymin,Y));
      Y = K1*K2*u + uF;
      uF + Tp*der(uF) = K1*u;
    else
      y = Y;
      Y = K1*K2*u + uF;
      uF + Tp*der(uF) = K1*u;
    end if;
  else
    if AntiWindup then
      y = min(Ymax,max(Ymin,Y));
      Y = tr;
      uF + eps*der(uF) = y - K1*K2*u;
    else
      y = Y;
      Y = tr;
      uF + eps*der(uF) = y  - K1*K2*u;
    end if;
  end if
  ;
end LeadLAG;

within IndustrialControlSystems.Controllers.Blocks;
model P "Integrator with tracking mode (and limiter)"
  extends IndustrialControlSystems.Controllers.Interfaces.Block;
  parameter Real Kp = 5 "Proportional gain" ;
equation
  if not ts then
      y = if AntiWindup then max(Ymin,min(Ymax,Kp*u)) else Kp*u;
    else
      y = if AntiWindup then max(Ymin,min(Ymax,tr)) else tr;
  end if
  ;
end P;

