within IndustrialControlSystems.Controllers.Digital;
model PID_2dof "Digital 2-dof PID controller"
  extends Interfaces.Controller;
  parameter Real Kp = 1 "|Parameters| Gain";
  parameter Real Ti = 10 "|Parameters| Integral time";
  parameter Real Td = 0 "|Parameters| Derivative time";
  parameter Real N = 5 "|Parameters| Derivative filter ratio";
  parameter Real b = 1 "|Parameters| SP weight in P action";
  parameter Real c = 0 "|Parameters| SP weight in D action";
protected
  discrete Real sp;
  discrete Real dsp;
  discrete Real pv;
  discrete Real dpv;
  discrete Real dp;
  discrete Real di;
  discrete Real d;
  discrete Real dd;
  discrete Real cs;
  discrete Real dcs;
algorithm
  when sample(0,Ts) then

    // read the inputs
    sp  := SP;
    pv  := PV;
    dsp := sp - pre(sp);
    dpv := pv - pre(pv);

    if (not ts) and (not man) then
      // automatic mode
      dp  := Kp*(b*dsp-dpv);
      di  := Kp*Ts/Ti*(sp-pv);
      d   := (Td*pre(d)+Kp*N*Td*(c*dsp-dpv))/(if Td>0 then Td+N*Ts else 1);
      dd  := d - pre(d);
      dcs := dp + di + dd + bias - pre(bias);
      cs  := pre(cs) + dcs;
    elseif man then
      // manual mode
      // (Manual has an higher priority with respect to tracking)
      cs  := pre(cs) + csInc;
    else
      // tracking mode
      cs := tr;
    end if;

    // Forbid increment
    if F_inc and (not man) and cs > pre(cs) then
      cs := pre(cs);
    end if;
    // Forbid decrement
    if F_dec and (not man) and cs < pre(cs) then
      cs := pre(cs);
    end if;

    // saturation
    if cs > CSmax and AntiWindup then
      cs     := CSmax;
      satHI  := true;
      satLOW := false;
    else
      satHI := false;
    end if;
    if cs < CSmin and AntiWindup then
      cs     := CSmin;
      satLOW := true;
      satHI  := false;
    else
      satLOW := false;
    end if;

    // Output assignment
    CS := cs;

  end when
       ;
end PID_2dof;

within IndustrialControlSystems.Controllers.Digital;
model PID_2dof_TDO
  "Digital 2-dof PID controller with Time Division Output (TDO)"
  extends Interfaces.Controller;
  parameter Real Kp = 1 "|Parameters| Gain";
  parameter Real Ti = 10 "|Parameters| Integral time";
  parameter Real Td = 0 "|Parameters| Derivative time";
  parameter Real N = 5 "|Parameters| Derivative filter ratio";
  parameter Real b = 1 "|Parameters| SP weight in P action";
  parameter Real c = 0 "|Parameters| SP weight in D action";
  parameter Real TDsteps = 100 "|Parameters| Time Division Output resolution";
  Real counter;
  Real cs;
protected
  Real sp;
  Real dsp;
  Real pv;
  Real dpv;
  Real dp;
  Real di;
  Real d;
  Real dd;

  Real dcs;

  Real spo;
  Real pvo;
  Real dold;
  Real cso;
  Real StepsUp;

algorithm
  when sample(0,Ts/TDsteps) then

    counter := counter + Ts/TDsteps;

    if counter>=Ts then
      // read the inputs
      counter :=0;
      sp  := SP;
      pv  := PV;
      dsp := sp - spo;
      dpv := pv - pvo;

      if (not ts) and (not man) then
        // automatic mode
        dp  := Kp*(b*dsp-dpv);
        di  := Kp*Ts/Ti*(sp-pv);
        d   := (Td*pre(d)+Kp*N*Td*(c*dsp-dpv))/(if Td>0 then Td+N*Ts else 1);
        dd  := d - dold;
        dcs := dp + di + dd + bias - pre(bias);
        cs  := pre(cs) + dcs;
      elseif man then
        // manual mode
        // (Manual has an higher priority with respect to tracking)
        cs  := pre(cs) + csInc;
      else
        // tracking mode
        cs := tr;
      end if;

      // Forbid increment
      if F_inc and (not man) and cs > pre(cs) then
        cs := pre(cs);
      end if;
      // Forbid decrement
      if F_dec and (not man) and cs < pre(cs) then
        cs := pre(cs);
      end if;

      // saturation
      if cs > CSmax and AntiWindup then
        cs     := CSmax;
        satHI  := true;
        satLOW := false;
      else
        satHI := false;
      end if;
      if cs < CSmin and AntiWindup then
        cs     := CSmin;
        satLOW := true;
        satHI  := false;
      else
        satLOW := false;
      end if;

      spo     := sp;
      pvo     := pv;
      cso     := cs;
      dold    := d;
      StepsUp :=((cs-CSmin)/(CSmax-CSmin)*Ts);

    end if;

    CS := if (counter<StepsUp) then CSmax else CSmin;

    end when

       ;
end PID_2dof_TDO;

within IndustrialControlSystems.Controllers.Digital;
model PID_2dof_TDO_FullyEventBased
  "Digital 2-dof PID controller with event based Time Division Output (TDO)"
  extends Interfaces.Controller;
  parameter Real Kp = 1 "|Parameters| Gain";
  parameter Real Ti = 10 "|Parameters| Integral time";
  parameter Real Td = 0 "|Parameters| Derivative time";
  parameter Real N = 5 "|Parameters| Derivative filter ratio";
  parameter Real b = 1 "|Parameters| SP weight in P action";
  parameter Real c = 0 "|Parameters| SP weight in D action";
  parameter Real TDsteps = 100 "|Parameters| Time Division Output resolution";
  Real counter;
  Real cs;
protected
  Real sp;
  Real dsp;
  Real pv;
  Real dpv;
  Real dp;
  Real di;
  Real d;
  Real dd;
  Real dcs;

  Real spo;
  Real pvo;
  Real dold;
  Real cso;
  Real nextEventTime;

algorithm
  when sample(0,Ts) then

      // read the inputs
      counter :=0;
      sp  := SP;
      pv  := PV;
      dsp := sp - spo;
      dpv := pv - pvo;

      if (not ts) and (not man) then
        // automatic mode
        dp  := Kp*(b*dsp-dpv);
        di  := Kp*Ts/Ti*(sp-pv);
        d   := (Td*pre(d)+Kp*N*Td*(c*dsp-dpv))/(if Td>0 then Td+N*Ts else 1);
        dd  := d - dold;
        dcs := dp + di + dd + bias - pre(bias);
        cs  := pre(cs) + dcs;
      elseif man then
        // manual mode
        // (Manual has an higher priority with respect to tracking)
        cs  := pre(cs) + csInc;
      else
        // tracking mode
        cs := tr;
      end if;

      // Forbid increment
      if F_inc and (not man) and cs > pre(cs) then
        cs := pre(cs);
      end if;
      // Forbid decrement
      if F_dec and (not man) and cs < pre(cs) then
        cs := pre(cs);
      end if;

      // saturation
      if cs > CSmax and AntiWindup then
      cs     := CSmax;
      satHI  := true;
      satLOW := false;
    else
      satHI := false;
    end if;
    if cs < CSmin and AntiWindup then
      cs     := CSmin;
      satLOW := true;
      satHI  := false;
    else
      satLOW := false;
    end if;

      // store the old values
      spo     := sp;
      pvo     := pv;
      cso     := cs;
      dold    := d;

      // define the output and compute the
      // time division output
      if cs<=CSmin then
        CS := CSmin;
        nextEventTime := time+Ts;
      elseif cs>=CSmax then
        CS := CSmax;
        nextEventTime := time+Ts;
      else
        CS := CSmax;
        nextEventTime := time+(cs-CSmin)/(CSmax-CSmin)*Ts;
      end if;

    end when;

    // when the time is elapsed reset the output
    when time>=nextEventTime then
      if cs>CSmin and cs<CSmax then
        CS:=CSmin;
      end if;
    end when

       ;
end PID_2dof_TDO_FullyEventBased;

