model Relay "Relay"
  extends IndustrialControlSystems.Controllers.Interfaces.BaseBlock;
  parameter Real Ymax = 1 "maximum output value" ;
  parameter Real Ymin = 0 "minimum output value" ;
  parameter Real Th = 0 "input treshold value" ;
equation
  if Ts > 0 then
    // Discrete time relay
    when sample(0,Ts) then
      if pre(u) >= Th then
        y = Ymax;
      else
        y = Ymin;
      end if;
    end when;
  else
    // Continuous time relay
    if u >= Th then
        y = Ymax;
      else
        y = Ymin;
      end if;
  end if
  ;
end Relay;

