end MultiStepsDelay;

within IndustrialControlSystems.LinearSystems.Discrete;
model TransferFunction " Model of a generic rational transfer function
  [a(m)*s^m + a(m-1)*s^(m-1) + ... + a(1)*s + a(0) ]/[b(n)*s^n + b(n-1)*s^(n-1) + ... + b(1)*s + b(0) ] "
  extends Interfaces.DiscreteBaseBlock;
  parameter Real num[:] = {1,1}
    "|Block parameters| Numerators coefficients (4*s + 2) is {4,2}";
  parameter Real den[:] = {2,1,1}
    "|Block parameters| Denumerators coefficients (4*s + 2) is {4,2}";
  parameter Real y_start = 0 "|Initial conditions| Output initial value";
  parameter Boolean initOutput = false
    "|Initial conditions| Initialise the output";
  parameter Boolean initSteadyState = false
    "|Initial conditions| Initialise at steady state";
  parameter Boolean initSteadyOutput = false
    "|Initial conditions| Initialise at steady output";
protected
  parameter Integer N = size(num,1) "grade of the numerator";
  parameter Integer D = size(den,1) "grade of the denumerator";
  parameter Real b[D] = den[:] "den. coefficients";
  Real a[D] "num. coefficients";
  Real c[D-1] "num. coefficients (proper part)";
  discrete Real Y[D];
  discrete Real U[D-1];
  Real A "terms used if the system is not strictly proper";
  discrete Real w "proper part of the output";
initial equation
  if initOutput then
    y = y_start;
  end if;
  if initSteadyOutput then
    pre(y) = 0;
  end if;
  if initSteadyState then
    pre(w) = 0;
  end if;
equation
  assert(D >= N,"The system is not proper");

  if D==N then
    a[1:D] = num[1:D];
  else
    a[1:D-N] = zeros(D-N);
    a[D-N+1:D] = num[1:N];
  end if;

  A = a[1]/b[1];

  for i in 1:D-1 loop
    c[i] = a[i+1] - A*b[i+1];
  end for;

  when sample(0,Ts) then
    Y[1] = Functions.fDerivator(1,w,pre(w),pre(Y[1]),Ts,1);
    Y[2] = w;
    for i in 3:D loop
      Y[i] = Functions.fIntegrator(alfa,Y[i-1],pre(Y[i-1]),pre(Y[i]),Ts,1);
    end for;

    U[1] = u;
    for i in 2:D-1 loop
      U[i] = Functions.fIntegrator(alfa,U[i-1],pre(U[i-1]),pre(U[i]),Ts,1);
    end for;

    w = - b[1]*Y[1] - sum(b[i]*Y[i] for i in 3:D) + sum(c[i]*U[i] for i in 1:D-1);

    y = A*u + w;

  end when

 ;
end TransferFunction;

within IndustrialControlSystems.LinearSystems.Discrete;
model TwoPolesTwoZeroes
  "Process with an integrator, 1 pole and 2 zeroes: mu(1+sT1)(1+sT2)/(1+sT3)s"
  extends Interfaces.DiscreteBaseBlock;
  parameter Real mu = 1 "|Block parameters| Gain";
  parameter Real T1 = 2 "|Block parameters| first zero's time constant";
  parameter Real T2 = 0.03 "|Block parameters| second zero's time constant";
  parameter Real T3 = 0.5 "|Block parameters| pole's time constant";
  parameter Real y_start = 0 "|Initial conditions| Output initial value";
protected
  Real u_pre;
  Real y_pre;
initial equation
  pre(y) = y_start;
equation
  assert(abs(T2-T3)>1e-8 and abs(T1-T3)>1e-8,"T1 and T2 must be != T3");

  when sample(0,Ts) then
    y = IndustrialControlSystems.LinearSystems.Discrete.Functions.f2p2z(
      alfa,
      T1,
      T2,
      T3,
      u,
      pre(u),
      pre(u_pre),
      pre(y),
      pre(y_pre),
      Ts,
      mu);
    u_pre = pre(u);
    y_pre = pre(y);
  end when

  ;
end TwoPolesTwoZeroes;

within IndustrialControlSystems.LinearSystems.Discrete.Functions;
function f1Pole "Function first order process : k/(1+s*tau)"
  input Real alfa "Parametro di discretizzazione";
  input Real u "Current input";
  input Real u_pre "Previous input";
  input Real y_pre "Previous output";
  input Real Ts "Sampling time [s]";
  input Real k "Gain";
  input Real tau "Pole";
  output Real y "Output";
protected
  Real A;
  Real B;
  Real C;
  Real D;
algorithm
  A := alfa*Ts;
  B := Ts - alfa*Ts;
  C := A + tau;
  D := B - tau;
  y := (A*k*u + B*k*u_pre - D*y_pre)/C
  ;
end f1Pole;

within IndustrialControlSystems.LinearSystems.Discrete.Functions;
function f2p2z
  "Function of a process with oneintegrator, one pole and two zeroes: k(1+sT1)(1+sT2)/(1+sT3)s"
  input Real alpha "Parametro di discretizzazione";
  input Real T1 "Zero";
  input Real T2 "Zero";
  input Real T3 "Polo";
  input Real u "Current input";
  input Real u_pre1 "Previous input";
  input Real u_pre2 "two steps ago input";
  input Real y_pre1 "Previous output";
  input Real y_pre2 "two steps ago output";
  input Real Ts "Sampling time [s]";
  input Real mu "Gain";
  output Real y "Output";
algorithm
  y := 1/(alpha*Ts + T3)*(
          + T3*y_pre1
          - (-T3-alpha*Ts+Ts)*y_pre1
          + alpha*Ts*y_pre1
          - (T3+alpha*Ts-Ts)*y_pre2
          + mu*T1*T2*u
          + alpha^2*mu*Ts^2*u
          + alpha*mu*Ts*T2*u
          + alpha*mu*Ts*T1*u
          + mu*(-T1-alpha*Ts+Ts)*T2*u_pre1
          + mu*T1*(-T2-alpha*Ts+Ts)*u_pre1
          + alpha*mu*Ts*(-T2-alpha*Ts+Ts)*u_pre1
          + alpha*mu*Ts*(-T1-alpha*Ts+Ts)*u_pre1
          + mu*(-T1-alpha*Ts+Ts)*(-T2-alpha*Ts+Ts)*u_pre2)

  ;
end f2p2z;

within IndustrialControlSystems.LinearSystems.Discrete.Functions;
function fCmplx "Function process with two complex poles"
  input Real alfa "Parametro di discretizzazione";
  input Real u "Current input";
  input Real u_pre1 "Previous input";
  input Real u_pre2 "ingresso a 2 passi precedente";
  input Real y_pre1 "Previous output";
  input Real y_pre2 "uscita a 2 passi precedente";
  input Real Ts "Sampling time [s]";
  input Real mu "Gain";
  input Real xi "Smorzamento";
  input Real omegan "Natural pulse";
  output Real y "Output";
protected
  Real A;
  Real B;
  Real C;
  Real D;
  Real E;
  Real F;
  Real G;
  Real H;
  Real I;
  Real L;
  Real M;
  Real N;
  Real O;
  Real P;
algorithm
  A := alfa*Ts;
  B := Ts - alfa*Ts;
  C := -2;
  D := A^2;
  E := 2*A*B;
  F := B^2;
  G := omegan;
  H := 2*xi*omegan;
  I := 1 + A*H + G*G*D;
  L := C - A*H + B*H + E*G*G;
  M := 1 - B*H + F*G*G;
  N := D*G^2;
  O := E*G^2;
  P := F*G^2;
  y := (mu*N*u + mu*O*u_pre1 + mu*P*u_pre2 - L*y_pre1 - M*y_pre2)/I
  ;
end fCmplx;

within IndustrialControlSystems.LinearSystems.Discrete.Functions;
function fDerivator "Function derivator"
  input Real alpha "discretisation parameter";
  input Real u "Current input";
  input Real u_pre "Previous input";
  input Real y_pre "Previous output";
  input Real Ts "Sampling time [s]";
  input Real k "Gain";
  output Real y "Output";
algorithm
  y := (u - u_pre + (alpha-1)*Ts*y_pre)/(alpha*Ts)
  ;
end fDerivator;

within IndustrialControlSystems.LinearSystems.Discrete.Functions;
function fIntegrator "Function integrator"
  input Real alfa "Parametro di discretizzazione";
  input Real u "Current input";
  input Real u_pre "Previous input";
  input Real y_pre "Previous output";
  input Real Ts "Sampling time [s]";
  input Real k "Gain";
  output Real y "Output";
protected
  Real A;
  Real B;
algorithm
  A := alfa*Ts;
  B := Ts - alfa*Ts;
  y := A*k*u + B*k*u_pre + y_pre
  ;
end fIntegrator;

