within IndustrialControlSystems.Logical.LogicalOperations.Functions;
function And "Function AND"
  input Boolean u[:];
  input Integer nInput = 2;
  output Boolean y;
algorithm
  y := u[1] and u[2];

  for i in 3:size(u,1) loop
    y := y and u[i];
  end for

  ;
end And;

within IndustrialControlSystems.Logical.LogicalOperations.Functions;
function Not "Function NOT"
  input Boolean u[:];
  input Integer nOutput = 1;
  output Boolean y[nOutput];
algorithm
  for i in 1:size(u,1) loop
    y[i] := not u[i];
  end for
  ;
end Not;

within IndustrialControlSystems.Logical.LogicalOperations.Functions;
function Or "Function OR"
  input Boolean u[:];
  input Integer nInput = 2;
  output Boolean y;
algorithm
  y := u[1] or u[2];

  for i in 3:size(u,1) loop
    y := y or u[i];
  end for

  ;
end Or;

within IndustrialControlSystems.Logical.LogicalOperations.Functions;
function SR "This function represents the behavious of the set-reset filp-flop"
    input Boolean s "Set signal";
    input Boolean r "Reset signal";
    input Boolean q_old "Previous output ";
    output Boolean q "Output";
algorithm
    q := if (s==true and r==false) then true else
         if (s==true and r==true) then false else
         if (s==false and r==true) then false else
         q_old
  ;
end SR;

within IndustrialControlSystems.Logical.LogicalOperations.Functions;
function Xor "Function XOR"
  input Boolean u[:];
  input Integer nInput = 2;
  output Boolean y;
algorithm

  y := (u[1] and (not u[2])) or ((not u[1]) and u[2]);

  for i in 3:size(u,1) loop
    y := (u[i] and (not y)) or ((not u[i]) and y);
  end for

  ;
end Xor;

