within IndustrialControlSystems.Logical.Timers;
model Timer_On "ON timer model"
  extends IndustrialControlSystems.Logical.Timers.Interfaces.BaseResidualTimer;
  Boolean run "Flag: true while the timer is counting";
  Real startTime "start time of the timer counting";
  discrete Boolean Sd;
initial equation
  startTime = 0;
  pre(Sd) = false;
equation
  Sd = S;
  when sample(0,Ts) then
    startTime =
      IndustrialControlSystems.Logical.Timers.Functions.positiveEdge(
        pre(Sd),
        Sd,
        R,
        pre(startTime),
        time);
    (run,Q) = IndustrialControlSystems.Logical.Timers.Functions.tim(
        S,
        R,
        PV,
        time,
        startTime);
    tr = if Q then PV - (time - startTime) else 0.0;
  end when
  ;
end Timer_On;

within IndustrialControlSystems.Logical.Timers;
model Timer_On_Redge "ON timer model, active on rising edge"
  extends IndustrialControlSystems.Logical.Timers.Interfaces.BaseResidualTimer;
  Boolean run "Flag: true while the timer is counting";
  Real startTime "start time of the timer counting";
  Boolean S_hold
    "This variable is kept on by a rising edge of set signal until a rising edge of reset signal.";
  discrete Boolean Sd;
  discrete Boolean Shd;
initial equation
  startTime = 0;
  run = false;
equation
  when sample(0,Ts) then
    Sd = S;
    Shd = S_hold;
    S_hold = IndustrialControlSystems.Logical.Timers.Functions.hold(
        pre(Sd),
        Sd,
        R,
        pre(Shd));
    startTime =
      IndustrialControlSystems.Logical.Timers.Functions.positiveEdge(
        pre(Sd),
        Sd,
        R,
        pre(startTime),
        time);
    (run,Q) = IndustrialControlSystems.Logical.Timers.Functions.tim(
        S_hold,
        R,
        PV,
        time,
        startTime);
    tr = if (Q) then PV - (time - startTime) else 0.0;
  end when
;
end Timer_On_Redge;

within IndustrialControlSystems.Logical.Timers.Functions;
function fallingEdge
  "logical function that senses a falling edge of set signal"
  input Boolean S_old;
  input Boolean S;
  input Boolean R;
  input Real s_time;
  input Real t;
  input Boolean Run_old;
  output Real st_time;
  output Boolean Run;
algorithm
  Run     := if ((S_old==true and S==false and R==false) or (Run_old==true and R==false)) then true else false;
  st_time := if (S_old==true and S==false and R==false) then t else 0.0;
  st_time := max(s_time,st_time)
    ;
end fallingEdge;

within IndustrialControlSystems.Logical.Timers.Functions;
function hold
  "this function keeps high the set value after a rising edge, until an high value of the reset signal"
  input Boolean S_old;
  input Boolean S;
  input Boolean R;
  input Boolean S_hold;
  output Boolean Y;
algorithm
  if (S_old==false and S==true and R==false) then
    Y := true;
  elseif (S_old==true and S==false and R==false) then
    Y := true;
  elseif (S==true and R==false) then
    Y := true;
  elseif (S_hold==true and R==false) then
    Y := true;
  else
    Y := false;
  end if
    ;
end hold;

within IndustrialControlSystems.Logical.Timers.Functions;
function odt "This logical function represents the Off-Delay timer behaviour."
  input Boolean S;
  input Boolean R;
  input Real durata;
  input Real t;
  input Real inizio;
  output Boolean run;
  output Boolean Q;
algorithm
  if (S==true and R==false and t >= inizio + durata) then
    Q := true;
  else
    Q := false;
  end if;
  run := Q
    ;
end odt;

within IndustrialControlSystems.Logical.Timers.Functions;
function odts
  "This function represents the Off-Delay timer (active on a rising edge) behaviour."
  input Boolean R;
  input Real durata;
  input Real t;
  input Real inizio;
  input Boolean run;
  output Boolean Q;
algorithm
  if (R==false and t >= inizio + durata and run==true) then
    Q := true;
  else
    Q := false;
  end if
    ;
end odts;

within IndustrialControlSystems.Logical.Timers.Functions;
function positiveEdge
  "The positive Edge Detection function detects a change from 0 to 1"
  input Boolean S_old;
  input Boolean S;
  input Boolean R;
  input Real s_time;
  input Real t;
  output Real st_time;
algorithm
  st_time := if (S_old==false and S==true and R==false) then t else 0.0;
  st_time := max(s_time,st_time)
    ;
end positiveEdge;

within IndustrialControlSystems.Logical.Timers.Functions;
function risingEdge "logical function that senses a rising edge of set signal"
  input Boolean S_old;
  input Boolean S;
  input Boolean R;
  input Real s_time;
  input Real t;
  input Boolean Run_old;
  output Real st_time;
  output Boolean Run;
algorithm
  Run     := if ((S_old==false and S==true and R==false) or (Run_old==true and R==false)) then true else false;
  st_time := if (S_old==false and S==true and R==false) then t else 0.0;
  st_time := max(s_time,st_time)
    ;
end risingEdge;

within IndustrialControlSystems.Logical.Timers.Functions;
function tim "This function represent the logical of the timer"
    input Boolean S;
    input Boolean R;
    input Real durata;
    input Real t;
    input Real inizio;
    output Boolean run;
    output Boolean Q;
algorithm
    if (S==true and R==false and t-inizio <= durata) then
      Q := true;
    else
      Q := false;
    end if;
    run := Q
  ;
end tim;

