model Add "Sum of two real numbers"
  extends
    IndustrialControlSystems.MathOperations.RealType.Interfaces.RealSimpleOperation;
equation

  if FixedPoint then

    // Overflow : Numerical error
    assert(U1fp > MIN and U1fp < MAX, "Overflow error, chose a different scale factor or Nbit");
    assert(U2fp > MIN and U2fp < MAX, "Overflow error, chose a different scale factor or Nbit");

    // FixedPoint variables
    // conversion from Real to Integer
    U1fp = integer(Functions.toFixedPoint(u1,scaleFactor,MAX,MIN));
    U2fp = integer(Functions.toFixedPoint(u2,scaleFactor,MAX,MIN));

    // Math operation
    if Ts > 0 then
      when sample(0,Ts) then
        Yfp = max(MIN,min(MAX,U1fp + U2fp));
      end when;
    else
      Yfp = max(MIN,min(MAX,U1fp + U2fp));
    end if;

    // Output conversion
    y = Yfp/scaleFactor;

  else

    // FixedPoint variables
    U1fp = 0;
    U2fp = 0;
    Yfp = 0;

    // Math operation
    if Ts > 0 then
      when sample(0,Ts) then
        y = u1 + u2;
      end when;
    else
      y = u1 + u2;
    end if;

  end if
  ;
end Add;

within IndustrialControlSystems.MathOperations.RealType;
model Div "Division of two real numbers"
  extends
    IndustrialControlSystems.MathOperations.RealType.Interfaces.RealSimpleOperation;
equation

  if FixedPoint then

    // Overflow : Numerical error
    assert(U1fp > MIN and U1fp < MAX, "Overflow error, chose a different scale factor or Nbit");
    assert(U2fp > MIN and U2fp < MAX, "Overflow error, chose a different scale factor or Nbit");

    // FixedPoint variables
    // conversion from Real to Integer
    U1fp = integer(Functions.toFixedPoint(u1,scaleFactor,MAX,MIN));
    if abs(u2)<1 and scaleFactor > 1 then
      U2fp = integer(Functions.toFixedPoint(u2,scaleFactor,MAX,MIN));
    else
      U2fp = integer(Functions.toFixedPoint(u2,1,MAX,MIN));
    end if;

    assert(U2fp<>0,"Division by zero");

    // Math operation
    if Ts > 0 then
      when sample(0,Ts) then
        Yfp = max(MIN,min(MAX,div(U1fp,U2fp)));
      end when;
    else
      Yfp = max(MIN,min(MAX,div(U1fp,U2fp)));
    end if;

    // Output conversion
    if abs(u2)<1 and scaleFactor > 1 then
      y = Yfp;
    else
      y = Yfp/scaleFactor;
    end if;

  else

    // FixedPoint variables
    U1fp = 0;
    U2fp = 0;
    Yfp = 0;

    assert(abs(u2)>Modelica.Constants.eps,"Division by zero");

    // Math operation
    if Ts > 0 then
      when sample(0,Ts) then
        y = u1/u2;
      end when;
    else
      y = u1/u2;
    end if;

  end if

  ;
end Div;

