model noiseGen "Noise generator"
  extends Interfaces.RealNinOperation(final useInputs=false, final FixedPoint=false, final Nbit = 1, final scaleFactor = 1, final MAX = 1, final MIN = 0);
  parameter Modelica.Units.SI.Time Ts=0.1 "|Noise generator| Sampling time"
    ;
  parameter Real amp = 0.01 "|Noise generator| Amplitude" ;
  parameter Real Tf = 1 "|Noise generator| First order filter time constant" ;
  parameter Real X_start = 1 "|Noise generator| Initial value" ;
  constant Real m = 2^31 - 1 "|Algorithm| coefficient";
  constant Real a = 7^5 "|Algorithm| coefficient";
  constant Real c= 10 "|Algorithm| coefficient";
protected
  discrete Real X;
  discrete Real U;
equation
  // No Fixed Point here
  Ufp = zeros(nInput);
  Yfp = 0;
algorithm
  // initialisation
  when initial() then
     X := X_start;
  end when;

  // Random sample generator algorithm
  when noEvent(sample(0,Ts)) then
       X := (a*X+c)-div((a*X+c),m)*m;
       U := (X/2e9-0.5)*amp;
       y := (Tf*y+Ts*U)/(Tf+Ts);
  end when
  ;
end noiseGen;

