model SmoothStepSignal "Smooth step Set Point generator, driven by signals"
  extends Interfaces.RealNinOperation(final useInputs=false, final FixedPoint=false, final Nbit = 1, final scaleFactor = 1, final MAX = 1, final MIN = 0);
  Modelica.Blocks.Interfaces.BooleanInput ENup ;
  parameter Real alfa = 0.1
    "|Smooth step| Portion of time for parabolic junctions";
  parameter Real yin = 0 "|Smooth step| Output initial value";
  parameter Real yfin = 1 "|Smooth step| Output final value";
  parameter Real m = 0.1 "|Smooth step| Slope of the ramp";
  parameter Real tin = 10 "|Smooth step| Initial time";
  parameter Real delay = 0 "|Smooth step| Delay";
protected
  discrete Boolean En_d;
  discrete Boolean St(start=false);
  Real StartTime(   start=0);
equation
  En_d = ENup;
  when
      (pre(En_d)== false and En_d==true) then
    StartTime = time;
    St = true;
  end when;
  y = if
        (St==false) then
                        yin else Functions.fSmoothStep(time,StartTime+delay,alfa,m,yin,yfin);

  // No Fixed Point here
  Ufp = zeros(nInput);
  Yfp = 0

  ;
end SmoothStepSignal;

