model SmoothThooth "Smooth thooth Set point generator"
  extends Interfaces.RealNinOperation(final useInputs=false, final FixedPoint=false, final Nbit = 1, final scaleFactor = 1, final MAX = 1, final MIN = 0);
  parameter Real ts = 10 "|Smooth step| Initial rising time";
  parameter Real td = 29 "|Smooth step| Initial falling time";
  parameter Real alfa = 0.1
    "|Smooth step| Portion of time for parabolic junctions";
  parameter Real yin = 0 "|Smooth step| Output initial value";
  parameter Real yfin = 1 "|Smooth step| Output final value";
  parameter Real m = 0.1 "|Smooth step| Slope of the ramp";
equation
  assert(alfa>=0 and alfa<=1,"alfa out of range [0,1]");
  assert(td>ts+(abs(yin-yfin)/m)*(1+alfa),"you have to increase td");

  y = if (time<td) then
         Functions.fSmoothStep(time,ts,alfa,m,yin,yfin) else
         Functions.fSmoothStep(time,td,alfa,m,yfin,yin);

  // No Fixed Point here
  Ufp = zeros(nInput);
  Yfp = 0

  ;
end SmoothThooth;

within IndustrialControlSystems.MathOperations.RealType.Signals;
model SmoothThoothSignal "Smooth thooth Set Point generator, driven by signals"
  extends Interfaces.RealNinOperation(final useInputs=true,final nInput = 2, final FixedPoint=false, final Nbit = 1, final scaleFactor = 1, final MAX = 1, final MIN = 0);
  Modelica.Blocks.Interfaces.BooleanInput ENup ;
  Modelica.Blocks.Interfaces.BooleanInput ENdown ;
  Real ts;
  Real td;
  Boolean Sali(start=false);
  Boolean Scendi(start=false);
  parameter Real alfa =  0.1
    "|Smooth step| Portion of time for parabolic junctions";
  parameter Real m =     0.1 "|Smooth step| Slope of the ramp";
  parameter Real wait_s = 0 "|Smooth step| Rising delay";
  parameter Real wait_d = 0 "|Smooth step| Falling delay";
protected
  discrete Boolean Ed_d;
  discrete Boolean Es_d;
equation
  Ed_d = ENdown;
  Es_d = ENup;

  when
      (pre(Ed_d)== false and Ed_d==true) then
    td = time + wait_d;
    Scendi = true;
  end when;

  when
      (pre(Es_d)== false and Es_d==true) then
    ts = time + wait_s;
    Sali = true;
  end when;

  y = Functions.f(
    Sali,
    Scendi,
    time,
    ts,
    td,
    alfa,
    m,
    u[1],
    u[2]);

  // No Fixed Point here
  Ufp = zeros(nInput);
  Yfp = 0

  ;
end SmoothThoothSignal;

