partial model OnePortAC "Base class for non-bus AC components with one port"
  import PowerGrids.Types.Choices.LocalInitializationOption;
  extends OnePortACVI(
    final isOnePortAC = true,
    redeclare connector TerminalAC = Interfaces.TerminalAC,
    terminalAC(
      final computePF = computePF,
      terminalACPF(final v = vPF, final i = iPF)));
  parameter LocalInitializationOption localInit = LocalInitializationOption.none "Initialize the component locally in steady state from port start values" ;
  parameter Boolean hasSubPF = false "= true, if the model contains a sub-network with its own embedded PF; set to final in usable components" ;

  replaceable BaseComponents.OnePortACPFDummy componentPF if computePF and not hasSubPF constrainedby OnePortACPF "component to be used to compute the embedded PF" ;

  Types.ComplexVoltage vPF "Phase-to-ground voltage phasor of embedded power flow model";
  Types.ComplexCurrent iPF "Line current phasor of embedded power flow model";

initial equation
  if computePF then
    // set default values for PStart and QStart based on embedded power flow solution
    UStartPF = CM.abs(vPF)*sqrt(3);
    UPhaseStartPF = CM.arg(vPF);
    PStartPF = 3*CM.real(vPF*CM.conj(iPF));
    QStartPF = 3*CM.imag(vPF*CM.conj(iPF));
  else
    // set dummy values for PStartPF and QStartPF which  (not used)
    UStartPF = 0;
    UPhaseStartPF = 0;
    PStartPF = 0;
    QStartPF = 0;
  end if;

equation
  // Connect the terminalACPF sub-connector to the terminalAC connector of the
  // embedded power flow component (if activated)
  connect(terminalAC.terminalACPF, componentPF.terminalAC);

  // Set appropriate relationships between connector and port voltage and currents
  // based on the selected initializatio option
  if initial() and localInit == LocalInitializationOption.PV then
    // During local initialization, P,V is enforced at the connector towards
    // the grid, while Q,phase(V) is enforced at the port towards the component
    // Further two initial equations will be needed (e.g. in the controller)
    // to enforce P,V at the port or achieve actuator saturation if that is not possible
    CM.real(terminalAC.v*CM.conj(terminalAC.i)) = port.PStart;
    CM.abs(terminalAC.v) = port.VStart;
    port.Q = port.QStart;
    port.v.re*port.vStart.im = port.v.im*port.vStart.re;
  elseif initial() and localInit == LocalInitializationOption.PQ then
    // During local initialization, P,Q is enforced at the connector towards
    // the grid, while phase(V), phase(I) is enforced at the port towards the component
    // Further two initial equations will be needed (e.g. in the controller)
    // to enforce P,Q at the port or achieve actuator saturation if that is not possible
    terminalAC.v*CM.conj(terminalAC.i) = Complex(port.PStart, port.QStart);
    port.v.re*port.vStart.im = port.v.im*port.vStart.re;
    port.i.re*port.iStart.im = port.i.im*port.iStart.re;
  else
    // In all other cases, the port voltage and current are identically equal to
    // the connector voltage and current
    port.v = terminalAC.v;
    port.i = terminalAC.i;
  end if;

  // if the embedded power flow is not computed, set unused vPF and iPF to dummy values
  if not computePF then
    vPF = Complex(0) "Dummy value";
    iPF = Complex(0) "Dummy value";
  end if

  ;
end OnePortAC;

within PowerGrids.Electrical.BaseClasses;

partial model OnePortACdqPu "Base class for one-port AC components with p.u. Park's transformation"
  extends OnePortAC;

  parameter SI.Angle thetaStart = UPhaseStart "Start value of rotation between machine rotor frame and port phasor frame" ;

  final parameter Types.PerUnit udPuStart(fixed = false) "Start value of udPu";
  final parameter Types.PerUnit uqPuStart(fixed = false) "Start value of uqPu";
  final parameter Types.PerUnit idPuStart(fixed = false) "Start value of idPu";
  final parameter Types.PerUnit iqPuStart(fixed = false) "Start value of iqPu";

  // d-q axis p.u. variables
  Types.PerUnit udPu(start = udPuStart) "Voltage of direct axis in p.u.";
  Types.PerUnit uqPu(start = uqPuStart) "Voltage of quadrature axis in p.u.";
  Types.PerUnit idPu(start = idPuStart) "Current of direct axis in p.u.";
  Types.PerUnit iqPu(start = iqPuStart) "Current of quadrature axis in p.u.";

  // other variables
  Types.Angle theta(start = thetaStart) "Rotation between machine rotor frame and port phasor frame";

initial equation
  // Park's transformations for start values
  port.vStart.re/port.VBase =  sin(thetaStart)*udPuStart + cos(thetaStart)*uqPuStart;
  port.vStart.im/port.VBase = -cos(thetaStart)*udPuStart + sin(thetaStart)*uqPuStart;
  port.iStart.re/port.IBase =  sin(thetaStart)*idPuStart + cos(thetaStart)*iqPuStart;
  port.iStart.im/port.IBase = -cos(thetaStart)*idPuStart + sin(thetaStart)*iqPuStart;

equation
  // Park's transformations
  port.vPu.re =  sin(theta)*udPu + cos(theta)*uqPu;
  port.vPu.im = -cos(theta)*udPu + sin(theta)*uqPu;
  port.iPu.re =  sin(theta)*idPu + cos(theta)*iqPu;
  port.iPu.im = -cos(theta)*idPu + sin(theta)*iqPu
;
end OnePortACdqPu;

within PowerGrids.Electrical.BaseClasses;

partial model OnePortACPF
  extends OnePortACVI(
    redeclare replaceable connector TerminalAC = PowerGrids.Interfaces.TerminalACPF);
  Boolean isSlackBus = false "=true, if the componentsPF is a slack bus";
  final Modelica.Blocks.Interfaces.BooleanOutput isSlackBusOut = isSlackBus "output connector to propagate the value of the flag isSlackBus";

protected
  // The following parameter and variables are used as workaround to force the computation of
  // the Embedded Power Flow before to start the initialization, in order to proper compute the start
  // values of the initialization itself.
  // This workaround in necessary because some Modelica compilers does not correctly implement the dependency
  // introduced by the start attributes (see Modelica Specificatoin - section 8.6).
  parameter Real zero = 0 ;
  final Real Pepf = PStart;
  final Real Qepf = QStart;
  final Real Uepf = UStart;
  final Real UPhepf = UPhaseStart;

initial equation
  UStartPF = UNom;
  UPhaseStartPF = 0;
  PStartPF = 0;
  QStartPF = 0;

equation
  port.v = terminalAC.v + zero*Complex(Pepf+Qepf+Uepf+UPhepf) "the part multiplied by zero is to force the EPF computation before to start the initialization";
  port.i = terminalAC.i + zero*Complex(Pepf+Qepf+Uepf+UPhepf) "the part multiplied by zero is to force the EPF computation before to start the initialization"
;    
end OnePortACPF;

