model PortAC "AC port computing auxiliary quantities"
  parameter Types.Power   SNom(start = 100e6) "Nominal or rated power";
  parameter Types.Voltage UNom(start = 400e3) "Nominal or rated phase-to-phase voltage";
  final parameter Types.Power   SBase = SNom "Base power";
  final parameter Types.Voltage UBase = UNom "Base phase-to-phase voltage";

  parameter Types.Power PStart = 0 "Start value of active power flowing into port";
  parameter Types.Power QStart = 0 "Start value of reactive power flowing into port";
  parameter Types.Voltage UStart = UNom "Start value of phase-to-phase voltage modulus";
  parameter Types.Angle UPhaseStart = 0 "Start value of voltage phase";

  parameter Boolean portVariablesPhases = false "Compute voltage and current phases for monitoring purposes only" ;
  constant Boolean generatorConvention = false "Also compute currents and power variables with generator convention (positive when exiting the device)";

// Computed parameters
  final parameter Types.Voltage VNom = UNom/sqrt(3) "Nominal phase-to-ground voltage";
  final parameter Types.Current INom = SNom/(3*VNom) "Nominal current";

  final parameter Types.Voltage VBase = UBase/sqrt(3) "Base phase-to-ground voltage";
  final parameter Types.Current IBase = SBase/(3*VBase) "Base current";

  final parameter Types.Voltage VStart = UStart/sqrt(3) "Start value of phase-to ground voltage modulus";
  final parameter Types.Current IStart = sqrt(PStart^2 + QStart^2)/(3*VStart) "Start value of current modulus";

  final parameter Types.ComplexVoltage vStart = CM.fromPolar(UStart/sqrt(3), UPhaseStart)
    "Start value of phase-to-ground voltage phasor";
  final parameter Types.ComplexCurrent iStart = CM.conj(Complex(PStart,QStart)/(Complex(3)*vStart))
    "Start value of current phasor flowing into the port";

  connector InputComplexVoltage = input Types.ComplexVoltage "Marks potential input for balancedness check without requiring binding equation";
  connector InputComplexCurrent = input Types.ComplexCurrent "Marks potential input for balancedness check without requiring binding equation";

  InputComplexVoltage v(re(nominal = VNom, start = vStart.re),
                        im(nominal = VNom, start = vStart.im)) "Port voltage (line-to-neutral)";
  InputComplexCurrent i(re(nominal = INom, start = iStart.re),
                        im(nominal = INom, start = iStart.im)) "Port current";

  Types.ComplexVoltage u(re(nominal = UNom, start = vStart.re*sqrt(3)),
                         im(nominal = UNom, start = vStart.im*sqrt(3))) = sqrt(3)*v
     "Complex phase-to-phase voltage";
  Types.ComplexPower   S(re(nominal = SNom), im(nominal = SNom)) = 3*v*CM.conj(i)
     "Complex power flowing into the port";
  Types.ActivePower   P(nominal = SNom, start = PStart) = S.re "Active power flowing into the port";
  Types.ReactivePower Q(nominal = SNom, start = QStart) = S.im "Reactive power flowing into the port";

  Types.Voltage U(nominal = UNom, start = UStart) = CM.abs(u) "Port voltage absolute value (phase-to-phase)";
  Types.Current I(nominal = INom, start = IStart) = CM.abs(i) "Port current (positive entering)";

  Types.PerUnit        PPu(start = PStart/SBase) = S.re/SBase "Active power flowing into the port in p.u. (base SBase)";
  Types.PerUnit        QPu(start = QStart/SBase) = S.im/SBase "Reactive power flowing into the port in p.u. (base SBase)";
  Types.ComplexPerUnit vPu(re(start = vStart.re/VBase),im(start = vStart.im/VBase)) = u*(1/UBase) "Complex voltage across the port in p.u. (base VBase)";
  SI.PerUnit           VPu(start = VStart/VBase) = U/UBase "Absolute value of voltage across the port in p.u. (base VBase)";
  Types.ComplexPerUnit iPu(re(start = iStart.re/IBase), im(start = iStart.im/IBase)) = i*(1/IBase) "Complex current flowing into the port in p.u. (base IBase)";
  SI.PerUnit           IPu(start = IStart/IBase) = I/IBase "Absolute value of complex current flowing into the port in p.u. (base IBase)";

  Types.Angle UPhase(start = UPhaseStart) = if portVariablesPhases then atan2(v.im, v.re) else 0 "Phase of voltage across the port";
  Types.Angle IPhase(start = CM.arg(iStart)) = if portVariablesPhases then atan2(i.im, i.re) else 0 "Phase of current into the port";

  Types.ComplexCurrent iGen(re(nominal = INom, start = -iStart.re),
                            im(nominal = INom, start = -iStart.im)) = if generatorConvention then  -i else Complex(0)
                             "Port current, generator convention";
  Types.ActivePower PGen(nominal = SNom, start = -PStart) = if generatorConvention then -S.re else 0
                             "Active power flowing out of the port";
  Types.ReactivePower QGen(nominal = SNom, start = -QStart) = if generatorConvention then -S.im else 0
                             "Reactive power flowing out of the port";
  Types.PerUnit PGenPu(start = -PStart/SBase) = if generatorConvention then -PPu else 0
                             "Active power flowing out of the port in p.u. (base SBase)";
  Types.PerUnit QGenPu(start = -QStart/SBase) = if generatorConvention then -QPu else 0
                             "Reactive power flowing out of the port in p.u. (base SBase)";
  Types.ComplexPerUnit iGenPu(re(start = -iStart.re/IBase),
                              im(start = -iStart.im/IBase)) = if generatorConvention then -iPu else Complex(0)
                               "Complex current flowing out of the port in p.u. (base IBase)";
  SI.PerUnit IGenPu(start = IStart/IBase) = if generatorConvention then I/IBase else 0
                               "Absolute value of current flowing out of the port in p.u. (base IBase)" 

  ;
end PortAC;

