model InfiniteBusVariableVoltage
  extends Icons.Bus(VPuIcon=port.VPu, UIcon=port.U, UPhaseIcon=port.UPhase);
  extends Electrical.BaseClasses.SolutionChecking(VPuCheck = port.VPu, IPuCheck = port.IPu);
