      final computePF = computePF,
      terminalACPF(final v = vPF, final i = iPF)),
    e = CM.fromPolar(UAux/sqrt(3), UPhaseAux),
    Z = Complex(R, X));
  extends PowerGrids.Electrical.BaseClasses.OnePortAC(
    final hasSubPF,
    final localInit,
    final isLinear = true,
    redeclare PowerGrids.Electrical.PowerFlow.InfiniteBusPF componentPF(
      UNom = UNom, SNom = SNom, URef = UFixed, UPhase = UPhaseFixed, R = R, X = X));

  parameter Boolean useUIn = false "Use external input for source voltage magnitude" ;
  parameter Boolean useUPhaseIn = false "Use external input for source voltage angle" ;
  parameter Types.Resistance R = 0 "Series resistance";
  parameter Types.Reactance X = 0 "Series reactance";
  parameter Types.Voltage UFixed = UNom "Fixed source voltage modulus, phase-to-phase, reference Voltage for the embedded PF" ;
  parameter Types.Angle UPhaseFixed = 0 "Fixed angle of source voltage, reference angle for the embedded PF" ;
  Modelica.Blocks.Interfaces.RealInput UIn(unit = "V", displayUnit = "kV") if useUIn "Source voltage modulus input, phase-to-phase, V" ;
  Modelica.Blocks.Interfaces.RealInput UPhaseIn(unit = "rad", displayUnit = "deg") if useUPhaseIn "Source voltage phase angle input, rad" ;
protected
  // Auxiliary hidden connectors to manage the conditional connectors
  Modelica.Blocks.Interfaces.RealInput UAux "Source voltage modulus, phase-to-phase";
  Modelica.Blocks.Interfaces.RealInput UPhaseAux "Source voltage phase angle";
equation
// Conditional connectors
  connect(UIn, UAux);
  if not useUIn then
    UAux = UFixed;
  end if;
  connect(UPhaseIn, UPhaseAux);
  if not useUPhaseIn then
    UPhaseAux = UPhaseFixed;
  end if;
  assert(UAux >= 0, "Magnitude must be positive");
// Overconstrained connector
  Connections.potentialRoot(terminalAC.omegaRefPu);
  if Connections.isRoot(terminalAC.omegaRefPu) then
    terminalAC.omegaRefPu = 1;
  end if
  ;
end InfiniteBusVariableVoltage;

