model ExciterVoltageTransducerIEEE "Exciter voltage transducer"
  parameter SI.PerUnit kp = 9.3"First potential circuit gain";
  parameter SI.Angle thetap = 0 "Potential circuit phase angle Thetap";
  parameter SI.PerUnit ki = 0 "Second potential circuit gain coefficient";
  parameter SI.PerUnit xl = 0.124 "Reactance associated with potential source";
  Modelica.ComplexBlocks.Interfaces.ComplexInput Vt ;
  Modelica.ComplexBlocks.Interfaces.ComplexInput It ;
  Modelica.Blocks.Interfaces.RealOutput Ve ;
  Modelica.Blocks.Sources.Constant constKp(k = kp)  ;
  Modelica.Blocks.Sources.Constant constThetap(k = thetap)  ;
  Modelica.ComplexBlocks.ComplexMath.Add add1 ;
  Modelica.ComplexBlocks.ComplexMath.ComplexToPolar complexToPolar ;
  Modelica.ComplexBlocks.ComplexMath.PolarToComplex complexKp ;
  Modelica.ComplexBlocks.ComplexMath.Gain gainXl(k.re = 0, k.im = xl) ;
  Modelica.ComplexBlocks.ComplexMath.Gain J(k.re = 0, k.im = 1) ;
  Modelica.ComplexBlocks.ComplexMath.Product prod1 ;
  Modelica.ComplexBlocks.ComplexMath.Add add2 ;
  Modelica.ComplexBlocks.ComplexMath.Product prod2 ;
  Modelica.ComplexBlocks.Sources.ComplexConstant constKi(k.re = ki, k.im = 0) ;
equation
  connect(constKi.y, add1.u2) ;
  connect(Vt, prod2.u1) ;
  connect(complexToPolar.len, Ve) ;
  connect(add2.y, complexToPolar.u) ;
  connect(prod1.y, add2.u2) ;
  connect(prod2.y, add2.u1) ;
  connect(complexKp.y, prod2.u2) ;
  connect(It, prod1.u2) ;
  connect(J.y, prod1.u1) ;
  connect(add1.y, J.u) ;
  connect(gainXl.y, add1.u1) ;
  connect(complexKp.y, gainXl.u) ;
  connect(constThetap.y, complexKp.phi) ;
  connect(constKp.y, complexKp.len) 
  ;
end ExciterVoltageTransducerIEEE;

within PowerGrids.Electrical.VoltageTransducers;
model TerminalVoltageTransducerIEEE "Terminal voltage transducer IEEE"
  parameter SI.Time Tr = 0 "Transducer time constant";
  parameter SI.PerUnit Rc = 0 "Load compensation resistance";
  parameter SI.PerUnit Xc = 0 "Load compensation reactance";
  parameter Modelica.Blocks.Types.Init initType=Modelica.Blocks.Types.Init.NoInit "Type of initialization (1: no init, 2: steady state, 3/4: initial output)" ;
  parameter Real yStart=0 "Initial or guess value of output (= state)" ;
