    population = initial_population;
  elseif init==InitializationOptions.SteadyState then
    der(population) = 0;
  else
  end if;
equation
  der(population) = species.rate;
  assert(population>=0, "Population must be greater than or equal to zero")
  ;
end RegionalPopulation;

