    ;
  Analog.Ideal.IdealDiode D2(Vknee=0, Ron=1e-5, Goff=1e-5)
    ;
  Analog.Ideal.IdealDiode D3(Vknee=0, Ron=1e-5, Goff=1e-5)
    ;
  Analog.Ideal.IdealDiode D4(Vknee=0, Ron=1e-5, Goff=1e-5)
    ;
  Analog.Basic.Ground ground1
    ;
equation
  connect(D1.p, D3.p) ;
  connect(load.p, capacitor.p) ;
  connect(load.p, D2.n) ;
  connect(D1.n, D2.p) ;
  connect(switch.p, wall_voltage.p) ;
  connect(switch.n, transformer.p1) ;
  connect(step.y, switch.control) ;
  connect(D3.n, D4.p) ;
  connect(D2.n, D4.n) ;
  connect(transformer.p2, D1.n) ;
  connect(D4.p, transformer.n2) ;
  connect(wall_voltage.n, transformer.n1) ;
  connect(wall_voltage.n, ground1.p) ;
  connect(transformer.n2, ground1.p) ;
  connect(D1.p, capacitor.n) ;
  connect(load.n, capacitor.n) ;
