    parameter Real sigma=sqrt(noisePower/samplePeriod);
  initial equation
     r = distribution(r_raw, mu, sigma);
  equation

    when generateNoise and sample(startTime, samplePeriod) then
      r = distribution(r_raw, mu, sigma);
    end when
                                                                                        ;
  end BandLimitedWhiteNoise
