  "Connector of Boolean output signal"     ;
protected
  Boolean y2(start=y_start);
  Boolean y3(start=y_start, fixed=true);
  Boolean uu ;
equation
  when Clock() then
     uu = u "Dummy assignment to relate clock of u with y2";
