    period = 1,
    offset = 1)
    ;
  Clocked.ClockSignals.Clocks.Rotational.RotationalClock rotational_clock_1
    ;
  Clocked.ClockSignals.Clocks.Rotational.RotationalClock rotational_clock_2
    ;
