    ;
  connect(trigger_interval_input.y, rotational_clock_1.trigger_interval)
    ;
  connect(trigger_interval_input.y, rotational_clock_2.trigger_interval)
    ;
  connect(cosine_angle_input.y, rotational_clock_2.angle)
    ;
