    ;
  connect(rotational_clock_2.y, conjunctiveClock.u[2])
    ;
  connect(rotational_clock_1.y, disjunctiveClock.u[1])
    ;
  connect(rotational_clock_2.y, disjunctiveClock.u[2])
    ;
  connect(disjunctiveClock.y, sample_disjunctive.clock) ;
  connect(conjunctiveClock.y, sample_conjunctive.clock) ;
  connect(sample_conjunctive.u, sine_angle_input.y) ;
  connect(sample_disjunctive.u, sine_angle_input.y) 
  ;
end LogicalSample;

