within Modelica.Electrical.Batteries.BaseClasses;
partial model BaseCellStack
  "Battery with open-circuit voltage dependent on state of charge, self-discharge and inner resistance"
  extends Modelica.Electrical.Batteries.Icons.BatteryIcon(final displaySOC=SOC);
  parameter Integer Ns(final min=1)=1 "Number of serial connected cells";
  parameter Integer Np(final min=1)=1 "Number of parallel connected cells";
  replaceable parameter ParameterRecords.CellData cellData "Cell parameters"
    ;
  parameter Real SOCtolerance=1e-9 "Tolerance to detect depleted of overcharged battery"
    ;
  extends Modelica.Electrical.Analog.Interfaces.TwoPin;
  SI.Current i = p.i "Current into the battery";
  SI.Power power = v*i "Power to the battery";
  output Real SOC(start=cellData.SOCmax) = limIntegrator.y "State of charge"
    ;
  Modelica.Electrical.Analog.Sensors.CurrentSensor currentSensor
    ;
  Blocks.Continuous.LimIntegrator limIntegrator(
    final k=1/(Np*cellData.Qnom),
    outMax=1 - SOCtolerance,
    outMin=SOCtolerance,
      final initType=Modelica.Blocks.Types.Init.NoInit) ;
  Modelica.Blocks.Tables.CombiTable1Ds ocv_soc(
    final table=cellData.OCV_SOC_internal,
    final smoothness=cellData.smoothness,
    extrapolation=Modelica.Blocks.Types.Extrapolation.HoldLastPoint)
    ;
  Modelica.Blocks.Math.Gain gainV(final k=Ns*cellData.OCVmax) ;
  Modelica.Electrical.Analog.Sources.SignalVoltage ocv
    ;
  Modelica.Electrical.Analog.Basic.Conductor selfDischarge(
    final G=Np*cellData.Idis/(Ns*cellData.OCVmax),
    T_ref=293.15,
    final useHeatPort=true)
    ;
  Modelica.Electrical.Analog.Basic.Resistor r0(
    final T_ref=cellData.T_ref,
    final alpha=cellData.alpha,
    final useHeatPort=true)
    ;
  extends Modelica.Electrical.Analog.Interfaces.PartialConditionalHeatPort;
equation
  assert(cellData.OCVmax > cellData.OCVmin, "Specify 0 <= OCVmin < OCVmax");
  assert(cellData.SOCmax > cellData.SOCmin, "Specify 0 <= SOCmin < SOCmax <= 1");
  assert(cellData.OCV_SOC[1, 1] >= 0, "Specify OCV(SOC) table with minimum SOC >= 0");
  assert(cellData.OCV_SOC[end, 1] <= 1,  "Specify OCV(SOC) table with maximum SOC <= 1");
  assert(cellData.OCV_SOC[1, 2] >= 0, "Specify OCV(SOC) table with minimum OCV/OCVmax >= 0");
  assert(cellData.OCV_SOC[end, 2] <= 1, "Specify OCV(SOC) table with maximum OCV/OCVmax <= 1");
  assert(SOC < cellData.SOCmax + SOCtolerance, "Battery overcharged!");
  assert(SOC > cellData.SOCmin - SOCtolerance, "Battery exhausted!");
  connect(gainV.y, ocv.v)
    ;
  connect(ocv_soc.y[1], gainV.u)
    ;
  connect(limIntegrator.y, ocv_soc.u)
    ;
  connect(currentSensor.n, ocv.p)
    ;
  connect(limIntegrator.u, currentSensor.i)
    ;
  connect(p, currentSensor.p)
    ;
  connect(ocv.n, r0.p)
    ;
  connect(currentSensor.p, selfDischarge.p) ;
  connect(ocv.n, selfDischarge.n)
    ;
  connect(selfDischarge.heatPort, internalHeatPort) ;
  connect(internalHeatPort, r0.heatPort) 
  ;
end BaseCellStack;

within Modelica.Electrical.Batteries.BaseClasses;
partial model BaseCellWithSensors "Partial cell with sensors"
  extends Modelica.Electrical.Batteries.Icons.BatteryIcon(final displaySOC=SOC);
  replaceable parameter Modelica.Electrical.Batteries.ParameterRecords.CellData cellData
    "Cell parameters"
    ;
  parameter Real SOC0=0.1 "Initial SOC";
  parameter Real SOCtolerance=1e-9 "SOC tolerance for detection of depleted or overcharged cell"
    ;
  extends Modelica.Electrical.Analog.Interfaces.TwoPin;
  output SI.Current i = p.i "Current into the cell";
  output SI.Power power = v*i "Power to the cell";
  output Real SOC = limIntegrator.y "State of charge";
  extends Modelica.Electrical.Analog.Interfaces.PartialConditionalHeatPort;
  replaceable Modelica.Electrical.Batteries.BatteryStacks.CellStack cell(
    final Ns=1,
    final Np=1,
    SOCtolerance=SOCtolerance,
    cellData=cellData,
    SOC(start=SOC0, fixed=true),
    useHeatPort=true,
    T=T) "Cell"
    ;
  Modelica.Electrical.Analog.Sensors.MultiSensor multiSensor
    ;
  Modelica.Blocks.Continuous.LimIntegrator limIntegrator(
    k=1/cellData.Qnom,
    outMax=1 - SOCtolerance,
    outMin=SOCtolerance,
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=SOC0)
    ;
  Modelica.Thermal.HeatTransfer.Sensors.TemperatureSensor temperatureSensor
    ;
  Modelica.Thermal.HeatTransfer.Sensors.HeatFlowSensor heatFlowSensor
    ;
  Modelica.Electrical.Batteries.Interfaces.CellBus cellBus "Cell bus"
    ;
equation
  connect(p, multiSensor.pc)
    ;
  connect(multiSensor.pc, multiSensor.pv)
    ;
  connect(multiSensor.nc, cell.p)
    ;
  connect(cell.n, n)
    ;
  connect(multiSensor.i, limIntegrator.u) ;
  connect(limIntegrator.y, cellBus.soc) ;
  connect(multiSensor.v, cellBus.v) ;
  connect(multiSensor.i, cellBus.i) ;
  connect(multiSensor.power, cellBus.power) ;
  connect(heatFlowSensor.port_b, internalHeatPort) ;
  connect(heatFlowSensor.port_a, cell.heatPort)
    ;
  connect(heatFlowSensor.Q_flow, cellBus.lossPower) ;
  connect(temperatureSensor.T, cellBus.T) ;
  connect(n, multiSensor.nv) ;
  connect(heatFlowSensor.port_a, temperatureSensor.port)

  ;
end BaseCellWithSensors;

within Modelica.Electrical.Batteries.BaseClasses;
partial model BaseStackWithSensors "Partial stack with sensors"
  extends Modelica.Electrical.Batteries.Icons.BatteryIcon(final displaySOC=SOC);
  replaceable parameter BaseStackData stackData
    ;
  parameter Boolean useAllParallelConnections=true "= true, if all parallel connections are used";
  parameter Real SOC0[stackData.Ns, stackData.Np]=fill(0.1, stackData.Ns, stackData.Np) "Initial SOC";
  parameter Real SOCtolerance=1e-9 "SOC tolerance for detection of depleted or overcharged cell"
    ;
  extends Modelica.Electrical.Analog.Interfaces.TwoPin;
  output SI.Current i = p.i "Current into the stack";
  output SI.Power power = v*i "Power to the stack";
  output Real SOC = socTotal.y "Overall State of charge";
  parameter Boolean useHeatPort = false "=true, if HeatPort is enabled"
    ;
  parameter SI.Temperature T=293.15
    "Fixed device temperature if useHeatPort = false"
    ;
  replaceable Modelica.Electrical.Batteries.BaseClasses.BaseCellWithSensors
    cell[stackData.Ns,stackData.Np](
    each SOCtolerance=SOCtolerance,
    each useHeatPort=false,
    each T=T,
    cellData=stackData.cellData,
    SOC0=SOC0) "Matrix of cells"
    ;
  Modelica.Electrical.Analog.Sensors.MultiSensor multiSensor
    ;
  Modelica.Electrical.Batteries.Interfaces.StackBus stackBus(Ns=stackData.Ns,
      Np=stackData.Np) "Stack bus"
    ;
  Modelica.Electrical.Batteries.Interfaces.CellBus batteryBus
    "Battery bus (average / sum over all cells)"
    ;
  Modelica.Blocks.Sources.RealExpression socTotal(
    y=sum(stackBus.cellBus.soc.*stackData.cellData.Qnom)/sum(stackData.cellData.Qnom)) ;
  Modelica.Blocks.Sources.RealExpression lossesTotal(y=sum(stackBus.cellBus.lossPower))
    ;
  Modelica.Blocks.Sources.RealExpression temperatureTotal(y=sum(stackBus.cellBus.T)/(stackData.Ns*stackData.Np))
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPort[stackData.Ns, stackData.Np] if useHeatPort
    "Optional port to which dissipated losses are transported in form of heat"
    ;
equation

  connect(multiSensor.nc, cell[1, 1].p)
    ;
  connect(cell[stackData.Ns, 1].n, n)
    ;
  connect(cell.cellBus, stackBus.cellBus) ;
  if useAllParallelConnections then
    for ks in 1:stackData.Ns loop
      for kp in 1:stackData.Np-1 loop
        connect(cell[ks, kp].p, cell[ks, kp + 1].p);
        connect(cell[ks, kp].n, cell[ks, kp + 1].n);
      end for;
    end for;
    for ks in 1:stackData.Ns-1 loop
      connect(cell[ks, 1].n, cell[ks + 1, 1].p);
    end for;
  else
    for kp in 1:stackData.Np loop
      for ks in 1:stackData.Ns-1 loop
        connect(cell[ks, kp].n, cell[ks + 1, kp].p);
      end for;
    end for;
    for kp in 1:stackData.Np-1 loop
      connect(cell[1, kp].p, cell[1, kp + 1].p);
      connect(cell[stackData.Ns, kp].n, cell[stackData.Ns, kp + 1].n);
    end for;
  end if;
  connect(p,multiSensor.pc)
    ;
  connect(multiSensor.pc,multiSensor.pv)
    ;
  connect(n, multiSensor.nv)
    ;
  connect(multiSensor.i, batteryBus.i) ;
  connect(multiSensor.power, batteryBus.power) ;
  connect(multiSensor.v, batteryBus.v) ;
  connect(socTotal.y, batteryBus.soc) ;
  connect(temperatureTotal.y, batteryBus.T) ;
  connect(lossesTotal.y, batteryBus.lossPower) ;
  connect(cell.heatPort, heatPort)

  ;
end BaseStackWithSensors;

within Modelica.Electrical.Batteries.BatteryStacks;
model CellRCStack
  "Battery with open-circuit voltage dependent on state of charge, self-discharge, inner resistance and a series of RC-elements"
  extends Modelica.Electrical.Batteries.BaseClasses.BaseCellStack(r0(final R=Ns*cellData.R0/Np),
    redeclare Modelica.Electrical.Batteries.ParameterRecords.TransientData.CellData cellData);
  extends Modelica.Electrical.Batteries.Icons.TransientModel;
  Modelica.Electrical.Analog.Basic.Resistor resistor[cellData.nRC](
    final R=Ns*cellData.rcData.R/Np,
    final T_ref=cellData.rcData.T_ref,
    final alpha=cellData.rcData.alpha,
    each final useHeatPort=true)
    ;
  Modelica.Electrical.Analog.Basic.Capacitor capacitor[cellData.nRC](each v(
        fixed=true, each start=0), final C=Np*cellData.rcData.C/Ns)
    ;
equation
  assert(cellData.R0 > 0, "Ri has to be greater than sum(rcParameters.R)");
  assert(cellData.rcData[1].R > 0, "Parameters of RC-elements undefined!");

  connect(resistor[1].p, r0.n)
    ;
  for k in 1:cellData.nRC loop
    connect(capacitor[k].p, resistor[k].p)
      ;
    connect(capacitor[k].n, resistor[k].n)
      ;
    connect(internalHeatPort, resistor[k].heatPort)
      ;
    if k < cellData.nRC then
      connect(resistor[k].n, resistor[k + 1].p);
    end if;
  end for;
  connect(resistor[cellData.nRC].n, n)

  ;
end CellRCStack;

within Modelica.Electrical.Batteries.BatteryStacks;
model SuperCap "Simple model of a supercapacitor"
  extends Modelica.Electrical.Analog.Interfaces.TwoPin;
  SI.Current i = p.i "Current into the supercap";
  parameter SI.Voltage Vnom "Nominal voltage";
  parameter SI.Voltage V0=Vnom "Initial voltage";
  parameter SI.Capacitance C "Capacitance";
  parameter SI.ElectricCharge Qnom=C*Vnom "Nominal charge";
  parameter SI.Resistance Rs "Series resistance";
  parameter SI.Temperature T_ref=293.15 "Reference temperature";
  parameter SI.LinearTemperatureCoefficient alpha=0 "Temperature coefficient of resistance at T_ref";
  parameter SI.Current Idis=0 "Self-discharge current at nominal voltage"
    ;
  extends Modelica.Electrical.Analog.Interfaces.PartialConditionalHeatPort;
  Modelica.Electrical.Analog.Basic.Resistor resistor(
    final R=Rs,
    final T_ref=T_ref,
    final alpha=alpha,
    final useHeatPort=true)
    ;
  Modelica.Electrical.Analog.Basic.Conductor conductor(
    final G=Idis/Vnom,
    T_ref=293.15,
    final useHeatPort=true)
    ;
  Modelica.Electrical.Analog.Basic.Capacitor capacitor(v(start=V0, fixed=true), final C=C)
    ;
equation
  connect(p, resistor.p)
    ;
  connect(resistor.n, capacitor.p)
    ;
  connect(capacitor.n, n)
    ;
  connect(capacitor.p, conductor.p)
    ;
  connect(capacitor.n, conductor.n)
    ;
  connect(internalHeatPort, conductor.heatPort) ;
  connect(internalHeatPort, resistor.heatPort) 
  ;
end SuperCap;

