  connect(pwm.notFire, dcdc.fire_n)
    ;
  connect(pin_nBat, dcdc.dc_n1) ;
  connect(pin_pBat, dcdc.dc_p1) ;
  connect(dcdc.dc_p2, pin_pMot) ;
