  extends Modelica.Blocks.Interfaces.MIMOs(final n=2);
protected
  Real RotationMatrix[2, 2]={{+cos(-angle),-sin(-angle)},{+sin(-angle),+
      cos(-angle)}};

public
  Modelica.Blocks.Interfaces.RealInput angle(unit="rad") ;
equation
