equation
  connect(phi, toGamma.u)
    ;
  connect(rotator.angle, toGamma.y)
    ;
  connect(rotator.y, fromSpacePhasor.u)
    ;
  connect(i0.y, fromSpacePhasor.zero) ;
  connect(u, rotator.u) ;
  connect(fromSpacePhasor.y, y) 
  ;
end FromDQ;

