within Modelica.Electrical.Polyphase.Sensors;
model PowerSensor "Polyphase instantaneous power sensor"
  extends Modelica.Icons.RoundSensor;
  parameter Integer m(min=1) = 3 "Number of phases" ;
  Polyphase.Interfaces.PositivePlug pc(final m=m) "Positive plug, current path"
    ;
  Polyphase.Interfaces.NegativePlug nc(final m=m) "Negative plug, current path"
    ;
  Polyphase.Interfaces.PositivePlug pv(final m=m) "Positive plug, voltage path"
    ;
  Polyphase.Interfaces.NegativePlug nv(final m=m) "Negative plug, voltage path"
    ;
  Modelica.Blocks.Interfaces.RealOutput power(unit="W") ;
  Polyphase.Sensors.VoltageSensor voltageSensor(final m=m) ;
  Polyphase.Sensors.CurrentSensor currentSensor(final m=m)
    ;
  Modelica.Blocks.Math.Product product[m] ;
  Modelica.Blocks.Math.Sum sum(final nin=m, final k=ones(m)) ;
equation
  connect(pc, currentSensor.plug_p)
    ;
  connect(currentSensor.plug_n, nc)
    ;
  connect(voltageSensor.plug_p, pv) ;
  connect(voltageSensor.plug_n, nv) ;
  connect(voltageSensor.v, product.u1) ;
  connect(currentSensor.i, product.u2) ;
  connect(product.y, sum.u) ;
  connect(sum.y, power) 
  ;
end PowerSensor;

within Modelica.Electrical.Polyphase.Sensors;
model ReactivePowerSensor "Three-phase sensor for reactive power"
  extends Modelica.Icons.RoundSensor;
  final parameter Integer m(final min=1) = 3 "Number of phases" ;
  Interfaces.PositivePlug plug_p(final m=m) ;
  Interfaces.NegativePlug plug_n(final m=m) ;
  Modelica.Blocks.Interfaces.RealOutput reactivePower(unit="var") "Reactive power"
    ;
  Basic.PlugToPins_p plugToPins_p(final m=m)
    ;
  Basic.PlugToPins_n plugToPins_n(final m=m)
    ;
  Modelica.Electrical.Analog.Sensors.PowerSensor powerSensor1
    ;
  Modelica.Electrical.Analog.Sensors.PowerSensor powerSensor2
    ;
  Modelica.Blocks.Math.Add3 add(
    final k1=1/sqrt(3),
    final k2=1/sqrt(3),
    final k3=1/sqrt(3))        ;
  Modelica.Electrical.Analog.Sensors.PowerSensor powerSensor3
    ;
equation
  connect(plug_p, plugToPins_p.plug_p)
    ;
  connect(plugToPins_n.plug_n, plug_n)
    ;
  connect(add.y, reactivePower)
    ;
  connect(plugToPins_p.pin_p[1], powerSensor1.pc)
    ;
  connect(powerSensor1.pv, plugToPins_p.pin_p[2]) ;
  connect(plugToPins_p.pin_p[3], powerSensor1.nv) ;
  connect(plugToPins_p.pin_p[3], powerSensor2.pv) ;
  connect(plugToPins_p.pin_p[2], powerSensor2.pc)
    ;
  connect(powerSensor1.nc, plugToPins_n.pin_n[1])
    ;
  connect(powerSensor2.nc, plugToPins_n.pin_n[2])
    ;
  connect(powerSensor1.nc, powerSensor2.nv)
    ;
  connect(plugToPins_p.pin_p[3], powerSensor3.pc) ;
  connect(powerSensor3.nc, plugToPins_n.pin_n[3])
    ;
  connect(powerSensor1.nc, powerSensor3.pv)
    ;
  connect(powerSensor3.nv, plugToPins_n.pin_n[2]) ;
  connect(powerSensor2.power, add.u2) ;
  connect(powerSensor1.power, add.u1) ;
  connect(powerSensor3.power, add.u3) 
  ;
end ReactivePowerSensor;

