block Filter "PT1 + all-pass filter"
  extends Modelica.Blocks.Interfaces.SISO;
  import Modelica.Constants.pi;
  parameter SI.Frequency f=50 "Mains Frequency";
  parameter SI.Frequency fCut=2*f "Cut off frequency";
  final parameter Integer na(final min=2) = 2
    "Count of 1st order all-pass";
  final parameter SI.Frequency fa=f/tan(pi/na - atan(f/fCut)
      /(2*na)) "Characteristic frequency of all-pass filter";
  parameter Real yStart=0 "Start value of output";
  Modelica.Blocks.Continuous.FirstOrder firstOrder(
    final k=1,
    final T=1/(2*pi*fCut),
    initType=Modelica.Blocks.Types.Init.InitialOutput,
    y_start=yStart)
    ;
  Modelica.Blocks.Continuous.TransferFunction transferFunction[na](
    each final b={-1/(2*pi*fa),1},
    each final a={+1/(2*pi*fa),1},
    each initType=Modelica.Blocks.Types.Init.InitialOutput,
    each y_start=yStart)
    ;
equation
  for j in 1:na - 1 loop
    connect(transferFunction[j].y, transferFunction[j + 1].u);
  end for;
  connect(u, firstOrder.u) ;
  connect(firstOrder.y, transferFunction[1].u) ;
  connect(transferFunction[na].y, y) 
  ;
end Filter;

within Modelica.Electrical.PowerConverters.ACDC.Control;
block Signal2mPulse "Generic control of 2*m pulse rectifiers"
  import Modelica.Constants.pi;
  extends PowerConverters.Icons.Control;
  parameter Integer m(final min=1) = 3 "Number of phases" ;
  parameter Boolean useConstantFiringAngle=true
    "Use constant firing angle instead of signal input";
  parameter SI.Angle constantFiringAngle=0 "Firing angle"
    ;
  parameter Boolean useFilter=true "Enable use of filter"
    ;
  parameter SI.Frequency f=50 "Frequency";
  parameter SI.Frequency fCut=2*f
    "Cut off frequency of filter"
    ;
  parameter SI.Voltage vStart[m]=zeros(m)
    "Start voltage of filter output"
    ;
  Modelica.Blocks.Interfaces.RealInput firingAngle(unit="rad") if not
    useConstantFiringAngle "Firing angle" ;
  parameter SI.Angle firingAngleMax(
    final min=0, final max=pi) = Modelica.Constants.pi
    "Maximum firing angle";
  parameter SI.Angle firingAngleMin(
    final min=0, final max=pi) = 0
    "Minimum firing angle";
  Modelica.Blocks.Sources.Constant constantconstantFiringAngle(final k=
        constantFiringAngle) if useConstantFiringAngle ;
  Modelica.Blocks.Logical.GreaterThreshold positiveThreshold[m](threshold=
       zeros(m)) ;
  Modelica.Blocks.Logical.LessThreshold negativeThreshold[m](threshold=
        zeros(m)) ;
  Modelica.Blocks.Logical.Timer timerPositive[m] ;
  Modelica.Blocks.Logical.Timer timerNegative[m] ;
  Modelica.Blocks.Logical.Greater greaterPositive[m] ;
  Modelica.Blocks.Logical.Greater greaterNegative[m] ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_p[m] ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_n[m] ;
  Modelica.Blocks.Math.Gain gain(final k=1/pi)     ;
  Modelica.Blocks.Routing.Replicator replicator(final nout=m) ;
  Modelica.Blocks.Nonlinear.Limiter limiter(final uMax=min(firingAngleMax, pi),
      final uMin=max(firingAngleMin, 0))
                                       ;
  Modelica.Blocks.Interfaces.RealInput v[m](each unit="V") "Voltages" ;
  Filter filter[m](
    each final f=f,
    each final fCut=fCut,
    yStart=vStart) if useFilter ;
  Modelica.Blocks.Routing.RealPassThrough realPassThrough[m] if not
    useFilter "Pass through in case filter is off"
    ;
  Modelica.Blocks.Math.Gain gainPositive[m](each final k=2*f) ;
  Modelica.Blocks.Math.Gain gainNegative[m](each final k=2*f) ;
equation
  assert(firingAngleMax>firingAngleMin,
    "Signal2mPulse: firingAngleMax has to be greater than firingAngleMin");
  connect(positiveThreshold.y, timerPositive.u) ;
  connect(negativeThreshold.y, timerNegative.u) ;
  connect(greaterPositive.y, fire_p) ;
  connect(greaterNegative.y, fire_n)
    ;
  connect(gain.y, replicator.u) ;
  connect(replicator.y, greaterPositive.u2) ;
  connect(replicator.y, greaterNegative.u2)
    ;
  connect(limiter.y, gain.u) ;
  connect(firingAngle, limiter.u) ;
  connect(constantconstantFiringAngle.y, limiter.u) ;
  connect(v, filter.u) ;
  connect(filter.y, positiveThreshold.u) ;
  connect(filter.y, negativeThreshold.u) ;
  connect(realPassThrough.u, v) ;
  connect(realPassThrough.y, positiveThreshold.u) ;
  connect(realPassThrough.y, negativeThreshold.u) ;
  connect(timerPositive.y, gainPositive.u)
    ;
  connect(gainPositive.y, greaterPositive.u1)
    ;
  connect(gainNegative.y, greaterNegative.u1)
    ;
  connect(timerNegative.y, gainNegative.u)

  ;
end Signal2mPulse;

