model Polyphase2Level "Polyphase DC to AC converter"
  extends Modelica.Blocks.Icons.Block;
  extends Interfaces.Enable.Enable2m;
  parameter SI.Resistance RonTransistor=1e-05
    "Transistor closed resistance";
  parameter SI.Conductance GoffTransistor=1e-05
    "Transistor opened conductance";
  parameter SI.Voltage VkneeTransistor=0
    "Transistor threshold voltage";
  parameter SI.Resistance RonDiode=1e-05
    "Diode closed resistance";
  parameter SI.Conductance GoffDiode=1e-05
    "Diode opened conductance";
  parameter SI.Voltage VkneeDiode=0 "Diode threshold voltage";

  extends PowerConverters.Interfaces.DCAC.DCtwoPin;
  extends PowerConverters.Interfaces.DCAC.ACplug;
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort(final T=
       293.15);
  Modelica.Electrical.Polyphase.Ideal.IdealGTOThyristor transistor_p(
    final m=m,
    final Ron=fill(RonTransistor, m),
    final Goff=fill(GoffTransistor, m),
    final Vknee=fill(VkneeTransistor, m),
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Polyphase.Ideal.IdealDiode diode_p(
    final m=m,
    final Ron=fill(RonDiode, m),
    final Goff=fill(GoffDiode, m),
    final Vknee=fill(VkneeDiode, m),
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Polyphase.Basic.Star star_p(final m=m) ;
  Modelica.Electrical.Polyphase.Ideal.IdealGTOThyristor transistor_n(
    final m=m,
    final Ron=fill(RonTransistor, m),
    final Goff=fill(GoffTransistor, m),
    final Vknee=fill(VkneeTransistor, m),
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Polyphase.Ideal.IdealDiode diode_n(
    final m=m,
    final Ron=fill(RonDiode, m),
    final Goff=fill(GoffDiode, m),
    final Vknee=fill(VkneeDiode, m),
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Polyphase.Basic.Star star_n(final m=m) ;
  Modelica.Thermal.HeatTransfer.Components.ThermalCollector
    thermalCollector(final m=m) if useHeatPort
    ;
equation
  if not useHeatPort then
    LossPower = sum(transistor_p.idealGTOThyristor.LossPower) + sum(diode_n.idealDiode.LossPower)
       + sum(transistor_n.idealGTOThyristor.LossPower) + sum(diode_n.idealDiode.LossPower);
  end if;
  connect(transistor_p.plug_p, star_p.plug_p) ;
  connect(star_p.plug_p, diode_p.plug_n) ;
  connect(transistor_n.plug_n, star_n.plug_p) ;
  connect(star_n.plug_p, diode_n.plug_p) ;
  connect(transistor_p.plug_n, diode_p.plug_p) ;
  connect(transistor_n.plug_p, diode_n.plug_n) ;
  connect(star_n.pin_n, dc_n) ;
  connect(dc_p, star_p.pin_n) ;
  connect(transistor_p.plug_n, ac) ;
  connect(transistor_n.plug_p, ac) ;
  connect(heatPort, thermalCollector.port_b) ;
  connect(thermalCollector.port_a, transistor_n.heatPort) ;
  connect(diode_n.heatPort, thermalCollector.port_a) ;
  connect(transistor_p.heatPort, thermalCollector.port_a) ;
  connect(diode_p.heatPort, thermalCollector.port_a) ;
  connect(andCondition_p.y, transistor_p.fire) ;
  connect(andCondition_n.y, transistor_n.fire) 
  ;
end Polyphase2Level;

within Modelica.Electrical.PowerConverters.DCAC;
model SinglePhase2Level "Single-phase DC to AC converter"
  extends Modelica.Blocks.Icons.Block;
  parameter SI.Resistance RonTransistor=1e-05
    "Transistor closed resistance";
  parameter SI.Conductance GoffTransistor=1e-05
    "Transistor opened conductance";
  parameter SI.Voltage VkneeTransistor=0
    "Transistor threshold voltage";
  parameter SI.Resistance RonDiode=1e-05
    "Diode closed resistance";
  parameter SI.Conductance GoffDiode=1e-05
    "Diode opened conductance";
  parameter SI.Voltage VkneeDiode=0 "Diode threshold voltage";

  extends PowerConverters.Interfaces.DCAC.DCtwoPin;
  extends PowerConverters.Interfaces.DCAC.ACpin;
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort(final T=
       293.15);
  extends Interfaces.Enable.Enable2;
  Modelica.Electrical.Analog.Ideal.IdealGTOThyristor transistor_p(
    final Ron=RonTransistor,
    final Goff=GoffTransistor,
    final Vknee=VkneeTransistor,
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode_p(
    final Ron=RonDiode,
    final Goff=GoffDiode,
    final Vknee=VkneeDiode,
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Analog.Ideal.IdealGTOThyristor transistor_n(
    final Ron=RonTransistor,
    final Goff=GoffTransistor,
    final Vknee=VkneeTransistor,
    final useHeatPort=useHeatPort) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode_n(
    final Ron=RonDiode,
    final Goff=GoffDiode,
    final Vknee=VkneeDiode,
    final useHeatPort=useHeatPort) ;
equation
  if not useHeatPort then
    LossPower = transistor_p.LossPower + diode_n.LossPower + transistor_n.LossPower
       + diode_n.LossPower;
  end if;
  connect(transistor_p.p, dc_p) ;
  connect(transistor_n.n, dc_n) ;
  connect(transistor_p.p, diode_p.n) ;
  connect(transistor_p.n, diode_p.p) ;
  connect(transistor_n.p, diode_n.n) ;
  connect(transistor_n.n, diode_n.p) ;
  connect(transistor_p.n, transistor_n.p) ;
  connect(ac, transistor_p.n) ;
  connect(transistor_p.heatPort, heatPort) ;
  connect(transistor_n.heatPort, heatPort) ;
  connect(diode_p.heatPort, heatPort) ;
  connect(diode_n.heatPort, heatPort) ;
  connect(andCondition_p.y, transistor_p.fire) ;
  connect(andCondition_n.y, transistor_n.fire) 
  ;
end SinglePhase2Level;

within Modelica.Electrical.PowerConverters.DCAC.Control;
block IntersectivePWM "Intersective PWM"
  extends Modelica.Blocks.Icons.Block;
  import Modelica.Electrical.PowerConverters.Types.ReferenceType;
  constant Integer m=3 "Number of phases";
  parameter SI.Frequency f "Switching frequency";
  parameter SI.Time startTime=0 "Start time of PWM";
  parameter Real uMax "Maximum amplitude of signal";
  parameter PowerConverters.Types.ReferenceType refType=PowerConverters.Types.ReferenceType.Triangle3
    "Type of reference signal" ;
  Modelica.Blocks.Interfaces.RealInput u[2] "Reference space phasor"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_p[m] "Positive fire signal"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_n[m] "Negative fire signal"
    ;
  Modelica.Electrical.Machines.SpacePhasors.Blocks.FromSpacePhasor
    fromSpacePhasor
    ;
  Modelica.Blocks.Sources.Constant zero(k=0) ;
  Modelica.Blocks.Sources.SawTooth sawTooth[m](
    each nperiod=-1,
    each amplitude=uMax,
    each offset=-uMax/2,
    each period=1/f,
    startTime={startTime - 1.5 + (if refType == ReferenceType.Sawtooth1
         then 0 else k)/m for k in 0:m - 1}/f) if
       (refType==ReferenceType.Sawtooth1 or refType==ReferenceType.Sawtooth3)
    ;
  Modelica.Blocks.Sources.Trapezoid trapezoid[3](
    each amplitude=uMax,
    each width=0,
    each nperiod=-1,
    each offset=-uMax/2,
    each rising=0.5/f,
    each falling=0.5/f,
    each period=1/f,
    startTime={startTime - 1.25 + (if refType == ReferenceType.Triangle1
         then 0 else k)/m for k in 0:m - 1}/f) if
       (refType==ReferenceType.Triangle1 or refType==ReferenceType.Triangle3)
     ;
  Modelica.Blocks.Logical.GreaterEqual greaterEqual[m]
    ;
  Modelica.Blocks.Logical.Not negation[m]
    ;
  Modelica.Blocks.Logical.Switch switch1[m]
    ;
  Modelica.Blocks.Sources.Constant const[m](each k=-uMax) ;
  Modelica.Blocks.Sources.BooleanExpression booleanExpression(y=time >=
        startTime)
    ;
  Modelica.Blocks.Routing.BooleanReplicator booleanReplicator(nout=m)
    ;
equation
  connect(u, fromSpacePhasor.u) ;
  connect(zero.y, fromSpacePhasor.zero)
    ;
  connect(fromSpacePhasor.y, greaterEqual.u1)
    ;
  connect(greaterEqual.y, fire_p)
    ;
  connect(negation.y, fire_n)
    ;
  connect(greaterEqual.y, negation.u) ;
  connect(switch1.y, greaterEqual.u2)
    ;
  connect(sawTooth.y, switch1.u1) ;
  connect(trapezoid.y, switch1.u1) ;
  connect(const.y, switch1.u3)
    ;
  connect(booleanReplicator.y, switch1.u2) ;
  connect(booleanExpression.y, booleanReplicator.u)

  ;
end IntersectivePWM;

within Modelica.Electrical.PowerConverters.DCAC.Control;
block PWM "PulseWidthModulation"
  extends Modelica.Blocks.Icons.Block;
  constant Integer m=3 "Number of phases";
  parameter PowerConverters.Types.PWMType pwmType=PowerConverters.Types.PWMType.SVPWM
    "PWM Type" ;
  parameter SI.Frequency f "Switching frequency";
  parameter SI.Time startTime=0 "Start time of PWM";
  parameter Real uMax "Maximum amplitude of signal";
  parameter PowerConverters.Types.ReferenceType refType=PowerConverters.Types.ReferenceType.Triangle3
    "Type of reference signal" ;
  Modelica.Blocks.Interfaces.RealInput u[2] "Reference space phasor"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_p[m] "Positive fire signal"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_n[m] "Negative fire signal"
    ;
  PowerConverters.DCAC.Control.SVPWM svPWM(
    f=f,
    startTime=startTime,
    uMax=uMax) if pwmType == PowerConverters.Types.PWMType.SVPWM
    ;
  PowerConverters.DCAC.Control.IntersectivePWM intersectivePWM(
    f=f,
    startTime=startTime,
    uMax=uMax,
    refType=refType) if pwmType == PowerConverters.Types.PWMType.Intersective
    ;
equation
  connect(u, svPWM.u) ;
  connect(u, intersectivePWM.u) ;
  connect(svPWM.fire_p, fire_p) ;
  connect(intersectivePWM.fire_p, fire_p) ;
  connect(svPWM.fire_n, fire_n) ;
  connect(intersectivePWM.fire_n, fire_n) 
  ;
end PWM;

within Modelica.Electrical.PowerConverters.DCAC.Control;
block SVPWM "SpaceVector Pulse Width Modulation"
  parameter SI.Frequency f "Switching frequency";
  extends Modelica.Blocks.Interfaces.DiscreteBlock(final samplePeriod=1/f);
  import Modelica.Constants.small;
  import Modelica.Constants.eps;
  import Modelica.Constants.pi;
  import Modelica.Math.atan2;
  constant Integer m=3 "Number of phases";
  parameter Real uMax "Maximum length of space vector = half diagonal of hexagon";
  constant Boolean fire[6,m]=[true, false,false;
                              true, true, false;
                              false,true, false;
                              false,true, true;
                              false,false,true;
                              true, false,true] "Switching patterns";
  Modelica.Blocks.Interfaces.RealInput u[2] "Reference space phasor"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_p[m] "Positive fire signal"
    ;
  Modelica.Blocks.Interfaces.BooleanOutput fire_n[m] "Negative fire signal"
    ;
protected
  discrete Real uRef(start=0, fixed=true) "Length of reference vector";
  discrete SI.Angle phiRef(start=0, fixed=true) "Angle of reference vector within (-pi, +pi]";
  discrete SI.Angle phiPos(start=0, fixed=true) "Angle of reference vector within [0, 2*pi)";
  Integer ka(start=0, fixed=true), kb(start=0, fixed=true) "Switching patterns limiting the sector";
  discrete SI.Angle phiSec(start=0, fixed=true) "Angle of reference vector within sector within [0, pi/m)";
  discrete Real ta(start=0, fixed=true), tb(start=0, fixed=true), t0(start=samplePeriod, fixed=true) "Relative time spans of vectors a, b, and 0";
  discrete SI.Time T0(start=startTime, fixed=true) "Start time of switching interval";
algorithm
  when sampleTrigger then

    uRef:=min(sqrt(u[1]^2 + u[2]^2)/(2/3*uMax), cos(pi/6));

    phiRef:=if noEvent(uRef < small) then 0 else atan2(u[2], u[1]);

    phiPos:=max(phiRef + (if phiRef < -eps then 2*pi else 0), 0);

    ka:=integer(phiPos/(pi/m));
    kb:=if noEvent(ka >= 5) then 0 else ka + 1;

    phiSec:=phiPos - ka*pi/m;



    tb:=min(uRef*sin(phiSec)/sin(pi/m), 1);
    ta:=min(uRef*cos(phiSec) - tb*cos(pi/m), 1);
    t0:=max(1 - ta - tb, 0);

    T0:=time;
  end when;
equation

  if time<startTime then
    fire_p= fill(true, m);
  elseif (time - T0)/samplePeriod < (t0/4) then
    fire_p= fill(false, m);
  elseif (time - T0)/samplePeriod < (t0/4 + ta/2) then
    fire_p= fire[ka + 1, :];
  elseif (time - T0)/samplePeriod < (t0/4 + ta/2 + tb/2) then
    fire_p= fire[kb + 1, :];
  elseif (time - T0)/samplePeriod < (t0/4 + ta/2 + tb/2 + t0/2) then
    fire_p= fill(true, m);
  elseif (time - T0)/samplePeriod < (t0/4 + ta/2 + tb/2 + t0/2 + tb/2) then
    fire_p= fire[kb + 1, :];
  elseif (time - T0)/samplePeriod < (t0/4 + ta/2 + tb/2 + t0/2 + tb/2 + ta/2) then
    fire_p= fire[ka + 1, :];
  else
    fire_p= fill(false, m);
  end if;
  fire_n= not fire_p
  ;
end SVPWM;

within Modelica.Electrical.PowerConverters.DCDC;
model ChopperStepDown "Step down chopper"
  import Modelica.Constants.pi;
  extends Icons.Converter;
  parameter SI.Resistance RonTransistor=1e-05
    "Transistor closed resistance";
  parameter SI.Conductance GoffTransistor=1e-05
    "Transistor opened conductance";
  parameter SI.Voltage VkneeTransistor=0
    "Transistor threshold voltage";
  parameter SI.Resistance RonDiode(final min=0) = 1e-05
    "Closed diode resistance";
  parameter SI.Conductance GoffDiode(final min=0) = 1e-05
    "Opened diode conductance";
  parameter SI.Voltage VkneeDiode(final min=0) = 0
    "Diode forward threshold voltage";
  extends PowerConverters.Interfaces.DCDC.DCtwoPin1;
  extends PowerConverters.Interfaces.DCDC.DCtwoPin2;
  extends Modelica.Electrical.Analog.Interfaces.ConditionalHeatPort(final T=
       293.15);
  extends Interfaces.Enable.Enable1;
  Modelica.Electrical.Analog.Ideal.IdealGTOThyristor transistor(
    useHeatPort=useHeatPort,
    Ron=RonTransistor,
    Goff=GoffTransistor,
    Vknee=VkneeTransistor) "Switching transistor" ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode(
    Ron=RonDiode,
    Goff=GoffDiode,
    Vknee=VkneeDiode,
    useHeatPort=useHeatPort) "Free wheeling diode" ;
equation
  if not useHeatPort then
    LossPower = diode.LossPower + transistor.LossPower;
  end if;
  connect(diode.n, transistor.n) ;
  connect(transistor.n, dc_p2) ;
  connect(transistor.heatPort, heatPort) ;
  connect(diode.heatPort, heatPort) ;
  connect(dc_p1, transistor.p) ;
  connect(dc_n1, diode.p) ;
  connect(dc_n1, dc_n2) ;
  connect(andCondition_p.y, transistor.fire) 
  ;
end ChopperStepDown;

