within Modelica.Electrical.PowerConverters.Examples.DCAC.ExampleTemplates;
partial model SinglePhaseTwoLevel
  "Single-phase two level inverter including control"
  extends Icons.ExampleTemplate;
  parameter SI.Frequency f=1000 "Switching frequency";
  Modelica.Electrical.Analog.Sources.ConstantVoltage constantVoltage_n(
      V=50) ;
  PowerConverters.DCAC.SinglePhase2Level inverter(useHeatPort=false)
    ;
  Modelica.Electrical.Analog.Sensors.CurrentSensor currentSensor
    ;
  Modelica.Electrical.Analog.Sensors.VoltageSensor voltageSensor
    ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  PowerConverters.DCDC.Control.SignalPWM signalPWM(useConstantDutyCycle=false,
      f=f) ;
  Modelica.Electrical.Analog.Sources.ConstantVoltage constantVoltage_p(
      V=50) ;
  Modelica.Blocks.Sources.Sine sine(f=50) ;
  Modelica.Blocks.Math.Harmonic fundamentalWaveVoltage(f=f, k=1)
    ;
  Modelica.Blocks.Math.Harmonic fundamentalWaveCurrent(f=f, k=1)
    ;
equation
  connect(voltageSensor.n, currentSensor.p) ;
  connect(signalPWM.fire, inverter.fire_p) ;
  connect(constantVoltage_p.n, constantVoltage_n.p) ;
  connect(constantVoltage_p.p, inverter.dc_p) ;
  connect(constantVoltage_n.n, inverter.dc_n) ;
  connect(ground.p, constantVoltage_p.n) ;
  connect(currentSensor.n, ground.p) ;
  connect(voltageSensor.p, inverter.ac) ;
  connect(sine.y, signalPWM.dutyCycle) ;
  connect(inverter.fire_n, signalPWM.notFire) ;
  connect(currentSensor.i, fundamentalWaveCurrent.u) ;
  connect(voltageSensor.v, fundamentalWaveVoltage.u) 
  ;
end SinglePhaseTwoLevel;

within Modelica.Electrical.PowerConverters.Examples.DCAC.PolyphaseTwoLevel;
model PolyphaseTwoLevel_R "Polyphase DC to AC converter with R load"
  extends Modelica.Icons.Example;
  parameter Integer m=3 "Number of phases" ;
  parameter SI.Frequency f=1000 "Switching frequency";
  parameter SI.Frequency f1=50
    "Fundamental wave AC frequency";
  parameter SI.Resistance R=100 "Resistance";
  Modelica.Electrical.Analog.Sources.ConstantVoltage constantVoltage_n(
      V=50) ;
  PowerConverters.DCAC.Polyphase2Level inverter(useHeatPort=false, m=m)
    ;
  Modelica.Electrical.Polyphase.Sensors.CurrentSensor currentSensor(m=
        m) ;
  Modelica.Electrical.Polyphase.Sensors.VoltageSensor voltageSensor(m=
        m) ;
  Modelica.Electrical.Analog.Basic.Ground ground ;
  PowerConverters.DCDC.Control.SignalPWM signalPWM[m](each useConstantDutyCycle
      =false, each f=f) ;
  Modelica.Electrical.Analog.Sources.ConstantVoltage constantVoltage_p(
      V=50) ;
  Modelica.Blocks.Sources.Sine sine[m](
    phase=-
        Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m),
    startTime=zeros(m),
