  SI.Current iAC=pin_pAC.i "AC current";
  SI.ActivePower pAC=vAC*iAC "AC power";
  SI.Voltage vDC=pin_pDC.v - pin_nDC.v "DC voltage";
  SI.Current iDC=pin_pDC.i "DC current";
  SI.Power pDC=vDC*iDC "DC power";
  Modelica.Electrical.Analog.Interfaces.PositivePin pin_pAC ;
  Modelica.Electrical.Analog.Interfaces.NegativePin pin_nAC ;
  Modelica.Electrical.Analog.Interfaces.PositivePin pin_pDC ;
  Modelica.Electrical.Analog.Interfaces.NegativePin pin_nDC ;
  Modelica.Electrical.Analog.Ideal.IdealDiode idealDiode1(Vknee=0) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode idealDiode2(Vknee=0) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode idealDiode3(Vknee=0) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode idealDiode4(Vknee=0) ;
equation
