model PumpingSystem "Model of a pumping system for drinking water"
  extends Modelica.Icons.Example;
  replaceable package Medium = Modelica.Media.Water.StandardWaterOnePhase
    constrainedby Modelica.Media.Interfaces.PartialMedium;


  Modelica.Fluid.Sources.FixedBoundary source(
    nPorts = 1,
    use_T=true,
    T=Modelica.Units.Conversions.from_degC(20),
    p=system.p_ambient,
    redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Pipes.StaticPipe pipe(
    allowFlowReversal=true,
    length=100,
    height_ab=50,
    diameter=0.3,
    redeclare package Medium = Medium)
    ;
  Machines.PrescribedPump pumps(
    checkValve=true,
    checkValveHomotopy = Modelica.Fluid.Types.CheckValveHomotopyType.Closed,
    N_nominal=1200,
    redeclare function flowCharacteristic =
        Modelica.Fluid.Machines.BaseClasses.PumpCharacteristics.quadraticFlow (
          V_flow_nominal={0,0.25,0.5}, head_nominal={100,60,0}),
    use_N_in=true,
    nParallel=1,
    energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    V(displayUnit="l") = 0.05,
    massDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial,
    redeclare package Medium = Medium,
    p_b_start=600000,
    T_start=system.T_start)
    ;
  Modelica.Fluid.Vessels.OpenTank reservoir(
    T_start=Modelica.Units.Conversions.from_degC(20),
    use_portsData=true,
    crossArea=50,
    level_start=2.2,
    height=3,
    nPorts=3,
    portsData={Modelica.Fluid.Vessels.BaseClasses.VesselPortsData(diameter=0.3),
        Modelica.Fluid.Vessels.BaseClasses.VesselPortsData(diameter=0.3),
        Modelica.Fluid.Vessels.BaseClasses.VesselPortsData(diameter=0.01)},
    redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Valves.ValveLinear userValve(
    allowFlowReversal=false,
    dp_nominal=200000,
    m_flow_nominal=400,
    redeclare package Medium = Medium)
    ;
  Modelica.Fluid.Sources.FixedBoundary sink(
    p=system.p_ambient,
    T=system.T_ambient,
    nPorts=2,
    redeclare package Medium = Medium)
    ;
  Modelica.Blocks.Sources.Step valveOpening(startTime=200, offset=1e-6)
    ;
  Modelica.Blocks.Sources.Constant RelativePressureSetPoint(k=2e4)
    ;
  Modelica.Blocks.Logical.OnOffController controller(bandwidth=4000,
      pre_y_start=false)
                        ;
  Modelica.Blocks.Logical.TriggeredTrapezoid PumpRPMGenerator(
    rising=3,
    falling=3,
    amplitude=1200,
    offset=0.001) ;
  Modelica.Fluid.Sensors.RelativePressure reservoirPressure(redeclare package
      Medium = Medium)
    ;
  Modelica.Blocks.Continuous.FirstOrder PT1(
    T=2,
    initType=Modelica.Blocks.Types.Init.InitialState,
    y_start=0)
    ;
  inner Modelica.Fluid.System system(energyDynamics=Modelica.Fluid.Types.Dynamics.FixedInitial)
                                   ;
equation
  connect(userValve.port_b, sink.ports[1]) ;
  connect(source.ports[1], pumps.port_a) ;
  connect(valveOpening.y, userValve.opening) ;
  connect(RelativePressureSetPoint.y, controller.reference)
                                                    ;
  connect(controller.y, PumpRPMGenerator.u)
    ;
  connect(reservoirPressure.p_rel, controller.u) ;
  connect(reservoirPressure.port_b, sink.ports[2]) ;
  connect(PumpRPMGenerator.y, PT1.u)
    ;
  connect(PT1.y, pumps.N_in) ;
  connect(pipe.port_a, pumps.port_b) ;
  connect(reservoir.ports[1], pipe.port_b) ;
  connect(reservoir.ports[3], reservoirPressure.port_a) ;
  connect(reservoir.ports[2], userValve.port_a) 
  ;
end PumpingSystem;

within Modelica.Magnetic.FluxTubes.BaseClasses;
partial model FixedShape "Base class for flux tubes with fixed shape during simulation; linear or non-linear material characteristics"
  extends Interfaces.TwoPort;
  parameter Boolean nonLinearPermeability=true
    "= true, if non-linear rel. permeability is used, otherwise constant rel. permeability"
    ;
  parameter SI.RelativePermeability mu_rConst=1
    "Constant relative permeability; used if nonLinearPermeability = false"
    ;
  parameter FluxTubes.Material.SoftMagnetic.BaseData material=
      Material.SoftMagnetic.BaseData()
    "Ferromagnetic material characteristics; used if nonLinearPermeability = true"
    ;
  SI.Reluctance R_m "Magnetic reluctance";
  SI.Permeance G_m "Magnetic permeance";
  SI.MagneticFluxDensity B "Magnetic flux density";
  SI.CrossSection A "Cross-sectional area penetrated by magnetic flux";
  SI.MagneticFieldStrength H "Magnetic field strength";
  SI.RelativePermeability mu_r "Relative magnetic permeability";
protected
  Real B_N "Absolute value of normalized B";
equation
  B_N = abs(B/material.B_myMax);
  mu_r = if nonLinearPermeability then
    1 + (material.mu_i - 1 + material.c_a*B_N)/(1 + material.c_b*B_N + B_N^material.n) else mu_rConst;
  R_m = 1/G_m;
  V_m = Phi*R_m;
  B = Phi/A;
  H = B/(mu_0*mu_r)
  ;
end FixedShape;

within Modelica.Magnetic.FluxTubes.BaseClasses;
partial model Force "Base class for flux tubes with reluctance force generation; constant permeability"
  extends Interfaces.TwoPort;
  parameter Boolean useSupport=false
    "= true, if support flange enabled, otherwise implicitly grounded"
    ;
  parameter SI.RelativePermeability mu_r(start=1)
    "Relative magnetic permeability";
  SI.Force F_m "Reluctance force";
  SI.Length s=flange.s - s_support
    "Distance between flange and support";
  SI.Reluctance R_m "Magnetic reluctance";
  SI.Permeance G_m "Magnetic permeance";
  SI.Permeability dGmBydx
    "Derivative of permeance with respect to armature position";
  parameter Integer dlBydx=1
    "Derivative of flux tube's varying dimension with respect to armature position; set to +1 or -1";
  Modelica.Mechanics.Translational.Interfaces.Flange_b flange
    "Generated reluctance force at armature position" ;
  Modelica.Mechanics.Translational.Interfaces.Support support(s=s_support,
      f=-flange.f) if useSupport "Support/housing of component" ;
protected
  SI.Length s_support "Absolute position of support flange";
equation
  V_m = Phi*R_m;
  R_m = 1/G_m;
  F_m = 0.5*V_m^2*dGmBydx;
  if not useSupport then
    s_support = 0;
  end if;
  flange.f = -F_m
  ;
end Force;

within Modelica.Magnetic.FluxTubes.BaseClasses;
partial model Generic "Partial Tellinen hysteresis model"
  extends Interfaces.TwoPort;
  extends Modelica.Magnetic.FluxTubes.Icons.Reluctance;

  parameter SI.Length l=0.1 "Length in direction of flux" ;
  parameter SI.Area A=1e-4 "Area of cross section" ;
  final parameter SI.Volume V = A * l "Volume of FluxTube"
  ;
end Generic;

within Modelica.Magnetic.FluxTubes.BaseClasses;
partial model GenericHysteresis "Partial hysteresis model"
  extends BaseClasses.Generic;
  extends Interfaces.ConditionalHeatPort(final T=293.15);
  parameter Boolean includeEddyCurrents = false
    "= true, if eddy current losses are enabled"
  ;
  parameter SI.Conductivity sigma=10e6 "Conductivity of core material" ;
  parameter SI.Length d = 0.5e-3 "Thickness of lamination" ;
  output SI.MagneticFieldStrength H(start=0) "Magnetic field strength";
  output SI.MagneticFieldStrength Hstat
    "Static (ferromagnetic) portion of the magnetic field strength";
  output SI.MagneticFieldStrength Heddy
    "Dynamic (eddy currents) portion of the magnetic field strength";
  output SI.MagneticFluxDensity B "Magnetic flux density";
  output Real MagRel(final quantity="Relative magnetization", final unit="1", start=0, min=-1, max=1)
    "Relative magnetization at initialization (-1..1)";
  output SI.Power LossPowerStat "Ferromagnetic (static) hysteresis losses";
  output SI.Power LossPowerEddy
    "Eddy current losses (dynamic hysteresis losses)";

  Real derHstat(start=0, unit="A/(m.s)")=der(Hstat);
protected
  final parameter Real eddyCurrentFactor(final unit="S.m") = (sigma * d^2)/12;
equation
  der(MagRel)=0;
  H = Hstat + Heddy;
  H = V_m/l;
  Phi = B*A;
  Heddy = if includeEddyCurrents then eddyCurrentFactor* der(B)  else 0;
  LossPowerStat = Hstat * der(B) * V;
  LossPowerEddy = Heddy * der(B) * V;
  LossPower = LossPowerStat + LossPowerEddy
  ;
end GenericHysteresis;

within Modelica.Magnetic.FluxTubes.BaseClasses;
partial model GenericHysteresisTellinen "Partial Tellinen hysteresis model"
  extends BaseClasses.GenericHysteresis;

  output Boolean asc(start=true) "True when der(Hstat)>0";
protected
  SI.MagneticFluxDensity hystR "Rising branch of limiting hysteresis loop";
  SI.MagneticFluxDensity hystF "Falling branch of limiting hysteresis loop";
  SI.MagneticFluxDensity diffHyst
    "Distance between rising and falling limiting hysteresis branch at the current operating point";
  Real dHyst(final quantity="MagneticFluxDensitySlope", final unit="T/s")
    "Slope of the Rising (when der(H)>0) or Falling (when der(H)<0) limiting hysteresis branch at the current operating point";
  Real k;
  parameter Real mu0(final unit="N/A2") = mu_0;
initial equation
  B = (hystR+hystF)/2 + MagRel*diffHyst/2;
equation
  asc = der(Hstat) > 0;
  der(B) = k * dHyst + mu0 * der(Hstat);
  diffHyst = hystF - hystR;
  if initial() then
    k = 0.01;
    dHyst = 0;
  elseif asc then
    dHyst = der(hystR-mu0*Hstat);
    k = max(0.01,(hystF - B)/diffHyst);
  else
    dHyst = der(hystF-mu0*Hstat);
    k = max(0.01, (B - hystR)/diffHyst);
  end if
  ;
end GenericHysteresisTellinen;

