within Modelica.Magnetic.FluxTubes.Examples.Hysteresis;
model ThreePhaseTransformerWithRectifier
  "Three-phase transformer (including hysteresis effect) with rectifier"
  extends Modelica.Icons.Example;
  Modelica.Electrical.Analog.Basic.Ground ground1 ;
  Modelica.Electrical.Analog.Basic.Ground ground2 ;
  Modelica.Electrical.Analog.Sources.SineVoltage vSource1(
    offset=0,
    f=50,
    V=50) ;
  Components.Transformer3PhaseYyWithHysteresis transformer(
    EddyCurrents=true,
    N1=200,
    N2=10,
    mat=FluxTubes.Material.HysteresisEverettParameter.M330_50A(),
    sigma=2.2e6,
    HFixed={true,true,true},
    MagRelFixed={true,true,false},
    I1Fixed={true,true,true},
    I2Fixed={true,false,false},
    useHeatPort=false,
    MagRelStart={-0.4,0.8,-0.4},
    l1=0.2,
    l2=0.15,
    a=0.04,
    b=0.04,
    t=0.0005) ;
  Modelica.Electrical.Analog.Sources.SineVoltage vSource2(
    offset=0,
    f=vSource1.f,
    V=50,
    phase=4.1887902047864) ;
  Modelica.Electrical.Analog.Sources.SineVoltage vSource3(
    offset=0,
    f=vSource1.f,
    V=50,
    phase=2.0943951023932) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor1(R=0) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor2(R=resistor1.R) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor3(R=resistor1.R) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode1(Vknee=0.7) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode2(Vknee=0.7) ;
  Modelica.Electrical.Analog.Basic.Resistor resistorL(R=5) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode3(Vknee=0.7) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode4(Vknee=0.7) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode5(Vknee=0.7) ;
  Modelica.Electrical.Analog.Ideal.IdealDiode diode6(Vknee=0.7) ;
  Modelica.Electrical.Analog.Basic.Capacitor capacitor1(C=1e-6, v(fixed=
          true)) ;
  Modelica.Electrical.Analog.Basic.Inductor inductor1(L=1e-3) ;
  Modelica.Electrical.Analog.Basic.Inductor inductor2(L=1e-3)
    ;
  Modelica.Electrical.Analog.Basic.Inductor inductor3(L=1e-3)
    ;
  Modelica.Electrical.Analog.Basic.Capacitor capacitor2(C=1e-6, v(fixed=
          true)) ;
  Modelica.Blocks.Sources.RealExpression rExp1(y=transformer.LossPowerStat) ;
  Modelica.Blocks.Sources.RealExpression rExp2(y=transformer.LossPowerEddy) ;
  Modelica.Blocks.Sources.RealExpression rExp3(y=transformer.LossPowerWinding) ;
  Modelica.Blocks.Continuous.Filter pdissStatAvg(f_cut=10)
    "Approx. average static hysteresis losses"
    ;
  Modelica.Blocks.Continuous.Filter pdissEddyAvg(f_cut=10)
    "Approx. average eddy current losses"
    ;
  Modelica.Blocks.Continuous.Filter pdissCopAvg(f_cut=10)
    "Approx. average copper losses"
    ;
initial equation
  transformer.core1.derHstat = 0.0;
  transformer.core2.derHstat = 0.0;
  transformer.core3.derHstat = 0.0;
equation
  connect(vSource1.n, ground1.p) ;
  connect(vSource2.n, ground1.p) ;
  connect(vSource3.n, ground1.p) ;
  connect(resistor1.n, transformer.p1) ;
  connect(resistor1.p, vSource1.p) ;
  connect(resistor2.n, transformer.p2) ;
  connect(resistor2.p, vSource2.p) ;
  connect(vSource3.p, resistor3.p) ;
  connect(resistor3.n, transformer.p3) ;
  connect(diode2.n, diode1.p) ;
  connect(diode4.n, diode3.p) ;
  connect(diode6.n, diode5.p) ;
  connect(diode2.p, diode4.p) ;
  connect(diode4.p, diode6.p) ;
  connect(diode1.n, diode3.n) ;
  connect(diode3.n, diode5.n) ;
  connect(diode5.n, capacitor1.p) ;
  connect(resistorL.p, capacitor1.p) ;
  connect(transformer.n1, inductor1.p) ;
  connect(transformer.n2, inductor2.p) ;
  connect(inductor2.n, diode3.p) ;
  connect(inductor3.p, transformer.n3) ;
  connect(inductor3.n, diode6.n) ;
  connect(capacitor2.n, diode6.p) ;
  connect(capacitor2.p, capacitor1.n) ;
  connect(inductor1.n, diode1.p) ;
  connect(resistorL.n, capacitor2.n) ;
  connect(transformer.starPoint1, ground1.p) ;
  connect(transformer.starPoint2, ground2.p) ;
  connect(ground2.p, capacitor2.p) ;
  connect(rExp3.y,pdissCopAvg. u) ;
  connect(rExp2.y,pdissEddyAvg. u) ;
  connect(rExp1.y,pdissStatAvg. u) 
  ;
end ThreePhaseTransformerWithRectifier;

within Modelica.Magnetic.FluxTubes.Examples.Hysteresis.Components;
model Transformer1PhaseWithHysteresis
  "Single-phase transformer with ferromagnetic core and hysteresis"
  Modelica.Electrical.Analog.Interfaces.NegativePin n1 "Negative pin of primary winding" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin p1 "Positive pin of primary winding" ;
  Modelica.Electrical.Analog.Interfaces.NegativePin n2 "Negative pin of secondary winding" ;
  Modelica.Electrical.Analog.Interfaces.PositivePin p2 "Positive pin of secondary winding" ;
  Modelica.Thermal.HeatTransfer.Sources.PrescribedTemperature tempSource ;

  parameter Integer N1=10 "Primary turns"
    ;
  parameter SI.Length L1(displayUnit="mm") = 1.2*2*(a+b)
    "Mean primary turn length"
    ;
  parameter SI.Length d1(displayUnit="mm") = 0.5e-3
    "Wire diameter of primary turns"
    ;
  parameter SI.Resistivity rho1 = 1.678e-8
    "Resistivity of primary winding (at 20degC)"
    ;
  parameter SI.LinearTemperatureCoefficient alpha1 = 0
    "Temperature coefficient of primary turns" ;

  parameter Integer N2=10 "Secondary turns"
    ;
  parameter SI.Length L2(displayUnit="mm") = L1
    "Mean secondary turn length"
    ;
  parameter SI.Length d2(displayUnit="mm") = d1
    "Wire diameter of secondary turns"
    ;
  parameter SI.Resistivity rho2 = rho1
    "Resistivity of secondary winding (at 20degC)"
    ;
  parameter SI.LinearTemperatureCoefficient alpha2 = alpha1
    "Temperature coefficient of secondary turns" ;
  parameter SI.Length l1(displayUnit="mm") = 40e-3
    "Mean Length l1 of core" ;
  parameter SI.Length l2(displayUnit="mm") = 60e-3
    "Mean Length l2 of core" ;
  parameter SI.Length a(displayUnit="mm") = 15e-3 "Height of core" ;
  parameter SI.Length b(displayUnit="mm") = 10e-3 "Width of core" ;

  parameter FluxTubes.Material.HysteresisEverettParameter.BaseData mat=
      FluxTubes.Material.HysteresisEverettParameter.BaseData()
    "Parameter set of ferromagnetic Hysteresis" ;
  output SI.Voltage v1 "Primary voltage drop";
  output SI.Voltage v2 "Secondary voltage drop";
  output SI.Resistance R1 "Primary resistance of Winding";
  output SI.Resistance R2 "Secondary resistance of Winding";
  output SI.Current i1 "Primary current";
  output SI.Current i2 "Secondary current";
  output SI.MagneticFluxDensity B "Magnetic Flux Density of Core";
  output SI.MagneticFieldStrength Hstat
    "Ferromagnetic portion of magnetic field strength";
  output SI.MagneticFieldStrength Heddy
    "Eddy current portion of magnetic field strength";
  output SI.MagneticFieldStrength H
    "Total magnetic field strength of core";

  parameter Real MagRelStart=0 "Initial magnetization of Core (-1..1)"
    ;
  parameter Boolean MagRelFixed = false "Fixed" ;
  parameter SI.MagneticFieldStrength HStart=0
    "Initial magnetic field strength of Core"
    ;
  parameter Boolean HFixed = false "Fixed"
    ;
  parameter SI.ElectricCurrent I1Start=0
    "Initial primary current through winding" ;
  parameter Boolean I1Fixed = false "Fixed" ;
  output SI.Power LossPowerWinding "Winding losses";
  output SI.Power LossPowerStat "Ferromagnetic hysteresis losses";
  output SI.Power LossPowerEddy "Eddy current losses";
  extends Interfaces.ConditionalHeatPort;
  parameter Boolean EddyCurrents = false "Enable eddy currents"
    ;
  parameter SI.Conductivity sigma = mat.sigma
    "Conductivity of core material" ;
  parameter SI.Length t(displayUnit="mm") = 0.5e-3
    "Thickness of lamination" ;
  parameter SI.Length L_l1=10e-3 "Length of leakage of primary Winding" ;
  parameter SI.Area A_l1=10e-6
    "Cross section of leakage of primary Winding" ;
  parameter Real mu_rel1=1
    "Constant relative permeability of primary leakage (>0 required)" ;
  parameter SI.Length L_l2=10e-3
    "Length of leakage of secondary Winding" ;
  parameter SI.Area A_l2=10e-6
    "Cross section of leakage of secondary Winding" ;
  parameter Real mu_rel2=1
    "Constant relative permeability of secondary leakage (>0 required)" ;
protected
  Basic.Ground ground
    ;
  Basic.ElectroMagneticConverterWithLeakageInductance winding1(
    N=N1,
    L=L_l1,
    A=A_l1,
    mu_rel=mu_rel1,
    i(start=I1Start, fixed=I1Fixed)) ;
  Basic.ElectroMagneticConverterWithLeakageInductance winding2(
    N=N2,
    L=L_l2,
    mu_rel=mu_rel2,
    A=A_l2) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor1(
    R=rho1*N1*L1/(pi/4*d1^2),
    useHeatPort=true,
    alpha=alpha1,
    T_ref=293.15) ;
  Modelica.Electrical.Analog.Basic.Resistor resistor2(
    R=rho2*N2*L2/(pi/4*d2^2),
    useHeatPort=true,
    alpha=alpha2,
    T_ref=293.15) ;
public
  Shapes.HysteresisAndMagnets.GenericHystTellinenEverett core(
    mat=mat,
    l=2*(l1 + l2),
    A=a*b,
    includeEddyCurrents=EddyCurrents,
    sigma=sigma,
    d=t,
    H(start=HStart, fixed=HFixed),
    MagRel(start=MagRelStart, fixed=MagRelFixed))
    ;
equation
  v1 =p1.v - n1.v;
  i1 =resistor1.i;
  R1 =resistor1.R_actual;
  v2 =p2.v - n2.v;
  i2 =resistor2.i;
  R2 =resistor2.R_actual;
  B =core.B;
  Hstat =core.Hstat;
  Heddy =core.Heddy;
  H =core.H;

  tempSource.T = if useHeatPort then T_heatPort else T;
  LossPowerWinding =resistor1.LossPower + resistor2.LossPower;

  LossPowerStat =core.LossPowerStat;
  LossPowerEddy =core.LossPowerEddy;
  LossPower = LossPowerWinding + LossPowerEddy + LossPowerStat;
  connect(winding1.port_n, ground.port) ;
  connect(resistor1.n, winding1.p) ;
  connect(resistor1.p, p1) ;
  connect(resistor2.n, p2) ;
  connect(winding1.n, n1) ;
  connect(tempSource.port, resistor1.heatPort) ;
  connect(resistor2.heatPort, tempSource.port) ;
  connect(winding2.port_n, ground.port) ;
  connect(winding2.n, resistor2.p) ;
  connect(n2, winding2.p) ;
  connect(core.port_p, winding1.port_p) ;
  connect(core.port_n, winding2.port_p) 
  ;
end Transformer1PhaseWithHysteresis;

within Modelica.Magnetic.FluxTubes.Examples.MovingCoilActuator;
model ArmatureStroke
  "Armature stroke of both moving coil actuator models after a voltage step at time t=0"
  extends Modelica.Icons.Example;
  Modelica.Electrical.Analog.Basic.Ground pmGround ;
  Modelica.Electrical.Analog.Sources.StepVoltage pmSource(startTime=0, V=
        pmActuator.R*1.5) "Steady state current 1.5A" ;
  FluxTubes.Examples.MovingCoilActuator.Components.PermeanceActuator pmActuator(
    material=Material.HardMagnetic.PlasticNdFeB(),
    x(start=pmActuator.x_min, fixed=true),
    armature(v(fixed=true)),
    coil(i(fixed=true)))
    "Moving coil actuator described with permeance model" ;
  Modelica.Mechanics.Translational.Components.Mass pmLoad(m=0.05)
    "Load to be moved in addition to the armature mass" ;
  Modelica.Electrical.Analog.Basic.Ground cGround ;
  Modelica.Electrical.Analog.Sources.StepVoltage cSource(startTime=0, V=
        cActuator.R*1.5) "Steady state current 1.5A" ;
  FluxTubes.Examples.MovingCoilActuator.Components.ConstantActuator cActuator(
    x(start=cActuator.x_min, fixed=true),
    armature(v(fixed=true)),
    l(i(start=0, fixed=true)))
    "Moving coil actuator described with converter constant" ;
  Modelica.Mechanics.Translational.Components.Mass cLoad(m=0.05)
    "Load to be moved in addition to the armature mass" ;
equation
  connect(pmLoad.flange_a, pmActuator.flange)
    ;
  connect(cGround.p, cSource.n)
    ;
  connect(cLoad.flange_a, cActuator.flange)
    ;
  connect(cSource.p, cActuator.p) ;
  connect(cSource.n, cActuator.n) ;
  connect(pmSource.n, pmGround.p)
    ;
  connect(pmSource.n, pmActuator.n) ;
  connect(pmSource.p, pmActuator.p) 
  ;
end ArmatureStroke;

