  FluxTubes.Examples.MovingCoilActuator.Components.PermeanceActuator actuator(x(start=0),
      material=Material.HardMagnetic.PlasticNdFeB()) ;
  Modelica.Electrical.Analog.Sources.ConstantCurrent source(I=3)
    ;
