  connect(permanentMagnet.support, airGap.support) ;
  connect(permanentMagnet.heatPort, internalThermalPort.heatPortPermanentMagnet)
    ;
  connect(permanentMagnet.flange, inertiaRotor.flange_b) ;
  connect(airGap.port_rp, rotorCage.port_n) ;
  connect(short.port_n, airGap.port_rp) ;
  connect(short.port_p, permanentMagnet.port_n) ;
  connect(rotorCage.port_p, permanentMagnet.port_n) ;
  connect(rotorCage.heatPortWinding, internalThermalPort.heatPortRotorWinding)

  ;
