  extends Modelica.Icons.RoundSensor;
  SI.AngularVelocity omega;
  FluxTubes.Interfaces.PositiveMagneticPort port "Quasi-static magnetic port" ;
equation
  omega = der(port.reference.gamma);
  port.Phi = Complex(0)
  ;
end AbsoluteSensor;

within Modelica.Magnetic.QuasiStatic.FluxTubes.Interfaces;
connector MagneticPort "Quasi-static magnetic port"
  SI.ComplexMagneticPotential V_m
  "Complex magnetic potential at the port";
  flow SI.ComplexMagneticFlux Phi
  "Complex magnetic flux flowing into the port"
  ;
end MagneticPort;

within Modelica.Magnetic.QuasiStatic.FluxTubes.Interfaces;
connector NegativeMagneticPort "Negative quasi-static magnetic port"
  extends Magnetic.QuasiStatic.FundamentalWave.Interfaces.MagneticPort;
  Modelica.Electrical.QuasiStatic.Types.Reference reference "Reference"
  ;
end NegativeMagneticPort;

within Modelica.Magnetic.QuasiStatic.FluxTubes.Interfaces;
connector PositiveMagneticPort "Positive quasi-static magnetic port"
  extends Magnetic.QuasiStatic.FundamentalWave.Interfaces.MagneticPort;
  Modelica.Electrical.QuasiStatic.Types.Reference reference "Reference"
  ;
end PositiveMagneticPort;

within Modelica.Magnetic.QuasiStatic.FluxTubes.Interfaces;
partial model RelativeSensor "Partial magnetic voltage or flux sensor"
  extends Modelica.Icons.RoundSensor;
  extends TwoPort;
  Modelica.ComplexBlocks.Interfaces.ComplexOutput y 
  ;
end RelativeSensor;

within Modelica.Magnetic.QuasiStatic.FluxTubes.Interfaces;
partial model Source "Partial magnetic voltage or flux source"
  FluxTubes.Interfaces.PositiveMagneticPort port_p "Positive magnetic port" ;
  FluxTubes.Interfaces.NegativeMagneticPort port_n "Negative magnetic port" ;
  SI.AngularVelocity omega;
  SI.Angle gamma(start=0) = port_p.reference.gamma;
equation
  Connections.root(port_p.reference);
  Connections.branch(port_p.reference, port_n.reference);
  port_p.reference.gamma = port_n.reference.gamma;
  omega = der(port_p.reference.gamma)
  ;
end Source;

within Modelica.Magnetic.QuasiStatic.FluxTubes.Interfaces;
partial model TwoPort "Two magnetic ports for textual modeling"
  extends TwoPortElementary;
equation
  Complex(0) = port_p.Phi + port_n.Phi
  ;
end TwoPort;

within Modelica.Magnetic.QuasiStatic.FluxTubes.Interfaces;
partial model TwoPortElementary "Two magnetic ports for graphical modeling"
  FluxTubes.Interfaces.PositiveMagneticPort port_p "Positive quasi-static magnetic port" ;
  FluxTubes.Interfaces.NegativeMagneticPort port_n "Negative quasi-static magnetic port" ;
  SI.ComplexMagneticPotentialDifference V_m
  "Magnetic potential difference of both ports";
  SI.MagneticPotentialDifference abs_V_m = Modelica.ComplexMath.abs(V_m)
  "Magnitude of complex magnetic potential difference";
  SI.Angle arg_V_m=Modelica.ComplexMath.arg(V_m)
  "Argument of complex magnetic potential difference";
  SI.ComplexMagneticFlux Phi(re(start=0),im(start=0))
  "Magnetic flux from port_p to port_n";
  SI.MagneticFlux abs_Phi=
      Modelica.ComplexMath.abs(Phi) "Magnitude of complex magnetic flux";
  SI.Angle arg_Phi=Modelica.ComplexMath.arg(Phi)
  "Argument of complex magnetic flux";
  SI.AngularVelocity omega;
equation
  Connections.branch(port_p.reference, port_n.reference);
  port_p.reference.gamma = port_n.reference.gamma;
  omega = der(port_p.reference.gamma);
  V_m = port_p.V_m - port_n.V_m;
  Phi = port_p.Phi
  ;
end TwoPortElementary;

