within Modelica.Magnetic.QuasiStatic.FluxTubes.Shapes.Leakage;
model QuarterSphere
"Leakage flux through the corners of a quarter sphere"
  extends BaseClasses.Leakage;
  parameter SI.Radius r=0.005 "Radius of quarter sphere"
