within Modelica.Magnetic.QuasiStatic.FundamentalWave.BasicMachines.Components;
model SymmetricPolyphaseWinding
  "Symmetric winding model coupling electrical and magnetic domain"

  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.PositivePlug
    plug_p(final m=m) "Positive plug" ;
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.NegativePlug
    plug_n(final m=m) "Negative plug" ;
  Interfaces.NegativeMagneticPort port_n "Negative complex magnetic port"
    ;
  Interfaces.PositiveMagneticPort port_p "Positive complex magnetic port"
    ;
  parameter Integer m=3 "Number of phases" ;
  parameter Boolean useHeatPort=false
    "Enable / disable (=fixed temperatures) thermal port"
    ;

  parameter SI.Resistance RRef
    "Winding resistance per phase at TRef";
  parameter SI.Temperature TRef(start=293.15)
    "Reference temperature of winding";
  parameter
    Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20
    alpha20(start=0) "Temperature coefficient of winding at 20 degC";
  final parameter SI.LinearTemperatureCoefficient alphaRef=
      Modelica.Electrical.Machines.Thermal.convertAlpha(
            alpha20,
            TRef,
            293.15) "Temperature coefficient of winding at reference temperature";
  parameter SI.Temperature TOperational(start=293.15)
    "Operational temperature of winding"
    ;
  parameter SI.Inductance Lsigma
    "Winding stray inductance per phase";
  parameter Real effectiveTurns=1 "Effective number of turns per phase";
  parameter SI.Conductance GcRef
    "Electrical reference core loss reluctance";
  SI.ComplexVoltage v[m]=plug_p.pin.v - plug_n.pin.v
    "Complex voltage";
  SI.Voltage abs_v[m]=Modelica.ComplexMath.abs(v)
    "Magnitude of complex voltage";
  SI.Angle arg_v[m]=Modelica.ComplexMath.arg(v)
    "Argument of complex voltage";
  SI.ComplexCurrent i[m]=plug_p.pin.i "Complex current";
  SI.Current abs_i[m]=Modelica.ComplexMath.abs(i)
    "Magnitude of complex current";
  SI.Angle arg_i[m]=Modelica.ComplexMath.arg(i)
    "Argument of complex current";
  SI.ActivePower P[m]={Modelica.ComplexMath.real(v[k]*
      Modelica.ComplexMath.conj(i[k])) for k in 1:m} "Active power";
  SI.ActivePower P_total=sum(P) "Total active power";
  SI.ReactivePower Q[m]={Modelica.ComplexMath.imag(v[k]*
      Modelica.ComplexMath.conj(i[k])) for k in 1:m} "Reactive power";
  SI.ReactivePower Q_total=sum(Q) "Total reactive power";
  SI.ApparentPower S[m]={Modelica.ComplexMath.abs(v[k]*
      Modelica.ComplexMath.conj(i[k])) for k in 1:m}
    "Magnitude of complex apparent power";
  SI.ApparentPower S_total=sqrt(P_total^2 + Q_total^2)
    "Magnitude of total complex apparent power";
  Real pf[m]={cos(Modelica.ComplexMath.arg(Complex(P[k], Q[k]))) for k in
          1:m} "Power factor";
  SI.ComplexMagneticPotentialDifference V_m=port_p.V_m -
      port_n.V_m "Complex magnetic potential difference";
  SI.MagneticPotentialDifference abs_V_m=
      Modelica.ComplexMath.abs(V_m)
    "Magnitude of complex magnetic potential difference";
  SI.Angle arg_V_m=Modelica.ComplexMath.arg(V_m)
    "Argument of complex magnetic potential difference";
  SI.ComplexMagneticFlux Phi=port_p.Phi
    "Complex magnetic flux";
  SI.MagneticFlux abs_Phi=
      Modelica.ComplexMath.abs(Phi)
    "Magnitude of complex magnetic flux";
  SI.Angle arg_Phi=Modelica.ComplexMath.arg(Phi)
    "Argument of complex magnetic flux";
  Magnetic.QuasiStatic.FundamentalWave.Components.PolyphaseElectroMagneticConverter
    electroMagneticConverter(final m=m, final effectiveTurns=effectiveTurns)
    "Symmetric winding"
    ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor resistor(
    final m=m,
    final useHeatPort=useHeatPort,
    final T_ref=fill(TRef, m),
    final T=fill(TOperational, m),
    R_ref=fill(RRef, m),
    final alpha_ref=fill(alphaRef, m)) "Winding resistor" ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortWinding[m] if
       useHeatPort "Heat ports of winding resistors"
    ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortCore if
    useHeatPort "Heat ports of winding resistor"
    ;
  Magnetic.QuasiStatic.FundamentalWave.Components.EddyCurrent core(final
      useHeatPort=useHeatPort, final G=(m/2)*GcRef*effectiveTurns^2)
    "Core loss model (currently eddy currents only)" ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Components.Permeance stray(final G_m(
        d=2*Lsigma/m/effectiveTurns^2, q=2*Lsigma/m/effectiveTurns^2)) "Stray permeance equivalent to ideally coupled stray inductances"
    ;
equation
  connect(resistor.heatPort, heatPortWinding) ;
  connect(core.heatPort, heatPortCore) ;
  connect(stray.port_n, core.port_n)
    ;
  connect(electroMagneticConverter.plug_p, resistor.plug_n) ;
  connect(plug_n, electroMagneticConverter.plug_n) ;
  connect(plug_p, resistor.plug_p) ;
  connect(port_p, electroMagneticConverter.port_p) ;
  connect(stray.port_p, port_p)
    ;
  connect(port_n, core.port_n) ;
  connect(electroMagneticConverter.port_n, core.port_p) 
  ;
end SymmetricPolyphaseWinding;

within Modelica.Magnetic.QuasiStatic.FundamentalWave.BasicMachines.InductionMachines;
model IM_SlipRing "Induction machine with slip ring rotor"
  parameter Integer mr(min=3) = m "Number of rotor phases" ;
  extends BaseClasses.Machine(
    Rs(start=0.03),
    Lssigma(start=3*(1 - sqrt(1 - 0.0667))/(2*pi*fsNominal)),
    final L0(d=2.0*Lm/m/effectiveStatorTurns^2, q=2.0*Lm/m/
          effectiveStatorTurns^2),
    redeclare final
      Modelica.Electrical.Machines.Thermal.InductionMachines.ThermalAmbientIMS
      thermalAmbient(final Tr=TrOperational, final mr=mr),
    redeclare final
      Modelica.Electrical.Machines.Interfaces.InductionMachines.ThermalPortIMS
      thermalPort(final mr=mr),
    redeclare final
      Modelica.Electrical.Machines.Interfaces.InductionMachines.ThermalPortIMS
      internalThermalPort(final mr=mr),
    redeclare final
      Modelica.Electrical.Machines.Interfaces.InductionMachines.PowerBalanceIMS
      powerBalance(
      final lossPowerRotorWinding=sum(rotor.resistor.resistor.LossPower),
      final lossPowerRotorCore=rotor.core.lossPower,
      final lossPowerBrush=0,
      final powerRotor=
          Modelica.Electrical.QuasiStatic.Polyphase.Functions.activePower(
                                                                 vr,
          ir)));
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.NegativePlug
    plug_rn(final m=mr) "Negative plug of rotor" ;
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.PositivePlug
    plug_rp(final m=mr) "Positive plug of rotor" ;
  parameter SI.Inductance Lm(start=3*sqrt(1 - 0.0667)/(2*pi
        *fsNominal)) "Stator main field inductance per phase" ;
  parameter SI.Inductance Lrsigma(start=3*(1 - sqrt(1 -
        0.0667))/(2*pi*fsNominal))
    "Rotor leakage inductance per phase w.r.t. rotor side"
    ;
  parameter SI.Resistance Rr(start=0.04)
    "Rotor resistance per phase w.r.t. rotor side"
    ;
  parameter SI.Temperature TrRef(start=293.15)
    "Reference temperature of rotor resistance"
    ;
  parameter
    Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20
    alpha20r(start=0)
    "Temperature coefficient of rotor resistance at 20 degC"
    ;
  parameter SI.Temperature TrOperational(start=293.15)
    "Operational temperature of rotor resistance" ;
  parameter Boolean useTurnsRatio(start=true)
    "Use TurnsRatio or calculate from locked-rotor voltage?";
  parameter Real TurnsRatio(final min=Modelica.Constants.small, start=1)
    "Effective number of stator turns / effective number of rotor turns"
    ;
  parameter SI.Voltage VsNominal(start=100)
    "Nominal stator voltage per phase"
    ;
  parameter SI.Voltage VrLockedRotor(start=100*(2*pi*
        fsNominal*Lm)/sqrt(Rs^2 + (2*pi*fsNominal*(Lm + Lssigma))^2))
    "Locked rotor voltage per phase"
    ;
  parameter Modelica.Electrical.Machines.Losses.CoreParameters
    rotorCoreParameters(
    final m=3,
    PRef=0,
    VRef(start=1) = 1,
    wRef(start=1) = 1)
    "Rotor core loss parameter record, all quantities refer to rotor side"
    ;
  output SI.ComplexVoltage vr[mr]=plug_rp.pin.v - plug_rn.pin.v
    "Complex rotor voltage";
  SI.Voltage abs_vr[mr]=Modelica.ComplexMath.abs(vr)
    "Magnitude of complex rotor voltage";
  SI.Angle arg_vr[mr]=Modelica.ComplexMath.arg(vr)
    "Argument of complex rotor voltage";
  output SI.ComplexCurrent ir[mr]=plug_rp.pin.i
    "Complex rotor current";
  SI.Current abs_ir[mr]=Modelica.ComplexMath.abs(ir)
    "Magnitude of complex rotor current";
  SI.Angle arg_ir[mr]=Modelica.ComplexMath.arg(ir)
    "Argument of complex rotor current";
  SI.ActivePower Pr[mr]={Modelica.ComplexMath.real(vr[k]*
      Modelica.ComplexMath.conj(ir[k])) for k in 1:mr}
    "Active rotor power";
  SI.ActivePower Pr_total=sum(Pr)
    "Total active rotor power";
  SI.ReactivePower Qr[mr]={Modelica.ComplexMath.imag(vr[k]*
      Modelica.ComplexMath.conj(ir[k])) for k in 1:mr}
    "Reactive rotor power";
  SI.ReactivePower Qr_total=sum(Qr)
    "Total reactive rotor power";
  SI.ApparentPower Sr[mr]={Modelica.ComplexMath.abs(vr[k]
      *Modelica.ComplexMath.conj(ir[k])) for k in 1:mr}
    "Magnitude of complex rotor apparent power";
  SI.ApparentPower Sr_total=sqrt(Pr_total^2 + Qr_total^2)
    "Magnitude of total complex rotor apparent power";
  Real pfr[m]={cos(Modelica.ComplexMath.arg(Complex(Pr[k], Qr[k]))) for k in
          1:m} "Rotor power factor";
protected
  final parameter Real internalTurnsRatio=if useTurnsRatio then
      TurnsRatio else VsNominal/VrLockedRotor*(2*pi*fsNominal*Lm)/sqrt(Rs
      ^2 + (2*pi*fsNominal*(Lm + Lssigma))^2);
public
  Components.SymmetricPolyphaseWinding rotor(
    final Lsigma=Lrsigma,
    final effectiveTurns=effectiveStatorTurns/internalTurnsRatio,
    final useHeatPort=true,
    final RRef=Rr,
    final TRef=TrRef,
    final TOperational=TrOperational,
    final GcRef=rotorCoreParameters.GcRef,
    final m=mr,
    final alpha20=alpha20r)
    "Symmetric rotor winding including resistances, zero and stray inductances and zero core losses"
    ;
equation
  connect(rotor.plug_n, plug_rn) ;
  connect(rotor.heatPortCore, internalThermalPort.heatPortRotorCore)
    ;
  connect(rotor.heatPortWinding, internalThermalPort.heatPortRotorWinding)
    ;
  connect(plug_rp, rotor.plug_p) ;
  connect(airGap.port_rn, rotor.port_p) ;
  connect(airGap.port_rp, rotor.port_n) 
  ;
end IM_SlipRing;

