block VfController "Voltage-Frequency-Controller"
  import Modelica.Constants.pi;
  parameter Integer m=3 "Number of phases" ;
  parameter SI.Angle orientation[m]=-
      Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m)
    "Orientation of phases";
  parameter SI.Voltage VNominal
    "Nominal RMS voltage per phase";
  parameter SI.Frequency fNominal "Nominal frequency";
  parameter SI.Angle BasePhase=0 "Common phase shift";
  output SI.Voltage amplitude;
  Modelica.ComplexBlocks.Interfaces.ComplexOutput y[m]
    "Complex quasi-static voltages (RMS)" ;
  Modelica.Blocks.Interfaces.RealInput u(unit="Hz") "Frequency input (Hz)"
    ;
equation

  amplitude = VNominal*(if abs(u) < fNominal then abs(u)/fNominal else 1);
  y = Modelica.ComplexMath.fromPolar(fill(amplitude, m), orientation + fill(
    BasePhase - pi/2, m))
  ;
end VfController;

within Modelica.Math;
package BooleanVectors "Library of functions operating on Boolean vectors"
 extends Modelica.Icons.Package;
function allTrue
    "Returns true, if all elements of the Boolean input vector are true ('and')"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Boolean result "= true, if all elements of b are true";
algorithm
  result := size(b,1) > 0;
  for i in 1:size(b,1) loop
     result := result and b[i];
  end for
    ;
end allTrue;
function andTrue
    "Returns true, if all elements of the Boolean input vector are true ('and')"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Boolean result "= true, if all elements of b are true";
algorithm
  result := true;
  for i in 1:size(b,1) loop
     result := result and b[i];
  end for
    ;
end andTrue;
function anyTrue
    "Returns true, if at least one element of the Boolean input vector is true ('or')"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Boolean result "= true, if at least one element of b is true";
algorithm
  result := false;
  for i in 1:size(b,1) loop
     result := result or b[i];
  end for
  ;
end anyTrue;
function countTrue "Returns the number of true elements in a Boolean vector"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Integer n "Number of true elements in b";
algorithm
  n := sum(if b[i] then 1 else 0 for i in 1:size(b, 1))
    ;
end countTrue;
function enumerate
    "Enumerates the true elements in a Boolean vector (0 for false elements)"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Integer enumerated[size(b, 1)]
      "Indices of the true elements in b (increasing order; 0 for false elements)";
  protected
  Integer count;
algorithm
    count := 1;
    for i in 1:size(b, 1) loop
      if b[i] then
        enumerated[i] := count;
        count := count + 1;
      else
        enumerated[i] := 0;
      end if;
    end for
    ;
end enumerate;
function firstTrueIndex
    "Returns the index of the first true element of a Boolean vector"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Integer index "Index of the first true element of b";
algorithm
   index :=0;
   for i in 1:size(b,1) loop
      if b[i] then
         index :=i;
         return;
      end if;
   end for
    ;
end firstTrueIndex;
function index "Returns the indices of the true elements of a Boolean vector"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Integer indices[countTrue(b)] "Indices of the true elements of b";
  protected
  Integer count;
algorithm
    count := 1;
    for i in 1:size(b, 1) loop
      if b[i] then
        indices[count] := i;
        count := count + 1;
      end if;
    end for
    ;
end index;
function oneTrue
    "Returns true, if exactly one element of the Boolean input vector is true (\"xor\")"
  extends Modelica.Icons.Function;
  input Boolean b[:] "Boolean vector";
  output Boolean result "= true, if exactly one element of b is true";
algorithm
  result := countTrue(b) == 1
  ;
end oneTrue
  ;
end BooleanVectors;

within Modelica.Math;
package FastFourierTransform
  "Library of functions for the Fast Fourier Transform (FFT)"
  extends Modelica.Icons.Package;
  import Modelica.Units.SI;
  package Examples
    "Examples demonstrating the usage of the Math.FastFourierTransform functions"
    extends Modelica.Icons.ExamplesPackage;
    model RealFFT1
      "Example demonstrating the use of an FFT calculation during simulation (and storing both amplitudes and phases on file)"
      import Modelica.Constants.pi;
      extends Modelica.Icons.Example;
      parameter SI.Frequency f_max = 4
        "Maximum frequency of interest";
      parameter SI.Frequency f_resolution = 0.2
        "Frequency resolution";
      parameter SI.Frequency f1 = 2 "Frequency of sine";
      parameter SI.Frequency f2 = 3 "Frequency of cosine";
      parameter String FFT_resultFileName = "RealFFT1_resultFFT.mat"
        "File where FFT will be stored as [f,A,Phi], with f in [Hz] and A the amplitudes and Phi the phases in [rad]";
      final parameter Integer nfi = max(1,min(integer(ceil(f_max/f_resolution))+1,nf))
        "Number of frequency points of the interested frequency range (only up to f_max)";
      final parameter SI.Frequency fi[nfi](each fixed=false)
        "FFT frequencies of interested frequency points";
      Real y(final start=0, final fixed=true)
        "Signal from which FFT is computed";
      final output Real Ai[nfi](each start=0, each fixed=true)
        "FFT amplitudes of interested frequency points";
      final output Real Phii[nfi](each start=0, each fixed=true)
        "FFT phases of interested frequency points";
      output Integer info(final start=0, final fixed=true)
        "Information flag from FFT computation; = 0: FFT successfully computed";
    protected
      parameter Integer ns = realFFTsamplePoints(f_max, f_resolution, f_max_factor=5);
      parameter SI.Frequency f_max_FFT = f_resolution*div(ns, 2)
        "Maximum frequency used by FFT";
      parameter Integer nf = div(ns,2) + 1 "Number of frequency points";
      parameter SI.Time Ts = 1/(2*f_max_FFT) "Sample period";
      parameter SI.Time T = (ns - 1)*Ts
        "Simulation time for one FFT calculation";
      Integer iTick(start=0, fixed=true);
      Real y_buf[ns](start=vector([6.5; fill(0, ns - 1)]), each fixed=true);
    initial equation
      for i in 1:nfi loop
         fi[i] = (i-1)*f_resolution;
      end for;
    algorithm
      when sample(0,Ts) then
         iTick :=pre(iTick) + 1;
         y := 5 + 3*sin(2*pi*f1*time) + 1.5*cos(2*pi*f2*time);
         if iTick >= 1 and iTick <= ns then
            y_buf[iTick] := y;
         end if;
         if iTick == ns then
           (info,Ai,Phii) := realFFT(y_buf, nfi);
           Modelica.Math.FastFourierTransform.realFFTwriteToFile(time,FFT_resultFileName,f_max,Ai,Phii);
         end if;
      end when;

within Modelica.Math;
function isPowerOf2 "Determine if the integer input is a power of 2"
  extends Modelica.Icons.Function;
  input Integer i(min=1) "Integer scalar";
  output Boolean result "= true, if integer scalar is a power of 2";
algorithm
  assert(i>=1, "Integer input to isPowerOf2 has to be >= 1");
  result := i == 2^integer(log(i)/log(2)+0.5)
  ;
end isPowerOf2;

within Modelica.Math;
function wrapAngle "Wrap angle to interval ]-pi,pi] or [0,2*pi["
  extends Modelica.Math.Icons.AxisCenter;
  import Modelica.Constants.pi;
  input Modelica.Units.SI.Angle u "Input angle";
  input Boolean positiveRange=false "Use only positive output range, if true";
  output Modelica.Units.SI.Angle y "Wrapped output angle";
algorithm
  y :=mod(u, 2*pi);
  if y>pi and not positiveRange then
    y := y - 2*pi;
  end if
  ;
end wrapAngle;

