  Modelica.Mechanics.MultiBody.Joints.Internal.RollingConstraintVerticalWheel rolling2(radius=radius, lateralSlidingConstraint=false) ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a axis1
