equation
 Frames.angularVelocity2(R_b) = Frames.resolve2(R_b,Frames.angularVelocity1(R_a)) + w_rel_b
  ;
end InitAngularVelocity;

within Modelica.Mechanics.MultiBody.Joints.Internal;
