  import Modelica.Units.Conversions.to_unit1;
  Interfaces.Frame_a frame_a
    "Coordinate system a (all shape definition vectors are resolved in this frame)"
     ;
  Interfaces.Frame_b frame_b "Coordinate system b"
     ;
