  connect(heatFlow1.y,prescribedHeatFlow1. Q_flow)
    ;
  connect(thermalConductance2.y, convection2.Gc)
    ;
  connect(thermalConductance1.y, Convection1.Gc)
    ;
  connect(pipe1.heatPort, Convection1.fluid) ;
