    "Temperature of element";
  SI.TemperatureSlope der_T(start=0)
    "Time derivative of temperature (= der(T))";
  Interfaces.HeatPort_a port ;
equation
  T = port.T;
  der_T = der(T);
  C*der(T) = port.Q_flow
  ;
end HeatCapacitor;

